VN.registerScenario("ch03", [

  // ===== シーン1: 御前にて (EP33) =====
  { label: "royal_report" },
  { chapter: { no: "第三章", title: "魔王編 前編" } },
  { bg: "royal_castle" },
  { bgm: "holy" },
  { text: "｜謁見《えっけん》の間、王座の御前。" },
  { text: "俺とクロセル、そしてアカツキとゲーテの四人は並んで立っていた。今は丁度、アカツキが今回の任務の報告を終えた所。" },
  { text: "俺のような素人が下手に口出すより、こういうのは慣れた人間に任せた方が良い物だろう。それは他の皆も承知のようで、先程から喋っているのは王とアカツキだけである。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "serious" },
    { slot: "center", id: "raon", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "以上が、今回の任務の報告となります" },
  { name: "国王", who: "raon", expr: "normal", text: "……そうか、大義であった" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "決して少なくはない犠牲はありましたが、結果として｜魔杖《まじょう》の奪還には成功しました。今後は予定通り｜魔杖《まじょう》とその主人を王城で監視、保護しつつ、一月先に起こるであろう魔王の復活に対策を練ることを進言致します" },
  { chara: { slot: "left", id: "goethe", expr: "normal" } },
  { name: "国王", who: "raon", expr: "smile", text: "ゲーテ・フォルモントは大任ご苦労であった、貴殿には後日然るべき褒美を与えよう" },
  { name: "ゲーテ", who: "goethe", expr: "normal", text: "有り難き幸せで御座います、陛下" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "国王", who: "raon", expr: "normal", text: "｜魔杖《まじょう》クロセルとその主人、ヤマトに関してだが……二人には各自部屋を用意し、王城に住まわせる事を許可する" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "すまん、陛下。今回も少し提案があるんだが、発言の許可を貰えるか?" },
  { name: "国王", who: "raon", expr: "smile", text: "ははは、余を相手に随分と砕けた態度で出て来たな、だが貴殿の活躍もアカツキの言葉で確かに聞いておる。構わん、言ってみろ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "一月先の魔王の復活、それの対処に俺とクロセルを使って欲しい" },
  { name: "国王", who: "raon", expr: "normal", text: "ほう、何故だ?貴殿に国を守る義理はないはずだが……正義感か?或いは褒美が目当てか?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "単に俺自身が自分の平和な日常を守りたいだけだ、国を救うだとか世界を救うだとかは、おまけに過ぎない" },
  { chara: { slot: "right", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我からもお願いしよう、これでも下手な魔術師よりはずっと戦力になるはずだ" },
  { name: "国王", who: "raon", expr: "normal", text: "ふむ、確かに｜魔杖《まじょう》クロセルは王国一の戦力として数えられる程の存在だ、その力に頼るのは悪くない相談だと言える" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なら……!" },
  { name: "国王", who: "raon", expr: "normal", text: "そう急かずとも、｜魔杖《まじょう》とその主人が魔王復活の件に関与することなら許可しよう" },
  { chara: { slot: "right", id: "yamato", expr: "smile" } },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "助かる、俺も期待を裏切らない様に善処させて貰おう" },
  { name: "国王", who: "raon", expr: "angry", text: "勘違いするな、｜魔杖《まじょう》に期待はせど貴殿に期待はしていない、精々足を引っ張らないようにするんだな" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……あぁ、そうだな、気を付ける" },
  { text: "なんとか｜此方《こちら》の要望は通すことが出来た。しかし、何故か王は俺に対して良い印象を持っていないらしい。" },
  { text: "やはりディザビリティとは行かずとも、才能を持っていない人間というのは世間的にこういう扱いを受けるのが普通なのだろうか。だとすれば何とも悔しい。次の機会で大きな成果を挙げて今度こそあの王を見返してやろう。" },
  { text: "……最も、こう考えさせる為に敢えて挑発的な言葉を選んだのかもしれないが。もしそうならば俺は完全に術中に｜嵌《は》まったと言える。悔しい物は悔しいのだ。" },
  { name: "国王", who: "raon", expr: "normal", text: "話は以上か?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、それと勇者に関してだが……どうも｜魔杖《まじょう》を敵視してるらしい、勘違いを解いてやって貰えるか、俺達としても別にあいつとはやり合いたくない" },
  { text: "だって面倒だもの、という言葉は飲み込む。" },
  { name: "国王", who: "raon", expr: "smile", text: "そうだな……勇者ニコラスに関しては余に任せておけ、下手な気を起こすことが無いように良く言い聞かせておこう" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "助かる、それと無礼で悪かった、です。すいません" },
  { name: "国王", who: "raon", expr: "smile", text: "ははは!過ぎたことだ、もう良い、話が済んだのなら下がりたまえ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさん、行きましょう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ" },
  { text: "アカツキは王座に向かって一礼すると、そのままくるりと｜踵《きびす》を返し、俺の耳元にそう囁きながら｜謁見《えっけん》の間を後にする。それに続いてゲーテもその場を離れ、それに習うように俺とクロセルもその場から退出した。" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { bgm: "daily" },
  { chara: [
    { slot: "left", id: "crocell", expr: "normal" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "akatsuki", expr: "smile" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "いやー……やっぱあの空気は苦手だな" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人はあんな奴相手にビビっておるのか?我の前では強気な癖に" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "お前には威厳って物が無いからな、少しはあの王を見習えよ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "な……何故だ……何故あの王に威厳があって我には無いのだ……解せぬ……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁ……見た目があれだからどんなに頑張っても威張れない気もするが……" },
  { text: "と思わず小声で呟く。どうやら本人には聞こえていないようだ。助かった。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そして、俺達は晴れて王城での暮らしを手に入れた訳だが" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "それでも、監視が無いと王都には出られないんだろう?息が詰まる生活が待っていそうだが……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "監視と言っても私が同行するだけですから、そこまで気負わなくても良いと思いますよ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そう言えば引き続き俺達のお目付け役を任されたんだったな、王も人使いが荒いよな、傷は大丈夫なのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "えぇ、クロセルさんの処置が良かったみたいで、もう殆ど回復しました" },
  { text: "今後のことを相談していると、横からアカツキが会話に入ってくる。彼女のこれからの仕事は俺とクロセル二人分の監視だ。最も、俺はクロセルから離れるつもりは無い為に、三人一緒が基本的な行動になるだろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "常に三人一緒……とは思った物の……クロセル、俺が｜邪魔《じゃま》だったらいつでも言ってくれて良いからな、女同士で話したいこともあるだろうし" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "アカツキ!?これはどういうことだ!?ご主人が優しいぞ……?何か悪い物でも食べたのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ヤマトさんは元から優しい方ですよ?ね?" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うるさいぞ、それとアカツキ!俺は優しくなんか無いからな?" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "素直じゃないですねぇ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "言われてみれば確かに……ご主人は元々優しい男だったな……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "止めてくれよ……" },
  { text: "呆れて溜息を吐きながら、頭を抱える。だがそんな苦悩も心地よい、これがいつもの俺達の調子だ。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そんなことより……アカツキとご主人の距離が前より近付いてないか……?我が居ない間に一体何があったというのだ……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば、クロセルには言ってなかったな。どうやらアカツキは俺と同じ世界から来たらしい、その因縁があるのもあって色々と、な" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はい、確かに同郷の人間相手だと話しやすいですからね" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "なるほど……そんな事があったのか" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "これも良い機会だ、アカツキの居た地球と俺の居た地球、それが本当に同じ物か確かめる為にも少し昔話でもしないか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "良いですね、私もヤマトさんがこの世界に来る前に何をしてたのか気になりますし" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "……あんま面白い話でも無いんだがな、まぁ言い出しっぺの俺が嫌がる訳にもいかないか" },
  { text: "どうせいつかは話すつもりだった話だ。それが少し早まった所で別に不都合は無いだろう。" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "それじゃあ私の部屋でお話しましょうか、準備もあるので十五分後に私の部屋で、良いですね?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、分かった。それまでクロセル連れて適当に散歩してるよ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "それでは、また後で" },
  { text: "そう言い残すと、アカツキはすたすたと俺達の前を去っていく。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人の昔話か、我も実に気になるな" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "本当に面白い話じゃないんだって……｜寧《むし》ろ聞いてて嫌になるかもしれんぞ?" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "そうだとしても、我はありのままのご主人を受け入れるぞ、それに我の過去も余り褒められた物では無いのでな" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そう言えばそうだな、気付かなかったが、俺達は似た者同士って訳だ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "そうだぞ、ははは、今更気付いたのだな" },
  { text: "そんな風にクロセルと雑談をして、俺達は時間を潰した。そして時刻は十五分後。俺とクロセルにアカツキを混じえた俺達三人は約束通り、アカツキの部屋で集まることとなった。" },

  // ===== シーン2: 過去 (EP34) =====
  { label: "past_confession" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { text: "場所はアカツキの執務室。机の脇に小椅子を並べ、俺達三人はそこに座していた。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それじゃ早速話し始めるとするか" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "勿論ヤマトさんが先ですよね、言い出しっぺですし" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、分かってる。んじゃまず俺が居た世界に関してだが……" },
  { text: "俺の話も、大凡は当たり障りの無い話だった。" },
  { text: "俺は自分が\"地球\"と称される惑星から来た事を語った。その世界では才能や魔術なんて物はなく、人類史は科学によって発達して来たということ。科学の賜物で、この世界より遥かに高い技術を持った世界ということ。そして、その世界の暦で言う2018年から来たということ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "とまぁ、此処までが俺の世界の話だ、アカツキ、何か質問はあるか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "やっぱり私より少し先の未来から来たんですね、私は西暦2014年にこの世界に来たので" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……あれ、おかしいな、それだと計算が合わなく無いか?アカツキはシンシアに来てから今年で五年目だろう?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "確かに本来なら今現在地球は2019年の筈ですが……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ふむ、地球とシンシアの暦では多少の誤差があるのかもしれんぞ?ヤマトも此方に来た直後は此方の時間感覚に慣れない様子だった" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なるほど、それもそうだな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それで、ヤマトさん自身が転生した経緯をお聞かせ願えますか?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "もう覚悟は決めてるんだから急かすなよ……" },
  { text: "面白くもない話だというのに、耳を澄ませて聞き逃すまいとしている二人の様子を見て、思わず溜息を吐いた。そして、俺は重い口を開いてゆっくりと話し出す。" },
  { fade: "out" },
  { hide: "all" },
  { bg: "japan_night" },
  { bgm: "mystery2" },
  { pov: { name: "ヤマト", color: "#BDC3C7" } },
  { text: "――回想・前世の地球――" },
  { fade: "in" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "俺の前世は俗に言う｜咎人《とがびと》……悪い人間と手を取り合って弱者を虐げる、地球ではヤンキーとか呼ばれる人間の類だった" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "話の腰を折って悪いんですけど、ヤマトさんって幾つなんです……?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "18だ、お前は?" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "女性にそれを聞くんですか……?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "冗談だ、見てくれで大体分かるから答えなくていい" },
  { text: "服装と仕草で大人びていると錯覚しがちだが、良く見てみればアカツキも俺とそう変わらない年齢だということが分かる。根拠は勘だ、俺のも割と当たる。" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "うーん……それはそれで困るんですが……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いいから黙って聞いてろ、んで俺が此処に来た経緯だが……まず、俺達は薬に手を出してたんだ、無論非合法のな。入手経路はモノホンのヤクザから奪い取ってた。それほどに俺達のグループは力があったんだ、武装した大人とやり合える程度にな" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "もしかして……ヤマトさんはそのグループの……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そう、頭を務めてた。霧雨組って名乗ってな、そりゃ色々やったさ。女も金も暴力も手を出した。犯して奪って殺したんだ。それらは全部俺の命令でやったことだ、やらされた訳じゃない。俺はそれを楽しんでやっていた、愉快犯って奴だな" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "そんなの……今のヤマトさんからは想像出来ません……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "だろうな。我ながら丸くなったとは思ってる。それもこれも、神に自慢の拳を奪われて骨抜きにされたってのが正しいか" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "傷害のディザビリティが無ければ、ご主人は前の世界と同じような生き方をするつもりだったのか?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ぶっちゃければ、その通りだ。もし神が俺に力を与えていたら、俺は前と同じ、｜悪逆非道《あくぎゃくひどう》を尽くす人間にして魔王のような存在と化していただろう" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "なら、ディザビリティのお陰で今のヤマトさんが居ると言っても過言ではないんですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だな、取り敢えず話に戻る。俺達霧雨組は色んな場所のヤクザから薬を奪って、それを高値で取引したり女に使ったり、好き勝手やってた訳だ" },
  { text: "一呼吸置く。あの時の事は思い出すだけで腹立たしく、悔しい。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "だがいつまでも上手く行くわけがなかった、俺の右腕であり親友でもある奴がヘマをしてな、中国のマフィアに捕まっちまったんだ" },
  { text: "もし過去をやり直せるとしたら、俺はあの時に戻りたい。もしそれが叶うなら、何度でもやり直して、絶対にあいつを救い出してやる。" },
  { text: "が、そんな奇跡が俺に起こる事は無かった。起きた奇跡は二度目の人生、それも拳を奪われての第二の生だ。本当に笑える。障害を持ったまま第二の人生なんか俺に与えられても何も成すことなど出来ないというのに。" },
  { text: "今だってクロセルに頼り切りなのだから。俺の存在価値なんて、この世界じゃほんの少しも無い。だがしかし、前の人生も似たような物か。俺のような社会の｜癌《がん》に存在価値なんて無かったのだろう。結局変わらないのだ。一度目も、二度目も。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "霧雨組の総意は奴を見捨てる事だった、俺も一度はその判断をした。だが……俺は諦めきれなかったんだ、奴を助ける為に、奴等の根城に単独で乗り込んだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "なるほど……" },
  { se: "gunshot" },
  { fx: "flash" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "後はもう分かったな、俺一人でどうこう出来る筈もなく、親友の前で｜鉛玉《なまりだま》を撃ち込まれて｜お陀仏《おだぶつ》だ。冷静さを欠かなければもっと上手くやれてた筈なんだけどな" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "つまり、ヤマトさんは一度死んでからこの世界に転生してきたという訳ですね?" },
  { fade: "out" },
  { hide: "all" },
  { pov: null },
  { bg: "royal_castle", instant: true },
  { bgm: "daily" },
  { fade: "in" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだが……お前は違うのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、私はその……自ら転生したんです" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "分からん、最初から説明してくれ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "分かりました、私が西暦2014年から来たという事は言いましたね?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、聞いたな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "当時高校生だった私は、特に特筆する特徴も無い、ある女子校に通っていました" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……年齢割れたな" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "うるさいですよ。それで、その七不思議の一つに、\"異世界に行く方法がある\"という物がありまして……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おかしな話だな、その方法で本当に異世界に行ったなら、誰がその事実を知って言い伝えたんだ?この手の怪談だと良くある矛盾だが" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "もしかしたら……異世界に\"行って帰ってきた\"人物が過去に居たのかもしれませんね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "その学校はどの位の歴史があるんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "創立120年と少しだった筈です、ありえない話では無いですよね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だな、それだけあれば異世界に行って帰ってきた人物が居ないとも限らない" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "それで、私は興味本位でその七不思議を試してみることにしました" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "本当に興味本位だったのか?何か向こうでの暮らしで嫌なことでもあったんじゃ……" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "それを聞くのはデリカシーが無いって物ですよ、ヤマトさん" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……言いたくないなら別に良い、話を続けてくれ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "その異世界に行く方法なんですが、学校の近くにある活火山の火口に飛び込むという物でした" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……冗談だろ?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "本当です、そしてこの話には続きがあって……もしそれが成功したら、その火山が噴火して、異世界に行った人物が最も憎んでいる人物を殺す……という物なんです" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "突然怪談らしくなったな……" },
  { name: "アカツキ", who: "akatsuki", expr: "angry", text: "まぁぶっちゃければ、異世界に行くのは手段に過ぎなくて、心底殺したい人物が居たんです。私だって人間ですから" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "不確かな怪談に従って火口に身投げ自殺してまで、他人を殺すとか……凄い執念というか狂気を感じるな" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "はい、私も今思えば無謀なことをした物だと思います" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ……納得は出来た、2014年ってのも｜辻褄《つじつま》が合う" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それは良かったです、あわよくば復讐の方も成功していることを祈りましょうか" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "目が怖いぞ……アカツキ……" },
  { text: "俺だけじゃなく、アカツキもかなりの訳有りだったらしい。というかぶっちゃけかなり怖い。絶対に敵には回したくない女だ。色々と気になることはあるが……余り深く詮索すると俺も身も危うそうである。止めておこう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "その火山が地球からシンシアを繋ぐゲートなのだとすれば、その逆であるシンシアから地球に繋がるゲートも何処かにあるのだろうか" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ふむ、可能性としては有り得るだろう、シンシアにも幾つか活火山がある、帰りたくなったら試してみるのも手だな" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "試して失敗したら死ぬから誰もやらないだろ……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "アカツキはそれをやったんだ、ご主人も男らしいとこを見せんか" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "男らしいとか女々しいとかそういう次元の話じゃねぇから!そういうお前は出来るのかよ!" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "火山如き、我の魔術を使えば泳ぐことすら容易よ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "お前に聞いた俺が馬鹿だった……" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "と……兎に角!以上が私がこの世界に来た経緯です、質問はありますか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "火口に落ちた時に一度死ななかったのか?そのままの身体でシンシアに?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね、落ちてる途中で一気に視界が変わって、気が付けばシンシアに降り立ってました" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "その場所は?俺はアランの森の湖だったが" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "王都の正面にある草原です、直ぐに通り掛かった国王に拾われたので殆ど苦労はしませんでしたね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "やっぱり俺とアカツキの転生は、色々と｜齟齬《そご》があるな……参考にはなったが、いまいち繋がりが見えない" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね……そう言えば、私の才能は恐らく世界に降り立った直後から持っていたみたいなんですが、ヤマトさんはどうでした?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "同じだ、最初から『傷害』のディザビリティを持ってた" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "才能がこの世界に来た時に決まるとしたら、そこには神の意志の介入があるのか、それともシステムに則ってランダムに与えられた物なのか、此処が気になる所ですね……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "同感だ、だが俺は前者の説を推すな。俺が傷害のディザビリティを与えられるとか……偶然にしては出来すぎている" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "確かに、ヤマトさんと出会ってからは私もそう思うようになりました。神様……一度会ってみたい物ですね" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふむ、では会いに行くか?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "何言ってんだよクロセル……そう簡単に神に会えるわけ……会えるのか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そもそも神とは人の身に転生して普段は地上に居る存在だからな、知らなかったのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "私も初耳です……勇者や魔王に関しては知識がありましたが、まさか神が普通に地上を歩き回っているとは……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "と言っても、基本的には教国の保護下にあるから会うのは簡単では無いがな、見るだけなら現地に行くだけだから簡単だぞ?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "教国……ってのはあれか、王国に帝国と続いて、また新しい国か" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "この世界は五つの領土に分かれてますからね、教国はその中でも一番小さな国ですが、神を強く信仰しているのもあって、民衆に対する影響力、発言力だけならトップレベルと言っても良いです" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私の知ってるのはこの程度で……本当に神様をお抱えになってるというのは初耳でした" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そもそも何で700年眠ってたクロセルが知ってるんだよ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "教国は700年前にもあったからな、いやはや、あれは強敵だった" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "魔王時代に攻め滅ぼそうとしたのかよ……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "我ではないぞ?我の元主人が攻め滅ぼそうとしていたのだ、我はそれに従って加担したまで" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "結局は同じだろ、んで教国が破れなかったのは何でなんだ?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "文字通り、神の加護を与えられた国故に、魔の者が近付くと力を奪われるのだ、故に攻め滅ぼすことは出来なかった" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "祝福と来て次が神の加護か……魔王以上に何でもありな奴なんだろうな、神ってのは" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "そりゃ神なのだから当たり前だろう、世界を作った唯一神だぞ?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そんな神様が普通に国に抱えられて、生活していると聞くと……なんとも言えない違和感を感じますね……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……だな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……神が手を貸してくれたら魔王なんて一発なんじゃないか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "それはどうだろうな、我が思うに……恐らく魔王は神が作り出した存在。神が魔王をやろうと思えば簡単なのだろうが、実際にそうした例は過去に一度も無い。つまり、神が必ずしも人類側の味方であるとは限らないという訳だな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "神が魔王を作ったって……いやそりゃそうか、この世界の万物は神が作り出してるんだもんな……ん、てことは" },
  { text: "俺やアカツキのような\"外から来た者\"を例外として、他全ての物質から生物、法則やシステムに至るまで、神が作り出した物なのだとしたら。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "神は何で魔王や魔物を作ったんだ……?或いはその二つは俺達と同じ\"外から来た者\"なのか?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "さぁ、そこに関しては神本人に聞いてみる他無いだろう、我のも仮説に過ぎないのでな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いつか会ってみたいな、神。そして文句の一つでも言ってやりたいな、神" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "そこは呼び捨てじゃなくて神様って言いましょうよ……" },
  { text: "創造神と聞いて、やはり超常的な存在なのかと思えば、普通に地上に生を受けて活動しているというのだ。これで違和感を覚えない方がおかしいだろう。" },
  { text: "そんな得体の知れない\"神\"という存在について語り合った末。気が付けば日も傾き、アカツキも仕事があるとのことで、今日の所は解散としたのであった。" },

  // ===== シーン3: 特訓とエル (EP35〜36) =====
  { label: "training_el" },
  { fade: "out" },
  { hide: "all" },
  { bg: "royal_castle_corridor", instant: true },
  { fade: "in" },
  { text: "翌日、王城の廊下。どうやら先刻、勇者の身柄が解放されたらしい。約束通り王が説得してくれたようで、クロセルを敵視するような真似は今の所していないようだ。だが、俺は聖剣を失くした件を問い詰められていた。" },
  { chara: [
    { slot: "left", id: "nicholas", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "あ?聖剣?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あー、なんだ" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "そうだ!僕は覚えているからな?君が僕の聖剣を使って皇帝と戦っていたのを!" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あーそうだな……あの時は剣があって助かった、感謝してる" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "そんなことより!僕の大事な聖剣は何処へいったんだい!?" },
  { text: "約束通り王が説得してくれたようで、クロセルを敵視するような真似は今の所していないようだが、まずいことになった。" },
  { text: "俺は聖剣を借りた後に、剣術がディザビリティとなり触れなくなった為、剣を持って帰って来れていないのだ。正直に置いてきたと言うべきか、適当に誤魔化すか、どうしたものか。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あーあの聖剣だけどな、実は……" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "実は……?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あの後大英雄キュリオスの幽霊が現れて『聖剣は返して貰う』と言い残して剣を奪い去っていったんだ。俺は必死でそれを止めたのだが……幽霊相手に抵抗虚しく、剣は持ち去られてしまったんだ……" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "そうだったのか!僕も会いたかったな……大英雄キュリオス" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、格好良かったぞ、大英雄キュリオス、凄いんだな、大英雄キュリオス" },
  { text: "苦し紛れの誤魔化しが通用してしまった。解せない。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "悪かったよ、だが大英雄キュリオスもお前を称賛してたぞ、『勇者ニコラスの剣捌き実に見事であった、彼であれば聖剣の力を借りずとも魔王を打倒してくれるだろう』ってな" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "大英雄キュリオス様がそんなことを!?本当に!?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "本当だ、だから此処は大英雄キュリオスに免じて聖剣のことは忘れてくれないか?な?" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "うむむ……あの聖剣は黒金貨一枚もしたのだが……大英雄キュリオス様が持ち去っていったなら仕方ない……か" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "残念だったな、俺も悔しいよ" },
  { text: "兎も角、勇者が馬鹿で助かった。こんな奴が祝福の勇者で良いのかと、相変わらず心配になるが。" },
  { hide: "all" },
  { text: "そんな心にも無いことを並べながら、そそくさと勇者の前を立ち去る。俺も知らずの内に気が急いていたのだろう。慌てて早足で歩いていた俺は、正面から歩いて来る一人の使用人に気付かず、そのままぶつかってしまう。" },
  { fx: "shake" },
  { chara: [
    { slot: "left", id: "el", expr: "surprised" },
    { slot: "right", id: "yamato", expr: "surprised" },
  ] },
  { text: "俺の胸にどん、と鈍い衝撃が来る。痛くはないが、相手は頭をぶつけた訳だ。大丈夫だろうかと、一歩｜後退《あとず》りして顔を伺う。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "っと、すまんな、大丈夫か?" },
  { name: "？？？", who: "el", expr: "surprised", text: "っ……あっ……此方こそ、失礼しました" },
  { text: "ぶつかった使用人は澄んだ青色の髪をした、美少女であった。率直に可愛いと思う。使用人としての正装であるメイド服も相まって、思わず見惚れてしまう程だ。" },
  { text: "見た目だけなら、クロセルと良い勝負だろう。強いて言えば、クロセルより大人しい印象を覚える。" },
  { text: "例えるならそれはガラスの陶器。美しい器でありながら、扱いを間違えれば、簡単に割れてしまいそうな、そんな｜儚《はかな》さを覚える。" },
  { name: "青髪のメイド", who: "el", expr: "normal", text: "あ……あの……どうかしましたか?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "ん……あぁ、君が可愛くて思わず見惚れてた。仕事の｜邪魔《じゃま》して悪かったな" },
  { name: "青髪のメイド", who: "el", expr: "blush", text: "いえ……そんな……私には勿体無いお言葉です……" },
  { text: "ぺこぺこと頭を下げ、道の脇へと移動する。そんな小さな仕草でさえ目を惹かれる。" },
  { text: "とん、と背中を突かれる。振り向いてみれば、そこにはクロセルが居た。" },
  { chara: { slot: "center", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "何を他の女と戯れている、早く行くぞ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なんだよ……妬いてるのか?" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "な訳あるか!そもそも勇者と二人で話すからと言って離れたというのに、何を女にうつつを抜かして時間を掛けている!" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "別に良いだろ、たまには" },
  { name: "青髪のメイド", who: "el", expr: "sad", text: "あっあの……私は失礼しても?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、変な目で見て悪かったな、じゃあな" },
  { name: "青髪のメイド", who: "el", expr: "normal", text: "はい……では失礼します" },
  { hide: "left" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人……目付きがいやらしいぞ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "隠す気なんて更々無いからな、あの使用人に目を惹かれるのは事実だ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そんな胸を張って言われても……困るのだが……" },
  { text: "使用人の少女が立ち去っていく背を見送りながら、馬鹿正直に思ったことを言い放つ。何故か不満そうなクロセルを相手に、解せないと首を傾げながら、再び俺は歩き出した。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……名前聞いとけば良かったな" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そんなに名残惜しいのか?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そりゃなぁ……こっちの世界に来てからずっと禁欲してるんだ、欲求不満なんだよ" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "……折角添い寝しているというのに……ご主人は我に手を出す気は無いのか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なんか言ったか?" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "別に何も……" },
  { text: "小さな声で何か言っていたかと思えば、不機嫌そうにそう吐き捨てると、そのままそっぽを向かれてしまった。｜魔杖《まじょう》の心というのも気難しい物だ。それに対してティアのような子供は素直で良い。ああいう素直な奴の方が俺としては相手していて楽だ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "んで、勇者のせいで｜邪魔《じゃま》が入ったが……何をするんだったか" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "鈍った身体を鍛えたいと言っていたな、その為に中庭に行くんだろう?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、そうだったな、完全に忘れてた" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "全くご主人は……" },
  { text: "勇者と少女のせいで色々と頭から抜け落ちていたらしい。そのまま王城を歩き回り、やがて馴染みある中庭へと出る。" },
  { fade: "out" },
  { hide: "all" },
  { bg: "royal_castle" },
  { fade: "in" },
  { text: "あれ以来、俺とクロセルは中庭で特訓の日々を続けていた。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "angry" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "serious", text: "そもそも思うのだが、ご主人が戦えなくとも我が戦えば良いのでは?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "前回の例があるだろ、万が一に片方が戦闘不能になってもフォローが効けば何とかなる" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "確かにそうだな……それでご主人が満足するというのなら我は存分に付き合おうぞ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "付け焼き刃になるが、身体さえ出来てれば\"例のあれ\"で無理は効くからな、暫くは身体作りに付き合ってくれ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "あれは代償が大きすぎる、余り使って欲しくは無いのだがな……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "大丈夫、あれは四の五の言ってられない時になった時の奥の手だ、死ぬよりはマシだからな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "それじゃあ早速、何処からでも掛かってくるが良い" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "お手柔らかに頼むよ" },
  { text: "そう告げると、両拳を胸の前で構え、一気に踏み込む。遠慮は要らない。俺に手加減の必要は無いのだ。" },
  { text: "クロセルが詠唱を開始する。それが終わる前に、腹に拳を叩き込もうとする……が、遅い。これでは間に合わない。" },
  { fx: "shake" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "甘いぞご主人!" },
  { text: "詠唱を終え、彼女の身体は青いオーラで包まれる。これは恐らく、変異種討伐の際に見た強化魔術だろう。俺の拳はクロセルに届くこと無く、カウンターの拳が俺の腹に叩き込まれる。" },
  { text: "強化魔術を使った状態で本当に拳が当たれば俺の命など簡単に散ってしまう。故にクロセルの攻撃は見事な寸止めだ。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "やっぱ、届かないな……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "そう簡単に一本取られては我の面子も潰れるのでな、此方も手加減はせんぞ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "はは……そう来なくっちゃな" },
  { text: "その後、俺は何度もクロセルと拳を交えた。しかし、俺の拳が彼女に届くことは、物の見事に一度も無かった。" },
  { text: "そして、日は暮れる。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "今日の所は……この辺に……しとくか……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そうだな、ご主人……大丈夫か?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "いやー見事に全部避けられたな……完敗だよ……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "全く、無茶しおって……辛いなら途中で止めても良い物を……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "負けっぱなしってのは悔しいからな……結局、最後まで一度も勝てなかったが……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "明日もやるのか?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、ティアが来ない日は基本的に特訓になるな、｜猶予《ゆうよ》は一ヶ月しか無いんだ……それまでに最低限の戦闘技術は身に付けないといけない……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我の立場からすれば、止めるべきなのだが……ご主人が覚悟を決めたと言うのなら我も付き合おうではないか" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "助かる、明日も宜しくな……その前に、俺は少し……疲れ……た" },
  { text: "｜満身創痍《まんしんそうい》の身体で、ふらふらと歩く。消耗したのは体力だけなのだが、それでも少し無茶し過ぎたようだ。思わず倒れそうになる身体を、横からクロセルが支えてくる。そのまま俺を支えて歩いてくれるようだ。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "助かる、ありがとな" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我はご主人の下僕だからな、この程度は当然の事だ" },
  { text: "胸を張ってそう言うクロセル。本当にこいつには感謝してもしきれない。俺達二人はそのまま部屋に帰ると、俺はベッドに倒れ込み、そのまま泥沼に沈むかのように深い深い眠りに落ちた。" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { text: "そんな特訓の日々にも、少しだけ変化があった。アカツキに頼んで、例の使用人には俺の世話をさせている。忠実で仕事熱心、おまけに可愛いと来た。文句の付け所は無い。今日はそれに加えてティアも遊びに来て、俺は四人の女に囲まれることになった。" },
  { chara: [
    { slot: "left", id: "el", expr: "normal" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "crocell", expr: "normal" },
  ] },
  { name: "青髪のメイド", who: "el", expr: "normal", text: "お待たせしました、ヤマト様" },
  { name: "ティア", who: "tia", expr: "sad", text: "折角お庭に来たのに……ヤマトは遊んでくれないの?" },
  { chara: { slot: "left", id: "akatsuki", expr: "sad" } },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "言われた通りに手配はしたけど……これで良いの?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "うん、これだ……実にグレイトだぞ、アカツキ" },
  { chara: { slot: "right", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", expr: "sad", text: "全く、ご主人は一体何人の女性を侍らせるつもりなのか……我は複雑だぞ……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "一人でも多く見てくれる人が居た方が頑張れるだろ?" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "それでもこれは……ヤマトさんの趣味を疑いますよ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "うるさいなぁ……たまには良いだろ" },
  { text: "なんとも賑やかだ。女三人寄れば姦しいって奴だろうか。" },
  { chara: [
    { slot: "left", id: "el", expr: "normal" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "と言っても、俺が負け続ける様子を見るのも暇だろうし、アカツキと君はティアの相手を……そう言えば君の名前を聞いてなかったな、名前はなんだ?" },
  { name: "エル", who: "el", expr: "troubled", text: "エル・シュルツヴェールです……" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "オーケー、んじゃエルとアカツキはティアの相手任せたぞ" },
  { chara: { slot: "left", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "私はヤマトさんとクロセルさんのお目付け役なんですが……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "目に届く範囲に居れば大丈夫だって、何も中庭から塀を飛び越えて王城から出ようだなんて考えない……よな?クロセル" },
  { chara: { slot: "right", id: "crocell", expr: "sad" } },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人は我をなんだと思っているのだ……" },
  { hide: "all" },
  { text: "という訳で、ティアの相手をアカツキとエルに任せると、俺とクロセルは特訓に取り組んだ。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "angry" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ご主人!良く動きを見るのだ!本当の意味で隙の無い攻撃など存在しない!それを見付け出し、確実に点くのだ!" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "んな事は、分かってる!" },
  { text: "そんな言葉を交わしつつ、クロセルと肉弾戦を続ける。" },
  { text: "俺の方は防戦一方。クロセルの拳を躱し続けるのがやっとで、打ち込むチャンスなど見当たらない。だが、これで良い。俺には傷害の才能がある。そのハンデを最小限にするには、勝つ必要はない。" },
  { text: "要するに負けなければいいのだ。どんな手段であれ、先に立っていた方が勝者である。最小限の動きで、相手の体力を消耗させる。そうすれば……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "視えた!" },
  { fx: "shake" },
  { text: "クロセルの体力も無限ではない。打ち込み続けて僅かに息を乱した瞬間、それがチャンスだ。此処ぞとばかりに一気に踏み込み、拳を放つ。" },
  { fx: "flash" },
  { text: "そして遂に、その拳はクロセルの身体へと届いた。案の定、拳はばしんと弾かれる。その鈍い痛みすら今の俺には｜愉悦《ゆえつ》の燃料だ。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "よし!これで一本取ったな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、ここ数日で驚く程に実戦慣れしたな……成長速度が才能持ちのそれと変わらんぞ……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "これでも殴り合いの経験はそこそこにある、鈍ってた感覚を取り戻したに過ぎないからな" },
  { text: "ニヤニヤと笑いながら拳を握り締め、開くことを繰り返す。" },
  { text: "この数日の特訓で唯一にして初めての勝利だ。これで浮かれない方がおかしい。だが、この程度で喜んではいられない。確かに今の戦いは俺が傷害のディザビリティを持っていなければ勝利だった試合だ。" },
  { text: "しかし俺は傷害のディザビリティを持っている。今の一撃を加えたとして、相手にダメージはないのだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "どうやったら俺は勝てる?体力の我慢大会しか手段が無いなら人外相手に通用する気がしないんだが" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "傷を付けられないならば無力化すれば良い、それも魔術を使えば簡単なのだが……道具でやるとしたら……ふむ、これは我の教えでは不足かもしれんな" },
  { text: "クロセルは乱れた息を整えながら、考えるように腕を組む。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "縄や鎖を使った捕縄術という物がある、本来は才能が無ければ使い物にならないような術なのだが……ご主人であれば、或いは" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "才能持ちは同じ才能持ちで自分以上の才能指数の相手には敵わないんだろ?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "あぁ、その通りだ。そういう力が働く" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "じゃあ該当の才能の無い人間が該当の才能のある人間に勝てることは有り得るのか?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "本来は……有り得ない、だがご主人は例外だと我は思っている" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "どういうことだ?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "こういう仮説だ。ご主人はあらゆる才能を引き出せるのではなく、予め\"持っている\"。普段はそれが何らかの影響で抑えられていて、ご主人が強く願う、或いは思った際に抑えが解かれ、一時的にその才能を万全に発揮できる状態になる。という物だ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "また随分と突飛な発想だな……俺が全ての才能を持ってる、なんて仮定がまず成立するとは思えない" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、我もそう思う。だがこうでもなければご主人の\"あれ\"は説明出来ないのだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ何にしろ、相手と別の手段を取れば才能で負けてても何とかなる可能性があるって訳だろ?それならその捕縄術、身に付けてみるのもありかもしれないな" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "だが教えられる人物が居ない、本来この才能は忍ぶ者が習得している代物、そんな知り合いは身近に居ないだろう?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "忍者か……確かにそれらしい奴とは会ったこと無いな……そもそも王国に居るのかすら怪しいだろそれ……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "まぁ仮にその手の界隈の人間と出会う機会があったら教えて貰う、程度に思っていた方が良い、今は別の方法を考えよう" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "他の方法か……今すぐは思い付かないな……" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "我も考えておくが……余り期待はしないでくれ" },
  { text: "その後も二人で頭を捻ったが、良い案は思い付かず、今日の所の訓練は終了ということになった。俺は中庭の何処かに居るであろうティア達の姿を探す。" },
  { chara: [
    { slot: "left", id: "el", expr: "smile" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "お、居た居た" },
  { name: "エル", who: "el", expr: "smile", text: "あ……ヤマト様、訓練お疲れ様です" },
  { hide: "left" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "お、終わったのね、じゃあティア様もお部屋に戻りましょうか" },
  { hide: "left" },
  { chara: { slot: "left", id: "tia", expr: "surprised" } },
  { name: "ティア", who: "tia", expr: "surprised", text: "えー!?ヤマトは遊んでくれないの?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺は忙しいんだ、また今度な" },
  { hide: "left" },
  { chara: { slot: "left", id: "el", expr: "normal" } },
  { name: "エル", who: "el", expr: "normal", text: "ティアお嬢様、行きますよ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "最後まで任せて悪いな、助かる" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "労いの言葉は我にも無いのか……?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あ?クロセルか?そうだな……よくもあれほど負かしてくれたな、こいつめ……" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "痛くない痛くない!痛くないけど取り敢えず止めるのだ!" },
  { text: "クロセルの頭に｜拳骨《げんこつ》を強く擦り付ける。傷害判定になるようで、若干拳は浮いている。これじゃ痛くはないだろう。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "生意気なこいつに何か仕置きしてやりたいってのに……つくづく不便な才能だな" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "我がわざわざ時間を割いて特訓に付き合ってやってると言うのに……酷いぞ……" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "冗談だ、本当は凄い助かってる、だから顔を上げろ、クロセル" },
  { text: "涙目になっているクロセルが少し可哀想に思えた。少し言い過ぎたか。握り締めた拳を解き、そのままクロセルの頭を強く撫でる。" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "ご主人……" },
  { hide: "left" },
  { chara: { slot: "left", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "こほん!それでは私達は失礼しますので、お二人でごゆっくり" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんでアカツキが不機嫌になるんだよ……" },
  { text: "俺の周りの女は意味も分からない所で不機嫌になることが多すぎる。俺は何もしていないはず、何も悪いことしてない……よな?" },
  { hide: "left" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "俺達も戻るか、いやー良い汗掛いた……風呂でもあれば良いんだけどなぁ……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "風呂ならあるぞ?ご主人" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "えっ、マジで?王城にあるの?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "寧ろ王城だからこそ、だろうな……アカツキも使ってた故に、別に我々が使っても大丈夫だと思うが……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あいつ一人で抜け駆けしてたのか……許せん" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そんなに風呂に入りたかったのか……ご主人は" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、風呂は極楽だからな、あれほど疲れに効く良薬はない" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "なら、一緒に……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "一緒には入らないからな?" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "何故だ!?ご主人は我の身体に興味は無いのか?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "前から思ってたがお前を性的な目で見るには……少し幼すぎるな、あと4周りくらい胸を膨らませてからやり直せ" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "くっ……我を侮辱したな!?そんな事を言うと、魔術でご主人が入る湯を沸騰させてやるからな……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "やめてくれ……俺は茹でられる趣味はない" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "なら大人しく一緒に入るがよい!我も水浴びは好きなのでな" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あー分かった分かった、入れば良いんだろ……んじゃ取り敢えず案内は任せるぞ" },
  { text: "渋々と言った様子で折れる。本当は一人で落ち着いた時間を過ごしたかったのだが、これほど言われては仕方ない。最初だけだ、付き合ってやるとしよう。" },
  { text: "それにクロセルの裸に……興味が無いと言えば嘘になる。決して俺に幼女趣味は無いが、それでも好奇心が無いとは言い切れない。" },
  { text: "故に、俺は色んな意味で僅かばかりの期待を抱きつつ。こっちだ、と言いながら先導するクロセルに大人しく着いて行ったのであった。" },

  // ===== シーン4: 入浴と血吸い (EP37) =====
  { label: "bath_secret" },
  { fade: "out" },
  { hide: "all" },
  { bg: "royal_castle_bath", instant: true },
  { fade: "in" },
  { text: "王城の大浴場。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ほう……これは凄いな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "此処が王国でも最大規模の浴場だと言って良いだろう、今の時間ならば誰も来ない。貸し切りだぞ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "今の時間こそ風呂が賑わいそうな時間だと思ったが、そうでもないのか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "文化の違いだろうな、この世界の人間は基本的に朝風呂に入る習慣がある、夕刻に入る者は珍しい" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "二十四時間湯を沸かしてるのは王城だからか……贅沢な事してるんだな" },
  { text: "そんな会話をしながら、脱衣場で服を脱ぐと、浴場へと入っていく。プールなのではないかと錯覚するほどに広い浴場には大きな湯船は勿論、荒い布と石鹸すらも用意されている。" },
  { text: "流石にシャワーは無かったが、それでも十分だろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "タルフの村には無かったが、浴場自体は珍しい物でも無いのか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "これほど綺麗な場所は他に無いだろうが、大きな街であれば公衆浴場があるな" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうか……もし王城を追い出されても王都に住めばその辺りは困らなそうだな" },
  { text: "｜桶《おけ》で身体を流しながら、ゆっくりと考え事に｜耽《ふけ》る。内容は傷害のディザビリティを乗り越える対抗策と、もはや残り半月に迫った魔王の復活の件。最近は暇さえあればこれらの事ばかり考えている気がする。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、そんな場所で座っていては身体が冷えるぞ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ……そうだな、んじゃ入るとするか" },
  { text: "促されるままに、ゆっくりと湯船に浸かる。正面に居るクロセルの事だが……直視出来ない。予想はしていたことだが、混浴とはやはり居心地の悪い物だ。落ち着いて居られやしない。" },
  { text: "それはクロセルも同じようで、先程までは嬉しそうに歩いていたというのに、今になっては黙りこくって俺から目を逸らしているようだ。うん、何とも気まずい。やはり風呂は一人で入る物だ。次からはクロセルを連れて来ない事にしよう。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人は何故こっちを見ないのだ……?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "女の裸は目に毒だからな、襲われたくなかったら黙ってろ" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "そうか……ふふふ、そうかそうか" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "何を楽しそうにしてるんだよ……意味分からねぇ……" },
  { text: "何故か喜ばれた。こいつは俺に襲って欲しいのだろうか。いや、駄目だ。こいつに手を出すと主従関係が｜拗《こじ》れる気がする。俺とクロセルは今のままの関係でいいんだ、今のままの関係が心地良いんだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ふぅ……それにしても、短い間だったが……俺達にも色々あったな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "何をいきなり言い出すのだ、一生の別れでもあるまいし……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "こうやって落ち着いて寛げる場だからこそ、考えさせられる事もあるんだよ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そういうものなのか……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そういうものなんだ" },
  { text: "ちらりとクロセルの顔色を伺ってみれば。何やら不思議そうな顔を浮かべて、うんうんと頷いている。そんな姿に思わずドキリと胸を跳ねさせつつも、｜諸行無常《しょぎょうむじょう》。やましい感情を切り捨て、思考をぐるぐると回転させていく。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……そう言えば、クロセルの過去については聞いてなかったな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ふむ、確かにそうだ。だが……我の昔話は、話せば長くなるな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "言いたくないなら別に言わなくても良いぞ、暗い話は興が削がれるしな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そうだな……ではまたの機会にしよう" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "その代わりに……そうだな、恥ずかしい秘密でも言ってみろ、命令だ" },
  { text: "悪い事を思い付いたとばかりに、ニヤリと口角を上げる。たちまち真っ赤になり、慌てた様子のクロセルを見て癒されながら、返答を待った。" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "それはまた……難儀な質問だな……そもそもこれは、人ならざる者、杖に聞くものでは無いと思うのだが……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "人だった頃の話でも良いぞ、魔王時代の話でも良い" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "いや、1つあった。この｜魔杖《まじょう》クロセルに秘められた秘密が1つだけな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、なら言ってみろ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "……血吸いだ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……とは何だ?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "｜魔杖《まじょう》クロセルは、人の生き血を吸う事で魔力を生み出す力を持っている……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "それは……なんというか、完全に呪われた武器って感じだな……でも俺は今まで一度も血を吸われた記憶はないが" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "別に吸わなくとも｜魔杖《まじょう》として最低限の機能に支障は無いからな……それに血を吸うのには少し抵抗がある" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それは……人型の状態で吸うからか?" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "そうだ、それに血を吸うと力に満ちると同時に……その……酔った様になるというか、興奮するというか……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ……要するに乱れた状態の姿を見られたくないって訳か、道理で今まで一度もそんなことを聞かなかった訳だ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そうだ、それに血を吸った状態の我は理性が蒸発する、何があろうと歯止めが効かないからな……ご主人を殺してしまうとも限らない" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そんなにヤバイ状態になるのか……それはそれで見てみたくもあるな……" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "馬鹿を言うな、これだから伝えたくなかったのだ……我が全力を出しても勝てない敵と戦う時の、最終兵器だと思ってくれ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "人にして魔王にして｜魔杖《まじょう》にして吸血鬼とか、流石に属性が多すぎないか……?" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "それだけ我が万能だと言うことだな" },
  { text: "確かにクロセルの姿は、人、天使、悪魔、魔王、｜魔杖《まじょう》、吸血鬼。どんな者だと言われても違和感の無い姿をしている。それにしてもクロセルの乱れた姿か……俺には想像できない。故に純粋に興味がある。いつか命令して試してみよう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "うーん……確かに驚く秘密ではあったが、恥ずかしい秘密にしては少し物足りないな……他にないのか?" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "あまり女性にそういう質問をするものでは無いと思うぞ……?ご主人……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "かもしれないが、お前は俺の所有物だからな、遠慮も気を遣う理由も無い" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "ぐぬぬ……決して否定はしないが、どうも気に食わないな……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "何が不満なんだ?お前は俺にとって唯一無二の特等席に座る女だぞ、光栄だろう" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "確かに言われてみれば……この距離感も特別な物に感じられ……っと、我は騙されんぞ!?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "別に騙してないんだけどな、じゃあ俺の所有物から俺の従者に降格するか?" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "昇格に感じるのだが……気の所為なのだろうか……" },
  { text: "そんなことを言い合っていれば、良い感じに湯で疲れも取れてきた。そろそろ上がることにしよう。俺はクロセルから目を逸らしたまま立ち上がると、身体を軽く流し、そのまま浴場を後にする。" },
  { text: "脱衣場で身体を拭いていると、続いてクロセルも風呂から上がってくる。今この瞬間、初めて彼女の裸体を直視したが……美しいとしか言いようがない、女性として必要な物を殆ど兼ね備えた、抜群の肉体美だ。" },
  { text: "ただ、唯一にして致命的な欠点を抱えている。その部分とは言うまでもなく。無いのが残念としか言いようがない。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "いやーでもやっぱり風呂は良いな、ここ暫くで溜まった疲れが見事に取れたよ、今日は良く眠れそうだ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "それは良かった、我も教えた甲斐があったな" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "もっと早く教えてくれれば良かったんだがな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "仕方ないだろう、我は幾ら汚れても大丈夫なのだから" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前は身体も服も魔術で出来てるからなぁ……確かに必要無いのも分かる" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "一時的な魔力枯渇はあれど、慢性的な疲労など発生しないからな、そういう意味でも縁が無い場所だ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ならなんで着いてきたんだよ、折角一人で浴場を使えると思ったのに" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "ご主人も満更でもない癖に" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "全然そんなことは無いんだが、これっぽっちも、全く" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そ……そこまで言われると傷付くぞ……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "勝手に傷付いてろ、というか……こんなこと言われたってお前には痛くも痒くも無いだろ" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "それは……どういう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前にマゾの気があるってことだ、推定だがな" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "マゾ……?とは何だ?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "流石に通じないか、まぁ知らなくていい、その方が幸せに生きれる" },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "ううん……気になるぞ……一体我に何の気があるのだ……" },
  { text: "うんうんと首を捻って濡れたまま立ち尽くすクロセルにタオルを投げ付ける。そして俺はそそくさと服を着ると、クロセルを置いて先に部屋へと向かうことにした。" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人、我を置いてく気か!?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いつまでも裸で居る方が悪い、さっさと着替えろよ……部屋で待ってるから" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "そうか、承知したぞ!" },
  { text: "折角部屋を分けて貰ったというのに、クロセルは依然として俺の部屋に居着いて離れない。そう言えば、いつの間にか一緒に寝るのも常になっている。" },
  { text: "最初こそ抵抗した物の、慣れてしまえば別にどうということはないから良いのだが。ただまぁ、時々寝相が悪いのは勘弁して欲しい所だ。" },

  // ===== シーン5: 人選 (EP38) =====
  { label: "mission_briefing" },
  { fade: "out" },
  { hide: "all" },
  { bg: "royal_castle", instant: true },
  { fade: "in" },
  { bgm: "tension" },
  { text: "ある日の早朝。何処か焦りのような色を含んだアカツキの声で、俺は叩き起こされる。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "serious" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさん、起きて下さい!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんだよ……今日はやけに早いな" },
  { text: "隣で気持ち良さそうに眠っているクロセルを一瞥すると、俺は安眠を｜邪魔《じゃま》された苛立ちからアカツキを軽く睨み付けつつ、むっくりと起き上がる。" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "そんな怖い目をしないで下さいよ……ヤマトさん、あとクロセルさんも関係ありますね、緊急の報告です" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……なんだよ、報告って" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "魔王の復活地点が特定出来ました、王国の文書解読班が80年前の文献を片っ端から漁って、やっと割り出せたみたいです" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "今まで特定出来てなかったのか……そりゃ危ない所だったな、何しろあれから今日で……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "24日です、魔王の復活は恐らく7日後、丁度一週間後になると思われます" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "もうそんなに経ったのか……時間が流れるのは早いな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それで、その場所ですが……帝国領にある｜迷宮《ダンジョン》、通称\"｜魔窟《まくつ》\"と呼ばれる場所です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "帝国領ってのは分かるが……迷宮ってのは何だ……?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ある場所に、何の前触れもなく発生して、内部から魔物を生み出す異空間です。その多くは最深部に聖遺物や魔の力を持った品が封印されています" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "おかしな話だな、そう聞くと人為的に作られた物のように思える" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "えぇ、私もそう思います。現時点では神が生み出していると考える説が有力ですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "んで……その｜魔窟《まくつ》とやらの最深部には\"魔王\"が封印されてると、そういう訳だな?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、現代の魔王が消失した時期と｜魔窟《まくつ》の発生の時期は一致しています、恐らくはそういうことかと" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "迷宮の内部は……まぁ大凡予想はつくが、文字通り迷宮になってるのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "はい、その通りです" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "迷宮の中で魔王が復活するなら、下手に攻め込むより迷宮の入口で出待ちした方が良さそうだな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それがそうとも限らないんです、魔王は封印の影響で非常に弱った状態で復活します、そこから時間と共に力を取り戻すと推測されています" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "つまりは……魔王を仕留めるなら迷宮の奥で復活した直後、弱ってる時を狙って仕留めるべきってことだな?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "魔王を\"仕留める\"ならばその方法が最善だと思います、ですが魔王に関しては仕留めてはいけないんです、殺さず生かして、再封印せねばなりません" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "どういうことだ?魔王は殺せないとかそういうことか?" },
  { name: "アカツキ", who: "akatsuki", expr: "angry", text: "いいえ、そういう事ではなく。魔王を殺すと\"魔王の血を浴びた者\"に力が継承され、次の魔王として目覚めるのです" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……話が読めてきたな" },
  { text: "話している内に寝惚けていた頭も覚め、思考は正常に回転を始める。俺にはずっと謎だった事がある。それは皇帝が何故魔王の復活の儀式を行ったのかについてだ。" },
  { text: "それが今1つの仮説として分かった。恐らく、皇帝の目的は魔王の復活自体ではなかったのだ。皇帝は魔王を復活させ、直ぐに\"殺す\"事で……皇帝自身が魔王に成り代わる。推測の域を出ないが、それが皇帝の目的となれば色々と納得がいく。" },
  { name: "アカツキ", who: "akatsuki", expr: "angry", text: "はい、なので魔王は殺せません。殺してしまえば次の魔王が完全な状態で目覚めることになります、それだけは何としても阻止せねばなりません" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "それで……魔王を封印する方法を取るって訳だな、復活直後で弱ってる所を殺さずに封印すると" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そういう事になります、ただ……封印の方法ですが……現在王国は魔王を封印する手段を持っていません" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……は?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "封印する方法があるのは事実ですが、そもそも手段が現状不明です、恐らく唯一皇帝だけが封印する方法を知っています" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "確かに封印を解除する方法を知っていたということは、封印をする方法を知っていてもおかしくはないな……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "なので……今朝、私にある任務が下りました" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "大方予想はついたが……聞こう" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "帝国領での諜報任務です、目的は魔王封印の手段の獲得、そして期日に｜魔窟《まくつ》の深部に潜り、復活した魔王を再封印します" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "封印の手段とは、かつて皇帝が五芒星の会談に持ち込んだ一枚の｜石版《せきばん》……封印の儀式が記されたあれです。潜入先は帝国領の心臓部、帝都に位置するヴァルハラ要塞。恐らく｜石版《せきばん》は皇帝の手元にあります" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……無茶だろ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "私もそう思います、ですが何もしない訳にもいきませんからね。国王陛下も余り期待してはいないみたいです。主に王国領の防衛の強化を優先しているので人員も割けません" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル奪還と同じく、少数精鋭って訳か……" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そこでヤマトさんに相談です、王都を明日発つことになります、なので今日中に連れて行く方を見繕って貰えませんか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そこはお前の仕事だろ……俺の人脈なんてたかが知れてる" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうなんですが、私は旅の手配で恐らく今日が潰れてしまうと思うので、此処は人望が厚そうなヤマトさんに頼もうと思いまして" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……誰を選んでも文句は言わないな?" },
  { text: "俺にも宛が無い訳じゃない。直ぐに思いつくだけでも、祝福の勇者ニコラス、そしてティア。どちらも大きな問題を抱えているが戦力としては十分過ぎる人材だ。" },
  { text: "だがどちらも抱えている問題が致命的かつ大きすぎる。今回の旅も、前回と同じぐらいのリスクを孕んでいる。そんな任務に、ニコラスやティアを連れて行くのが最善とは思えない。" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はい、人選は完全にヤマトさんにお任せします、国王からも許可は降りているので誰を連れて行っても王国からは文句は言えません" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、まぁ了解した、やれるだけやってみるよ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "助かります。では私は忙しいのでこれで、失礼しました" },
  { text: "アカツキは一礼すると、そのままそそくさと部屋を出て行った。まるで嵐のようであった。唐突に訪れ、俺に重要な役回りを押し付けると、そのまま風のように去っていった。" },
  { text: "残された俺は、軽く呆然としながら、頼まれた人選に付いて考えを巡らしていく。" },
  { hide: "left" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセルと俺、そしてアカツキは確定として……" },
  { hide: "all" },
  { bgm: "daily2" },
  { text: "気が付けば日は昇り、普段目覚めていてもおかしくはない時間となっていた。朝食を乗せたトレイを持ってエルが入ってくる。相変わらず見ていて愛らしい。｜眼福《がんぷく》とはこのことだろう。" },
  { chara: [
    { slot: "left", id: "el", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "エル", who: "el", expr: "normal", text: "……失礼します、ヤマト様、朝食をお持ちしました" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ありがとな、それと少し聞きたいことがあるんだが……良いか?" },
  { name: "エル", who: "el", expr: "normal", text: "はい、ヤマト様。承ります" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "君の才能が知りたい" },
  { name: "エル", who: "el", expr: "surprised", text: "えっと……家事1、短剣術4、氷魔術4です……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……マジ?" },
  { name: "エル", who: "el", expr: "surprised", text: "嘘は致しません、ヤマト様" },
  { text: "驚いた。エルが戦闘向けの才能を持っているとは。本来なら使用人として、家事の才能に目が行くのだろうが、俺としては後者二つの才能の存在の方が大きかった。これほど可愛い子を危険に晒すと思うと胸が痛むが、ダメ元で問い掛けてみる。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "明日から俺はアカツキの任務に着いて行くことになるんだが……君も来るか?" },
  { name: "エル", who: "el", expr: "smile", text: "はい、お供します" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……マジで?" },
  { name: "エル", who: "el", expr: "surprised", text: "嘘は致しません" },
  { text: "二つ返事で了承されてしまい、思わず困惑する。この子はあまりにも従順過ぎる。否定するということを知らないのだろうかと錯覚する程に。" },
  { text: "だが了承を得られてしまった以上、今更無かった事になど出来ない。これで同行者一人目が決定だ。余りにも呆気ないが。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "じゃあ頂くよ、ありがとな" },
  { name: "エル", who: "el", expr: "blush", text: "いえ……滅相も無い、有難き幸せで御座います……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そんな畏まらなくても良いんだけどな……もう少し砕けた関係で良いんだぞ、その方が俺も気が楽だし" },
  { name: "エル", who: "el", expr: "normal", text: "分かりました、以後気を付けます" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "敬語も無し……ってのは流石にハードルが高いか?" },
  { name: "エル", who: "el", expr: "blush", text: "いや、大丈夫……これで良い?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "出来るじゃないか、それで良いんだぞ" },
  { text: "態度が変わっただけだが、それでも少しエルと距離が近付いた気がして嬉しい。その後、朝食を冷めない内に頂いた後に、まだ寝惚けた様子のクロセルを強引に引き連れ、部屋を出た。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "dizzy" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "dizzy", text: "うぅ……ご主人……今日は何でこんな早くから起きてるのだ……?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いつもとそこまで変わらないだろ、それより人探しだ……俺の人脈で戦力になる人間って言うと……やっぱあいつしか居ないよな……" },
  { text: "王城から出て王都に繰り出す。アカツキの監視が無いが、門番の方にアカツキの手が回っていて今日だけは例外ということにしてくれているらしい。流石はアカツキだ、抜かりが無い。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "久々の王都だが……うかうかしては居られないな……勇者を探さないと" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "勇者と言うと祝福の勇者か?一体あいつに何の用があるのだ?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "仲間へのお誘いだな……俺は全力で不本意だが、あいつを使わねばならない程に人手不足が深刻らしい" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "まぁ……確かに戦力としては申し分ないが……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、勇者ニコラスは頭がな……足りてない" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "扱いやすいという意味では利点でもあるがな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あぁ、その通りだ、単純で助かったよ……本当に" },
  { hide: "all" },
  { bg: "royal_capital", instant: true },
  { bgm: "town" },
  { text: "そのまま王都を巡り歩いていると……そこそこに大きな人だかりを見付ける。注目を浴びている何かがあるということだ。俺ははぐれないようにクロセルの手を握り、人だかりを掻き分けていく。" },
  { chara: [
    { slot: "left", id: "nicholas", expr: "laugh" },
    { slot: "center", id: "crocell", expr: "dizzy" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "お、見付けた……が、あれは……何してるんだ?" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "はははは!さぁ、他に僕に挑戦する人間は居ないのかい?この聖剣フルティンの錆にしてくれよう!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……帰るか" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人!?彼を仲間に誘うのでは無かったのか!?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "分かってるよ、冗談冗談" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "嘘つけ……声色が本気だったぞ……" },
  { text: "どうやら勇者はまた新しく聖剣を手に入れて、決闘大会を開いているらしい。冗談みたいな話だが、勇者の実力は確かのようで、辺りには勇者にやられたらしき男が何人も見受けられる。奴は装備と剣の腕だけは確かなんだ、剣の腕だけは。" },
  { text: "そんな、現在進行系で近寄り難い雰囲気を醸し出す勇者ニコラスに、意を決して近付いていく。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よう、勇者" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "おっと、君はヤマト君じゃないか、一体どうしたんだい?僕の聖剣と手合わせしたいってなら、いつでも相手になるけれど" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "決闘には興味ない、お前と話していると酷く時間の浪費した気分になるから簡潔に言おう、俺達の旅に着いてこい" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "何の旅だい?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "んまぁ……掻い摘んで言えば魔王退治だな" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "そうか!魔王と言えば悪の象徴!それを滅ぼすのが僕の役目だ!喜んで付いて行かせて貰おう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ……そりゃ良かった、明日発つから準備しとけよ" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "分かった!ふふふ、僕の聖剣が活躍する時も近いようだね……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、活躍出来るといいな" },
  { text: "やはり単純だ、こいつが馬鹿で本当に助かる。そんな事を心の中では思いつつ、｜飄々《ひょうひょう》とした顔色で勇者の近くを離れる。これで二人だ、アカツキとクロセルと俺を含め五人。ラストはやはり……彼女ぐらいしか俺には思い当たらない。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "城に帰るぞ、クロセル" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "もう少し王都観光と行きたかったのだが……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "同感だが……生憎勇者探しで時間が潰れちまった、最後の用事も、日が暮れる前に済ませたい" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "分かった、帰るとしよう" },
  { text: "王都見物もそこそこに、俺達は王城へと戻った。そして、俺達はある一室を目指す。" },
  { hide: "all" },
  { fade: "out" },
  { bg: "royal_castle", instant: true },
  { fade: "in" },
  { bgm: "daily2" },
  { text: "本当は連れて行きたくないのだが……彼女の魔術の才能は確かだ。それにああ見えてしっかりしている。" },
  { chara: [
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "crocell", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ、どうしようか……非常に悩ましいぞ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "……勇者ティアを連れて行くつもりなのだな?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ティア……ではあるが……勇者?あいつも勇者なのか?" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "あぁ、勇者だぞ、気付かなかったのか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あんな小さい奴が……と思ったが、いや……冷静に考えれば才能は生まれつきなのだから年齢は関係ないんだな……" },
  { text: "国王の娘、王女様が勇者とは、偶然という物は恐ろしい。連れて行っても｜邪魔《じゃま》にはならないだろうが……やはり一国の王女を連れて行くのはリスクが高すぎるだろうか。" },
  { text: "考えれば考える程に泥沼に沈んでいく。ええい、こういうのは勢いだ、彼女も誘おう。こんなことでひたすら悩んでも仕方ない、本人が嫌と言えばそれで終わり、着いて来たいと言うのなら連れて行くだけのことだ。" },
  { chara: { slot: "left", id: "tia", expr: "normal" } },
  { text: "俺は大きな深呼吸を一つすると、覚悟を決め、ティアの部屋へと足を踏み入れる。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "よし、｜邪魔《じゃま》するぞ。ティアは居るか?" },
  { name: "ティア", who: "tia", expr: "laugh", text: "ヤマトじゃない!どうしたの?遊びに来てくれたの?" },
  { text: "案の定、ティアはそこに居た。部屋に閉じ込められて居たのだろう。二人の使用人に囲まれ、ソファに座ってつまらなそうな顔をしている。ところが俺が部屋に入ると同時に、曇った表情は一瞬にして晴れ、ティアは笑顔で俺を出迎えてくれた。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いや、今日は真面目な話をしに来た、俺達は明日から任務で遠い所に行く。前回だって死者が出たんだ、危険な旅になるのは明白、そんな旅に俺達は行かなくてはならないんだが……" },
  { name: "ティア", who: "tia", expr: "normal", text: "どうしてそれをわたしに話したの……?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そう、そこなんだよ。俺がお前にこの話をしたのは、お前も俺達の旅に着いて来ないか?と誘う為なんだ、良いか?よく考えて決めるんだぞ" },
  { name: "ティア", who: "tia", expr: "laugh", text: "ヤマトが行くならわたしも着いていくわ!わたしだって戦えるもの!" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あぁ、そうだろう。才能に年齢は関係ない、お前の魔術の才能があれば、大人と同等かそれ以上に戦える。だから俺はお前を誘いに来たんだ、本当に良いんだな?死ぬことになるかもしれないんだぞ?" },
  { name: "ティア", who: "tia", expr: "normal", text: "それでも着いて行くわ、わざわざわたしを誘いに来たってことは、ヤマトも覚悟を決めたのでしょ?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、その通りだ。お前を誘う覚悟は出来てる、お前を危険に巻き込む覚悟も出来てる、お前がそれを理解した上で、着いて来ると言うのなら……" },
  { name: "ティア", who: "tia", expr: "normal", text: "言うのなら……?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "俺はお前を歓迎しよう。出発は明日だ、精々足手まといにはなるなよ" },
  { name: "ティア", who: "tia", expr: "laugh", text: "ヤマトよりは役に立つと思うわ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……助けてくれクロセル、言い返せないんだがどうすれば良い……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "これはご主人の負けだな、大人しく言い負かされるが良い" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あとこれって……国王の許可とかも必要になってきそうだよな……" },
  { name: "ティア", who: "tia", expr: "normal", text: "それなら心配要らないわ、お父様には私が言っといてあげる" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ……それは有り難いんだが、くそっ……ティアの方が俺よりしっかりしてるんじゃないか?" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "かもしれんな、ご主人も……もう少し頑張れ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くそっ……年下に負けるのがこれほど悔しい物とは" },
  { text: "こうして、旅の面子は決まった。クロセル、アカツキ、エル、ニコラス、ティア、そして俺の六人。その日、俺とクロセルは部屋に戻り、明日に備えて支度を始めるのであった。" },

  // ===== シーン6: 帝国を目指して・謎の夢 (EP39) =====
  { label: "road_fever_dream" },
  { fade: "out" },
  { hide: "all" },
  { bg: "country_road" },
  { fade: "in" },
  { text: "翌朝。何時ぞやと同じように、アカツキの手配してくれた馬車に乗り込む。六人も居るから乗り切れるか心配だったが、それも杞憂だったようだ。馬車の中はかなり広い。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "jito" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ヤマトさん……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "このメンバー、私凄く見覚えがあるんですが……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そりゃそうだ、俺の人選なんてこんな物よ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "だからと言って候補は他にも幾らでも居るでしょう、ゲーテさんとかギルドの冒険者とか……全く、ヤマトさんに期待した私が馬鹿だったかもしれません" },
  { text: "後ろをくるりと振り向けば、確かに手配した通りの人間が集まっている。最強の｜魔杖《まじょう》に勇者二名も居る。戦力としては十分だと思ったが、どうやらアカツキは不満らしい。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁ、今から集め直しって訳にもいかないんだろ?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "そうですね、こうなってしまったらこの面子で行く他ありません" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ならそれで決まりだ、さっさと行こうぜ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "いや、やっぱりティア様だけでも置いて行きましょう、遠足じゃないんですよ?彼女を連れて行くのは危険過ぎます" },
  { name: "ティア", who: "tia", expr: "normal", text: "嫌よ!わたし、ヤマトに着いて行くって決めたもの。それにこう見えても戦えるのよ、ヤマトよりは役に立つわ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……という訳らしいので、連れて行くことにした" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "馬鹿ですかヤマトさんは……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "こいつよりは賢いぞ" },
  { text: "俺は小さく勇者を指差す。それを見たアカツキは、一つ大きな溜息を吐くと、諦めたとばかりにひらひらと手を振る。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "分かりました、これで行きましょう" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "やっと覚悟を決めてくれたか。よし、それじゃ出発だな" },
  { text: "俺に続いて仲間が次々と乗り込んでいく。そして最後に、既に疲れた様子のアカツキが乗り込んだ。" },
  { text: "やがて、帝国を目指して馬車が動き出す。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "んな暗い顔するなよ、リーダーがそれじゃ締まらないだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "……そうですね、私がしっかりしないと……そう、私がしっかりしないと……" },
  { text: "アカツキが一人、同じ言葉を呪詛のようにぶつぶつと呟き始めた。駄目だこれ。俺は話題を逸らしてアカツキを正気に戻そうと試みる。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "帝国領を目指すんだったな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね、帝国領の心臓部、帝都に位置するヴァルハラ要塞が今回の目的地です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "要塞……?城じゃないのか" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "クロム帝国は軍事国家なので、その司令部は要塞となっているんです" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "つまり帝国の皇帝ってのは総司令官、元帥、そんな類の立場の人間ってことだな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうなります、なので皇帝不在の今も、皇帝の次点で権力を持つ人間が執政を行えるので、大きな混乱は起きていないみたいですね" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "やはり皇帝は不在なのか……奴は本当に死んだんだろうな?" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "遺体を見ていない以上、どちらとも断定出来ないのが辛い所ですね……" },
  { text: "話している内にアカツキの調子も戻ったようだ。" },
  { hide: "left" },
  { chara: [
    { slot: "left", id: "el", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "エル", who: "el", expr: "normal", text: "ヤマト様……少し良いかな?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "エルから声を掛けてくるとは珍しいな、何だ?言ってみろ" },
  { name: "エル", who: "el", expr: "surprised", text: "大したことじゃないんだけど……顔色が悪いように見えるから……大丈夫かなって" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "……そうだな、確かに少し調子が悪い" },
  { text: "エルは俺のことを随分と良く観察しているのだろう。言われて思い出したが、確かに俺は今日調子が悪い。それもほんの少しだけだが。" },
  { text: "｜徐《おもむろ》に手を額に当ててみれば、僅かだが微熱があるように感じる。鏡など見る機会など無い故に憶測になるが、確かにこの調子だと少し顔色が悪いのかもしれない。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "良く気付いたな、でも大丈夫だ。この程度寝て起きたら吹っ飛ぶ" },
  { name: "エル", who: "el", expr: "sad", text: "いや……気を付けてね、この世界では風邪一つでも命に関わるから" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうなのか……回復魔術とやらがあるから風邪程度簡単に治る物だと思っていた" },
  { chara: { slot: "center", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "エルの言う通りだ、回復魔術とは外傷を修復しているに過ぎない、身体の内で｜蔓延《はびこ》る病は治せないのだ" },
  { text: "ふと、何か違和感を覚えた。だがその正体が上手く掴めず、言語化出来ない。一体今の違和感とは何だったのだろう。" },
  { hide: "center" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "まぁ安静にしてるよ、少し眠る、何かあったら叩き起こしてくれ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "あぁ、おやすみご主人" },
  { name: "エル", who: "el", expr: "sad", text: "おやすみなさい" },
  { text: "エルとクロセルの言葉を聞き届けると……俺はゆっくり目を閉じる。思っていた以上に疲れていたらしい。やがて、俺は直ぐに意識を失った。" },
  { fade: "out" },
  { hide: "all" },
  { text: "そして俺は、夢を見た。" },
  { fade: "white" },
  { bgm: "mystery" },
  { pov: { name: "？？？", color: "#9a8cb8" } },
  { text: "広がる風景は白いもや。形を留めない雲のような世界。そこに、俺らしき人物と一人の少女が向き合って立っている。俺はそれを｜俯瞰《ふかん》的な視点から見ていた。" },
  { name: "???", text: "ヤマトくん、貴方は――――います" },
  { name: "俺らしき人物", text: "――――るのはお前の方だ、俺はお前を――――から――する" },
  { name: "???", text: "無駄です、そんなことをしたら――――は―――るんですよ?" },
  { name: "俺らしき人物", text: "それは――、俺は知っているんだ、お前が――――――――――だということを!" },
  { name: "???", text: "……――はあるのですか?" },
  { name: "俺らしき人物", text: "――無い、その｜惚《とぼ》けた口調が他の何よりも確かな――だ!" },
  { name: "???", text: "残念です、私と貴方は――――、―――やれると思ったのですが" },
  { text: "気が付けば、夢の中の俺は剣を取っていた。少女も剣を取っていた。やがて打ち合いが始まる。夢の中の朧な風景でも、それは惚れ惚れする程に鋭く、美しい剣舞に見えた。夢の中の俺は、少女と剣を打ち合い、踊り続ける。一見すると一体どちらが踊らされているのか、俺には判別できなかった。" },
  { name: "???", text: "私にとっては実に―――で、―――時間ですが……――――時は――ですので" },
  { name: "俺らしき人物", text: "くそっ……舐めた真似をしやがって" },
  { name: "???", text: "―――にしましょう、ヤマトくん" },
  { name: "俺らしき人物", text: "っ……これは……" },
  { name: "???", text: "そう、分かりましたね……――はもう……" },
  { name: "俺らしき人物", text: "嫌だ!くそっ……俺は……お前の思う通りには……ならない!" },
  { fx: "flash" },
  { text: "物事には必ず終わりがある。それは時として唐突で、呆気ない。" },
  { text: "――夢の中の俺は、少女の胸を刺し貫いた。" },
  { fx: "shake" },
  { se: "heartbeat" },
  { text: "驚いたのは少女の方であった。まるで思いもよらぬ事が起きているとばかりに、自分の胸元を見つめ……黙り込む。" },
  { text: "｜刹那《せつな》、夢の中の俺が頭を抱える。同時に、それを見ていた俺にも酷い頭痛が起きる。一体今のは何の風景なのだろう、何を明示している?そんなことを薄々思いながら、俺の意識は一気に覚醒する。" },
  { pov: null },
  { fade: "out" },
  { fade: "in" },
  { bgm: "daily2" },
  { chara: [
    { slot: "left", id: "el", expr: "sad" },
    { slot: "center", id: "yamato", expr: "surprised" },
    { slot: "right", id: "crocell", expr: "sad" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "っはぁ……はぁ……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "大丈夫か?ご主人、うなされていたようだが……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "大丈夫だ……少し悪い夢を見た……" },
  { name: "エル", who: "el", expr: "sad", text: "ヤマト様……それはどんな夢でした?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "それは……" },
  { text: "夢の内容を思い出そうとするが……思い出せない。俺は一体どんな夢を見ていたんだ?何故これほどに怯え、身体が震えている?幾ら考えても……俺はそれを思い出すことは出来なかった。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "悪い、思い出せない……" },
  { name: "エル", who: "el", expr: "sad", text: "そうですか……" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人、酷い熱だぞ!?本当に大丈夫なのか?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "いや……ちょっと不味いかもしれない……" },
  { se: "magic" },
  { name: "エル", who: "el", expr: "normal", text: "此処は私にお任せ下さい、｜魔術回路構築《クリエイト》……詠唱……ラ・アイス・ナヴル・ティロ……氷魔術……｜氷結籠手《アイスハンド》" },
  { text: "虚ろな意識の中、俺の額に冷たい物が当てられる。これは……エルの手か。程良く冷たく、心地よい。" },
  { name: "エル", who: "el", expr: "surprised", text: "まさかこんな所で私の才能が役立つ時が来るとは思いませんでした" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "おい……それ、当ててる側は冷たくないのか……?" },
  { name: "エル", who: "el", expr: "smile", text: "はい、全く私には問題ありません、ですのでヤマト様はゆっくりと休んで下さい、ね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうか……助かる" },
  { text: "エルの優しい手に包まれながら、俺はもう一度、ゆっくりと意識を手放した。それは恐ろしい程に心地よく、甘美な眠りだった。そのお陰だろうか……今度は悪い夢を見ることもなかった。" },

  // ===== シーン7: 帝都 (EP40) =====
  { label: "imperial_city" },
  { fade: "out" },
  { hide: "all" },
  { bg: "imperial_capital" },
  { bgm: "town" },
  { fade: "in" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "降りますよ、皆さん" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "まだ着いてないぞ?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "皇帝の差金で、二ヶ月程前から検問が強化されています。私達の素性を考えると、正面からは入れないと考えるべきです" },
  { text: "俺は促されるままに馬車を降りる。馬車の進行方向、そこには王都のそれの倍の高さはあるであろう、厚く巨大な城壁が｜聳《そび》え立っていた。続いて他の皆も馬車を降り、各自大凡は俺と似たり寄ったりの、様々な反応を浮かべている。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あれが検問か" },
  { text: "ゆっくりと視線を降ろすと、そこには大きな門があり、多くの兵士が立っているのが見える。確かにあそこから入るのは厳しそうだ。となると……どうやって帝都へと入るのだろうか。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "馬車はそのまま検問を通します、私達だけ別の手段で帝都に入り、後に馬車と合流する、この流れで行きましょう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それで……どうやって帝都に入るんだ?この城壁、そう簡単には飛び越えられない気がするが" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "物理的な障壁であれば、私やクロセルさんが居ればあって無いような物です、取り敢えず此処だと目立つので、離れましょう" },
  { text: "確かにこの｜大所帯《おおじょたい》では嫌でも目立つだろう。俺達五人は、城壁に沿うようにして森の中へと向かうアカツキに着いて行く。" },
  { chara: { slot: "right", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、熱は大丈夫なのか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、エルのお陰で完全に調子は戻った、ありがとな" },
  { chara: { slot: "left", id: "el", expr: "blush" } },
  { name: "エル", who: "el", expr: "smile", text: "いえいえ、そんな……私はヤマト様の使用人ですから、あの程度は当然の事です……" },
  { text: "隣を歩いていた、エルの頭を優しく撫でる。恐縮して縮こまる様子に思わず笑みが浮かぶのを抑えつつ、俺は軽く伸びをした。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ま、俺があの程度でくたばる訳無いわな、他の皆も心配掛けた、悪いな" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "まぁ、ヤマトさんの事ですから大事は無いと思いましたよ" },
  { name: "ティア", who: "tia", expr: "laugh", text: "ヤマトが元気になったようで良かったわ!" },
  { chara: { slot: "right", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "ヤマト君が居なくなればこのハーレムは僕一人の物になったんだけどね、残念だよ" },
  { chara: { slot: "left", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ニコラスさん、そんな事を考えていたんですか……?" },
  { chara: { slot: "right", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "全く、最低な男だな" },
  { name: "エル", who: "el", expr: "troubled", text: "ヤマト様、すいません……仲間を少し軽蔑してしまいました……" },
  { chara: { slot: "right", id: "nicholas", expr: "normal" } },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "あ……あはは……おかしいなぁ～?僕の扱いが酷く無いかい……?僕は祝福の勇者だぞ!?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "黙ってれば格好も付くんだけどな、口を開いたら残念なのがお前の致命的な欠点だ。アドバイスはしたからな、頑張れ" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "なるほど!確かに黙っていれば僕にもクール属性も付いてモテモテって訳だね!分かったよ!黙ってる!" },
  { chara: { slot: "left", id: "akatsuki", expr: "jito" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ニコラスさんに関しては、黙ったら誰も相手してくれないと思いますけどね……" },
  { text: "ぼそりと呟いたアカツキの言葉は、どうやら後列のニコラスには届かなかったらしい。相変わらず可哀想な男だ。" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "この辺まで来れば大丈夫ですかね……クロセルさん、向こうの様子は分かりますか?" },
  { chara: { slot: "right", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "あぁ、大丈夫だ。人の気配は無いぞ" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "では始めましょうか、｜魔術回路構築《クリエイト》……詠唱……ル・トゥーム・アルガス・ティル……空間魔術……｜接続《コネクション》!" },
  { se: "magic" },
  { fx: "flash" },
  { text: "アカツキが城壁に手を向けたまま詠唱を行ったかと思えば、城壁の空間がぐにゃりと歪み……やがて大きな穴が生まれる。魔術で直線状の二箇所の空間を繋げたのだろう。どうやら穴は城壁の向こう側まで通じているようだ。" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "相変わらず便利だな、空間魔法" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "魔術的な障壁が無ければこれで大体の場所は通れますからね、便利ですよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "どうとでも悪用出来る力だからな、つくづくお前のような良い奴が持ってて良かったと思うよ" },
  { chara: { slot: "left", id: "akatsuki", expr: "sad" } },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "良い奴ですか……やってることは不法入国、悪人と変わり無いんですが……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "魔王の封印という大義名分があるからな、その過程で何をしようと俺達は正義だ" },
  { chara: { slot: "right", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "その通り!勇者である僕らに間違いは無い!僕らが正義であり!正義とは僕達の事なんだ!" },
  { chara: { slot: "right", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "大きな声を出すでない、馬鹿者" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "おっとそうだったね……失敬失敬" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "こいつ俺より足手まといだったりしないか?" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "正直な話、ありえますね……" },
  { text: "幸運にも、近くに人は居なかったようで、俺達は穴を潜って帝都の内部に入ることに成功した。" },
  { text: "まず思ったこととして、帝都の様式は、王都より僅かに現代に近い印象を受けられる。王都やタルフの村の建造物は基本的に木造が多かったが、帝都の建造物は石造に｜煉瓦《れんが》屋根が大半である。此方の方が、俺達の抱いている中世の風景の印象に近いかもしれない。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "smirk" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "中に入ってしまえばこっちの物だな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね、では宿の手配をして、馬車に荷物を取りに行きましょうか" },
  { text: "アカツキの指示に従って、俺達は宿に向かった。" },
  { text: "唯でさえ広い帝都である。無数にある宿の一つの二つ、難無く見付ける事は出来た。出来たのだが、流石は帝都の宿と言うべきか、宿泊料金が一人辺り銀貨50枚とのこと、その金額に俺は大変驚いた。単純計算でタルフの村の宿の5倍である。" },
  { text: "一方、アカツキはそんな事を気にする様子もなく、淡々と宿の手配を進めていく。どうやらこの中で金銭感覚が庶民的なのは俺だけらしい。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさんは先に部屋に行って休んでいても構いませんよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "いや、荷物持ちは男の仕事だ、サボる訳にはいかない" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人のそういう所、格好良いと思うぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうですね、私もそう思います" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "意地張ってるだけじゃないのか……?" },
  { name: "ティア", who: "tia", expr: "angry", text: "ヤマトを悪く言うなんて、祝福の勇者様なのに心が狭いわね" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "そ……そうだな、そんなことはないな、僕もヤマト君は格好良いと思うよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "今更取り繕っても遅いぞ、勇者" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "くっ……何故だ……どうして此処まで僕が責められるんだ……" },
  { text: "少し可哀想に見えてくる。だがこればっかりは勇者の日頃の行いが悪い、自業自得と言う奴だ。そんな風に歓談しつつ、俺達は馬車との合流地点へと向かった。" },
  { fade: "out" },
  { fade: "in" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "これは、どうなってる?" },
  { text: "合流地点に辿り着くと、そこには無惨に破壊された馬車、そして馬と御者の死体が転がっていた。人気の無い路地裏であった為、騒ぎにはなっていないようだが……これは明らかに人の手が加わっている。" },
  { text: "一体誰がこんな酷い真似をしたのだろうか……" },
  { bgm: "tension" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "駄目ですね……死んでます" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "荷物は残っている、盗賊の仕業では無いようだな……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ティアは下がってろ、余り見て気持ちいい物じゃない" },
  { name: "ティア", who: "tia", expr: "sad", text: "うん、分かったわ……" },
  { fx: "red" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "serious" },
    { slot: "right", id: "yamato", expr: "angry" },
  ] },
  { text: "近付いて観察する。だが俺には馬車の残骸と死体である以上の事は分からない。此処は分析持ちの二人に任せるべきか。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "獲物は鈍器のようですね、頭に潰れた跡があります" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "まだ温かい、恐らく一時間以内の犯行だな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "こんな事をするのは、やはり皇帝の手の者と考えるのが自然ですかね" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そうだな、恐らくこれは一種の警告の類だと見て取れる、明日は我が身だぞ" },
  { text: "二人が冷静に状況を分析していく。だが、この二人の推測が確かであれば、ある事実が現実味を帯びてしまう。それは……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "つまり、皇帝は生きていて俺達の｜邪魔《じゃま》をしている……そういうことか?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "……高い確率で、その通りでしょう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "いや、間違い無いな。皇帝は生きていて、裏で手を引いている" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "皇帝が生きている……か、となると俺達の任務は……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "相当困難な物になるな、唯でさえ不可能に近かった任務が、更に困難を極めたことになる" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "後は皇帝が何処まで私達の目的を知っているか……ですね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……余り期待しない方が良い、全部知られていると仮定した上で動くのが無難だろう" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "取り敢えず荷物を持ってこの場を離れましょう、衛兵に見付かると面倒です" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "分かった、勇者も手伝え" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "勿論だ" },
  { text: "俺達は荷物を抱えると、急いでその場を後にした。" },
  { fx: "clear-red" },
  { fade: "out" },
  { hide: "all" },
  { bg: "imperial_capital_night" },
  { fade: "in" },
  { text: "そして宿屋に戻り、日が完全に落ちた頃。俺達は夜間の襲撃に備え、二人ずつペアで部屋を使い交互に見張り番をすることを話し合った。俺とクロセルは普段通り……の筈だったのだが、そこで何故か揉め事になった。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "jito" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺はクロセルで良いか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我はそれで何の問題もない" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "いえ、駄目です、仮にヤマトさんとクロセルさん、私とエルさんとすると、余ったティア様が可哀想ですし何より危険です" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "確かに勇者とティアは……一緒にさせたくはないな、というか誰も勇者と一緒にさせたくないんだが" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "此処は大人しくヤマトさんとニコラスさんのペアで行きましょう、それが一番無難です" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……マジかよ" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "それは僕の台詞だ!僕だって女の子と一緒の部屋がいい!" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "こういう方なので、ヤマトさん、お願いしますね?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "分かった、背に腹は代えられないからな……勇者は俺がしっかりと見張っとくよ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "助かります、では私はティア様と、クロセルさんはエルさんとで良いですね?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "問題無いぞ" },
  { name: "エル", who: "el", expr: "smile", text: "大丈夫です" },
  { name: "ティア", who: "tia", expr: "normal", text: "わたしもヤマトと一緒が良かったのだけれど……アカツキが言うなら仕方ないわね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……決まったな、俺は不本意だが" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "僕も不本意だが……民意というならば仕方ない、王は常に民の声に耳を傾ける物だからね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "お前は王じゃなくて勇者だろ" },
  { text: "面倒な奴と一緒に眠ることになってしまった。まぁ相手さえしなければ害はない。居ない物と考えれば良いだろう。" },
  { hide: "all" },
  { chara: [
    { slot: "left", id: "nicholas", expr: "laugh" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "んじゃ勇者は先に寝てくれ、俺は馬車で眠ったから目が冴えてる" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "分かった、有り難く先に眠らせて貰おう、僕に手を出したりするなよ?" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "馬鹿、する訳無いだろ" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "そうだと良いんだけどね、それじゃあおやすみ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、おやすみ" },
  { hide: "left" },
  { text: "勇者が眠りに落ちたのを確認すると、俺は重い溜息を吐いた。俺は一人見張り番を続ける。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "それにしても……やっぱり生きてやがったか……皇帝の奴" },
  { text: "遺体が見付からない辺りで薄々察してはいたことだ。皇帝とは嫌でも、また相見える事になるだろう。今度は相手も慢心すること無く、全力で俺を殺しに来る筈だ。" },
  { text: "その時に俺は……奴に勝てるのだろうか。……悲観的になっていても仕方がない。俺には仲間が居る。俺達全員が力を合わせれば、乗り越えられない物は無い。そう信じよう。" },
  { text: "そうして俺は、交代の時間が来るまで、考え事に耽りながら、見張り番を続けるのであった。" },

  // ===== シーン8: 決行準備・帝都観光 (EP41) =====
  { label: "recon_day" },
  { fade: "out" },
  { hide: "all" },
  { bg: "imperial_capital" },
  { fade: "in" },
  { bgm: "daily2" },
  { text: "昨晩は皇帝の刺客による襲撃も無く。無事に日は昇り、俺達は宿屋の食堂で、朝食を摂りながら一堂に会していた。会話の内容は言わずもがな。魔王封印の方法を獲得する為に、ヴァルハラ要塞に乗り込むという話だ。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "serious" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "今夜か" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、本来なら念入りに下見をした上で決行に移すべきなのですが、魔王復活の期日が迫っているので今夜決行することになります" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、行動は早いに越した事は無い。相手に対策する時間を与えてはならんからな" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "どういう作戦を取るんだ?無策で乗り込む訳でも無いだろう?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それは今から説明します" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "まずクロセルさんとニコラスさんが正面から要塞に入り、衛兵を陽動します" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "妥当な所だな、その二人はどうやっても目立ってしまう" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、そして私とヤマトさんの二人で壁を抜きながら皇帝の部屋を目指します。そしてそこにあるであろう｜石版《せきばん》を回収した後に、そのまま脱出します" },
  { name: "エル", who: "el", expr: "troubled", text: "あの……私とティアお嬢様はどうすれば……" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "宿で待機になります、私達が目的を果たした場合、そのまま宿に戻り合流、ティア様の魔法で派手に花火でも撃って貰えれば、それが陽動班への合図になります" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "陽動班は合図が見え次第撤退、追手を振り切ってから昨日の馬車との合流場所で落ち合いましょう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そして、そのまま帝都を離れるんだな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "はい、そうなります。その後は｜魔窟《まくつ》のある街\"ロイトン\"を目指します" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ロイトンと帝都は徒歩で行ける距離なのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "残念ながら、一晩で辿り着ける距離では無いですね、帝都からある程度離れた場所で一晩野宿して向かうことになります" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "なるほど、良く分かった" },
  { text: "俺はアカツキの言葉を噛み砕きながら、何度か頷く。作戦自体は特に穴も見当たらない。人選も妥当な所だろう。実戦経験の浅いエルとティアを待機させるのは正解だと思える。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私は昼間の内に要塞内の構造を把握しに下見に行ってきます。日が落ちた頃に宿で集合で、それまでは自由行動で構いません" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "外から見ただけで内部構造なんて分かる物なのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はい、大体は把握できます。分析の才能の賜物ですね" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうか、やっぱり分析の才能は凄いな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私もそう思います、それではお先に失礼しますね" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "おう、気を付けろよ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はい、では行ってきます" },
  { text: "アカツキが席を立ち、そのまま歩いて行く。その背を見送り、彼女の姿が完全に見えなくなった頃合いを見計らって、俺も席を立つ。" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人も何処か出掛けるのか?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、散歩でもして時間を潰そうと思ってな。お前も着いて来るか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人が行くというのなら我も着いて行こう" },
  { name: "エル", who: "el", expr: "smile", text: "あっ……私もお供します" },
  { name: "ティア", who: "tia", expr: "laugh", text: "わたしも!" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……やっぱりこうなるか" },
  { text: "薄々覚悟はしていたが、結果として勇者を除いた三人を連れて行くことになった。と言っても、やることは所詮散歩。何も面白い事など無い筈なのだが。とまぁ、そういうことで。俺達は帝都を｜縦横無尽《じゅうおうむじん》に歩いていた。" },
  { bgm: "town" },
  { chara: [
    { slot: "left", id: "el", expr: "normal" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "crocell", expr: "normal" },
    { slot: "farright", id: "tia", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人……本当に只歩くだけなのだな" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "当たり前だろ、俺は一文無しだからな、都の賑わいを見て楽しむぐらいしかすることが無い" },
  { name: "エル", who: "el", expr: "smile", text: "でも、私は楽しいですよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、俺も案外こうやってひたすらに歩き回るだけでも楽しめる人種だ" },
  { name: "ティア", who: "tia", expr: "sad", text: "わたしはつまらないわね……何か見世物でもやってれば良いのだけれど" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "生憎、そんな空気じゃないな……帝都は" },
  { text: "王都に負けず劣らず、帝都も確かに活気や人で溢れ返っている。しかし、何処か空気がピリピリしているのだ。それは武装した人間が多いからだろう。その内訳は冒険者が二割、他の八割は兵士である。これほど兵士が多い街も俺は初めて見た。そのせいか、良くも悪くも、治安は良さそうである。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いや、昨日のあれを考えると治安が良い訳でも無いか……" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "あれは例外だろう、少なくとも王都より帝都の方が争い事や揉め事は少ない、治安は良い方だと言える" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……久々に心を読まれたな" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "別に心を読んだ訳ではない、我はご主人の言葉に反応しただけだぞ!?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、余りに的確な反応で心を読まれたのかと思った" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人は疑り深いな……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "心外だ、慎重と言って欲しい" },
  { text: "ふざけてクロセルの頭に拳を投げ込み、ばしんと弾かれる。その様子を見て、驚いたような顔をしているエルが目に入る。そう言えばこの子には説明していなかったな。" },
  { name: "エル", who: "el", expr: "surprised", text: "ヤマト様……それは、その……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "これはディザビリティ。俺の傷害の才能指数は0なんだ" },
  { name: "エル", who: "el", expr: "surprised", text: "ディザビリティ……ですか、それは不便そうですね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "確かに不便だが、直ぐに手が出る俺にはこれぐらいの枷があった方が丁度良い" },
  { name: "エル", who: "el", expr: "normal", text: "なるほど……そういうものなんですね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あとまた敬語に戻ってるぞ、俺のことは呼び捨てで良い" },
  { name: "エル", who: "el", expr: "blush", text: "別に私は構わないんだけど、呼び捨てだとティア様と被るから私はヤマト様って呼ばせて欲しいな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "どうして被ることを気にするのか分からないんだが……まぁ良いか、呼び方はそのままで" },
  { name: "エル", who: "el", expr: "smile", text: "うん、ありがとう。ヤマト様" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……中途半端にタメ口ってのも慣れないな" },
  { name: "エル", who: "el", expr: "smile", text: "ヤマト様が言ったんだからね、不自然なのが気持ち悪いと言うならいつでも戻すよ" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "ならまぁ適度に使い分けてくれ、俺と直接話す時だけ砕けた口調にしよう、それなら特別感があって良い" },
  { name: "エル", who: "el", expr: "smile", text: "それはまた難しい注文だね……まぁ善処するよ" },
  { text: "その後、俺達は日が暮れるまで帝都を歩き回り、観光に興じた。四人で宿に戻ると、既に勇者は待機していた。後はアカツキが揃うのを待つばかり。そして、俺達は静かに作戦が決行される時を待つのであった。" },

  // ===== シーン9: 作戦決行・開いていた金庫 (EP42) ◆B04 =====
  { label: "fortress_raid" },
  { fade: "out" },
  { hide: "all" },
  { bg: "valhalla_gate", instant: true },
  { fade: "in" },
  { bgm: "suspense" },
  { text: "夜。ヴァルハラ要塞、正門前。その前に二人の人影が躍り出る。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "laugh" },
    { slot: "right", id: "nicholas", expr: "serious" },
  ] },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "さて、始めるとするか" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "これも魔王退治の為……そう、これは悪い事じゃないんだ……僕は正義に違いない" },
  { name: "クロセル", who: "crocell", expr: "angry", text: "何をぐずぐずとしている、ゆくぞ!" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "よーし……聖剣フルティンの力を見せてやる!" },
  { fx: "shake" },
  { se: "explosion" },
  { text: "クロセルの足元に魔法陣が浮かび上がったかと思えば、突如｜虚空《こくう》から水が溢れ、濁流が正門へと押し寄せ――堅く閉ざされた門を水流の力だけで吹き飛ばした。突然の敵襲に、要塞は混乱状態に陥る。" },
  { name: "兵士", text: "ごぼっ……敵襲!敵襲!" },
  { name: "兵士", text: "敵影は……二人です!" },
  { name: "兵士", text: "馬鹿な、たった二人でこの要塞の鉄壁の守りを打ち破る気なのか!?" },
  { name: "兵士", text: "正門突破されました!接敵まで3!2!1!接敵します!" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ふむ、こんな物か……後は適当に敵を蹴散らすだけだな、射線に入るでないぞ?祝福の勇者よ" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "ははは!僕は祝福の勇者だからね!入っても大丈夫だ!" },
  { fx: "flash" },
  { text: "正門を破った水は消失し、陣形もままならない兵士の海へと勇者が斬り込んで行く。その後方でクロセルが詠唱。お得意の水弾の嵐が、片っ端から兵士達の身体へと叩き込まれる。" },
  { text: "幸運にも、兵士達は｜鎧兜《よろいかぶと》で重装備していた為、クロセルの攻撃で致命傷を負うことは無さそうである。最も、クロセルが少しでも出力を上げれば、兵士達の身体は風穴だらけになるのだろう。流石はクロセル、兵士達を無力化して殺さない｜匙加減《さじかげん》を弁えている。" },
  { name: "兵士", text: "ぐっ、増援を呼べ!このままだと押し切られるぞ!" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "ははは!脆い脆い!君達のような雑魚がこの僕に適う筈もあるまい!全て聖剣の錆にしてくれよう!" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "祝福の勇者よ!そのまま前進して要塞内に入るぞ!" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "分かった!" },
  { hide: "all" },
  { bg: "imperial_capital_night", instant: true },
  { text: "倒れた兵士の数は遠目には数え切れない。この短時間で｜死屍累々《ししるいるい》と戦闘不能者の山を築き上げたのだ。流石は最大戦力、恐ろしい二人組である。やがて、二人の姿は要塞の中へと消えて行く。恐らく、続けて中で戦闘が繰り広げられているのだろう。" },
  { text: "そんな一部始終を、俺とアカツキの二人は、要塞の近くに位置する高い時計塔から見守っていた。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "serious" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "頃合いか" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうですね、そろそろ行きましょうか" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "要塞まで結構距離があるが……いけるか?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "いけます、｜魔術回路構築《クリエイト》……詠唱……ル・トゥーム・アルガス・ティル……空間魔術……｜接続《コネクション》!" },
  { se: "magic" },
  { fade: "out" },
  { bg: "valhalla_interior", instant: true },
  { fade: "in" },
  { text: "俺とアカツキの眼の前に、空間を引き裂いたような穴が生まれる。その先には、要塞内部らしき石畳と石壁に覆われた空間が広がっていた。｜躊躇《ためら》う事無く二人で中に入る。これで要塞内に侵入出来た。" },
  { text: "思惑通り、警備の人間は見当たらない。この調子なら、作戦遂行も現実的かもしれない。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "serious" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "皇帝の部屋はどっちだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "こっちです" },
  { text: "音を殺して小走りで、要塞内を進んでいく。" },
  { text: "要塞は王城以上に入り組んでいた。それは言うなれば人為的に作られた迷宮、侵入者を迷わせる事を目的とした造りになっている。だが確実に道はある。" },
  { text: "どんなに複雑な構造であっても、要塞として機能させる為には構造を把握した人間が真っ直ぐ目的の場所に向かえるようになっていなければならない。" },
  { text: "故に、必ず目的の場所に辿り着く道はあるのだ。そこに辿り着く道程に差はあれど。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "serious" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "此処で、壁を抜きます" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ショートカットか、本当に要塞の構造を把握してるんだな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "半日の間、要塞を観察、分析したんですから、これぐらいは出来て当然です" },
  { text: "そう言うアカツキの表情は、少しだけ得意気だった。良くやった、と小さな声で呟きながら、思わず手を伸ばし、アカツキの頭を撫でる。" },
  { chara: { slot: "left", id: "akatsuki", expr: "surprised" } },
  { text: "アカツキはそれに一瞬驚いた様子を示しつつも、嫌ではないのか、なすがままになる。だがそれも一瞬、クロセルと勇者が稼いでくれた時間は無駄にしてはならない。アカツキは直ぐに真面目な表情に戻ると先程と同じ詠唱を唱え、二箇所の空間を繋げる。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そんなに魔術を乱発して大丈夫なのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "実は大丈夫でも無かったりします、帰りの事を考えると壁を抜けれるのは次がラストです" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "やっぱり魔術も無制限に撃てる物じゃないんだな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はい、クロセルさんのような存在が規格外なだけです" },
  { text: "そうして会話を短く済ませると、空間の穴を潜り、俺達は更に先に進む。そして、十分程度要塞の中を走り回った頃。俺達は目的の部屋の前に辿り着いた。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁ、当然ではあるが……鍵掛かってるな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "此処まで来て出し惜しむ理由もありません、繋げます" },
  { text: "アカツキが詠唱し、部屋の中と外を繋ぐ。空間の穴を通り、部屋の中に入ると……俺とアカツキは手分けして目当ての物を探し始めた。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "｜石版《せきばん》なんだよな?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "はい、｜石版《せきばん》で間違いないです、大きさはこれくらいで……あ" },
  { text: "アカツキが手で大きな四角を作りながら、俺の大きさを指し示したかと思えば、俺の背後に視線が移り、そのまま静止する。何事かと思ってアカツキの視線の先へと振り向いてみれば……そこには金属製の金庫が置いてあった。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なるほどな、こりゃ見るからに怪しい" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私もそう思います、大きさも丁度その中に入るぐらいですし" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "取り出せそうか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "勇者の鎧と同様、魔術では干渉出来ないように対策されてますね……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……金庫ごと持ち出すか?" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ヤマトさんそこまで怪力じゃないですよね?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "だよな……どうした物か" },
  { text: "ダメ元で金庫の扉に手を掛け、引いてみる。すると……金庫は呆気無く、ガチャ、と音を立てながら開いた。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "マジ?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "驚きましたね……そんな、まさか……" },
  { text: "鍵を掛け忘れたのだろうか。中を確認してみれば、そこには一枚の｜石版《せきばん》が入っていた。" },
  { comment: "◆B04 分岐ポイント: 開いていた金庫" },
  { choice: [
    { label: "｜石版《せきばん》を掴んで撤収する", jump: "b04_take_and_go" },
    { label: "開いていた金庫を怪しむ", jump: "b04_doubt", kind: "if" },
  ] },

  // ----- 正史: そのまま回収 -----
  { label: "b04_take_and_go" },
  { text: "深く考える時間は無い。俺は｜石版《せきばん》を取り出した。石に文字列が刻まれており、目的の物で間違いなさそうである。大体の文字列は俺でも読めたが、一部読めない文字、俗に言う魔術言語って奴が所々で使われている。", tid: "ch03__b04_take_and_go__01" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ヤマトさん、見せて下さい" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ほら、これだ……間違い無いか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はい!確かにこれです、私は一度この｜石版《せきばん》を見ているので、間違いありません", tid: "ch03__b04_take_and_go__02" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、ならこれを持ってさっさと逃げるぞ、退路は任せた", tid: "ch03__b04_take_and_go__03" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "任せられました、着いて来て下さい", tid: "ch03__b04_take_and_go__04" },
  { text: "内側から鍵を開けて皇帝の部屋を出る。すると少し遠くから人の走ってくる足音が近付いてきた。別段騒ぎは立てていない筈だが……俺達の存在を勘付かれたのだろうか。", tid: "ch03__b04_take_and_go__05" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まずいな、このままだと鉢合わせになるぞ", tid: "ch03__b04_take_and_go__06" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "足音から推測するに敵は一人、交戦します", tid: "ch03__b04_take_and_go__07" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "分かった、前衛は任せろ" },
  { text: "そのまま先に進むと、案の定。一人の兵士と鉢合わせになる。", tid: "ch03__b04_take_and_go__08" },
  { text: "兵士は俺達の姿を視界に捉えると、剣を抜いて牽制してくる。" },
  { name: "兵士", text: "お前ら……侵入者か!?俺に見付かったからには何処にも逃さん、大人しく降伏しろ!", tid: "ch03__b04_take_and_go__09" },
  { name: "ヤマト", who: "yamato", text: "おう、やるってなら俺が相手になる", tid: "ch03__b04_take_and_go__10" },
  { name: "兵士", text: "ははは……武器も無しで立ち向かってくるとは威勢だけは良いんだな!お覚悟!" },
  { name: "ヤマト", who: "yamato", text: "アカツキ、やれ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "時間稼ぎ感謝します、空間魔術……｜亜空切断《ディメンションカッター》!", tid: "ch03__b04_take_and_go__11" },
  { se: "slash" },
  { fx: "flash" },
  { text: "俺と兵士が睨み合った一瞬の間に、アカツキが後ろで詠唱を終える。それは見事に不意打ちとなり、剣を構えた兵士の利き腕が空間ごと綺麗に切断される。", tid: "ch03__b04_take_and_go__12" },
  { name: "兵士", text: "ぐあぁぁぁあああああ!?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "残念だったな、悪く思わないでくれよ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "行きましょう、ヤマトさん" },
  { name: "ヤマト", who: "yamato", text: "おう" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "アカツキって結構えぐいことするよな", tid: "ch03__b04_take_and_go__13" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "可哀想ではありますが、戦闘不能にするにはあれが一番手っ取り早いので……", tid: "ch03__b04_take_and_go__14" },
  { text: "片腕を失い、激痛でのたうち回る兵士を一瞥すると、そのまま兵士を無視して先に進む。そして要塞を駆け回り、二度壁を抜けると、遂に要塞の外に出る事に成功する。俺の手には確かに｜石版《せきばん》が握られており、追手らしき者も無し。此処までは物の見事に完璧だ。", tid: "ch03__b04_take_and_go__15" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "正門の様子はどうだ?", tid: "ch03__b04_take_and_go__16" },
  { name: "アカツキ", who: "akatsuki", text: "微かですが騒ぎが聞こえます、まだクロセルさんとニコラスさんがやりあってるみたいですね", tid: "ch03__b04_take_and_go__17" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "見事な陽動だ、後で褒めてやらんとな", tid: "ch03__b04_take_and_go__18" },
  { name: "アカツキ", who: "akatsuki", text: "では宿に戻りますよ、エルさんとティア様と合流しましょう", tid: "ch03__b04_take_and_go__19" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうだな" },
  { jump: "el_wounded" },

  // ===== シーン10: 宿の前の血溜まり (EP42〜43) =====
  { label: "el_wounded" },
  { fade: "out" },
  { hide: "all" },
  { bg: "imperial_capital", instant: true },
  { fade: "in" },
  { text: "俺とアカツキは、要塞を出た後に、真っ直ぐ宿へと向かった。エルとティアとは、荷物を纏めて宿の前で待機している約束だ。故に、宿に戻ったら真っ先にその姿が見える筈なのだが……" },
  { bgm: null },
  { fx: "red" },
  { fx: "shake" },
  { text: "そこにあったのは血溜まり。そしてその中に倒れ込む人影。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "surprised" },
    { slot: "right", id: "yamato", expr: "surprised" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "嘘……だろ……?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "エルさん!?大丈夫ですか?" },
  { text: "俺は｜石版《せきばん》を抱えたまま、呆然と立ち尽くした。余りの出来事に思わず脳が理解を拒む。が、込み上がる絶望を飲み込み、脳を無理矢理に回転させて状況を冷静に整理する。" },
  { text: "倒れている人影、これはエルだ。約束通り宿の前で待っていたのだろう、近くには荷物も散乱している。ティアは……何処だ?少なくとも俺の視界には見当たらない……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くそっ、待たせるのが安全だと思った俺が馬鹿だった" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "いえ、この作戦を考えたのは私。これは私の落ち度です。ティア様が居ないとなると……ヤマトさん、要塞に行ってクロセルさんと勇者を呼んで来て貰えますか?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ、分かった" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "私は彼女を連れて行きます、作戦通り、例の場所で落ち合いましょう" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……気を付けろよ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ヤマトさんこそ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "じゃあ行ってくる!" },
  { text: "俺は無我夢中で走り出す。走りながら状況を分析する。ティアは遺体も無かった事から連れ去られたと考えるのが妥当。エルはあれだけ出血していたとなると、傷の深さにもよるがかなり危ない状況だろう。" },
  { text: "ただ外傷だけなら生きている限りクロセルの回復魔術で対応できる。これに関しては一刻も早く合流することが急務だろう。" },
  { text: "主犯格は皇帝で間違いない。が……あれが皇帝自身の犯行だとは思えない。皇帝の手の者による犯行だと考えるべきだ。ステラか?いや違う。それは有り得ない。冷静に考えれば、皇帝の手の者など俺の知らない所に幾らでも居る。特定しようと考えても無駄だ。" },
  { bgm: "tension2" },
  { fx: "clear-red" },
  { fade: "out" },
  { hide: "all" },
  { chara: [
    { slot: "left", id: "crocell", expr: "serious" },
    { slot: "center", id: "nicholas", expr: "surprised" },
    { slot: "right", id: "yamato", expr: "angry" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "はぁ……はぁ……着いた、クロセル!勇者!居るか!?" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "ヤマト君!?何故此処に!?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人……何かあったのだな?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、何かあった。取り敢えず要塞での用事は済んだから時間稼ぎはもういい、例の場所まで逃げるぞ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "……我は先に行くべきか?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、先に行ってくれ、俺達は後から追い付く" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "承知した、ご主人も気を付けるのだぞ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前……は心配する必要も無いな、取り敢えず急いでくれ、頼んだ" },
  { hide: "all" },
  { text: "クロセルは魔術による身体強化からの高速移動で、一人先に帝都を走り抜けて行く。相変わらず人間離れした動きだ。そして残された俺と勇者は、兵士の追手から逃げる事となった。" },
  { text: "と言っても、意外にも勇者の体力は俺に負けず劣らず中々の物で、俺達は帝都を縫うように走り続けることで、いとも簡単に兵士を振り切ることに成功した。そして、完全に撒いた事を確認すると、俺達は真っ直ぐに集合場所へと向かうのであった。" },
  { bg: "country_road", instant: true },
  { fade: "in" },
  { text: "そして集合場所へ。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "normal", text: "む、戻ったかご主人" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あぁ、全員無事か?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "大丈夫です、ティア様も含めて全員居ます" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……?ティアは連れ去られた筈じゃ……" },
  { text: "慣れない長距離走で息を切らしつつ、慌てて周囲を見渡す。しかし、何ということだろう。ティアは確かにそこに居た。怪我をしているようにも見えない。床に転がされたまま眠っているようだ。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "どうやら今回の犯人は、ティアを眠らせて此処まで連れてきた後に、捨て置いたようだ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "意味分からないぞ?犯人は何がしたいんだ……?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、我としてもそこが不可思議であった、ただ、状況的にはこれが二度目の警告と取るのが無難な所だろう" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "わざわざ警告なんて回りくどい真似をせずに、エルとティア、直接戦力を潰しておいた方が相手としては有利になる筈だが" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我々を脅して生かしておく理由があるのだろう、それが何なのかは現状不明だが" },
  { text: "犯人は傷を負ったエルにとどめを刺す事も出来た。ティアに至っては誘拐したまま交渉材料にすることも出来た筈だ。それなのにどちらも中途半端、決定的な事を起こしていないというのは、とても不自然な事に思えた。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "取り敢えず全員無事なら何よりだ、エルが死んで、ティアも連れ去られたのかと思ったから焦った" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "エルに関してはかなり危ない所だったな、あと数刻遅れていれば命はなかったかもしれん" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "話は出来そうか?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "無理だな、逸る気持ちも分かるが、話を聞くのは後にしよう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なら、動かす分には問題無いか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "傷は完全に塞いだ、運ぶ分には問題無い筈だぞ" },
  { text: "相手は一体何が目的なのだろう。俺達を泳がせておく理由は何なのだ?幾ら考えても、俺には到底理由が思い浮かばなかった。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、なら予定通り、ロイトンを目指そう" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうですね、あれだけ騒ぎを起こした以上、帝都に長居することも出来ませんし" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "俺がエルを運ぶ、ティアは……勇者、任せていいか" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "勿論だよ、僕に任せてくれ" },
  { text: "勇者にティアを任せるのは、実のところ、些か不本意だ。しかし、力仕事の出来る男手が二人しか居ない以上、つべこべ言っては居られない。仲間が全員居るのを再確認すると、俺達は最寄りの帝都の城壁へと向かった。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "アカツキ、撃てるか?" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "少し厳しいです、クロセルさん、お願い出来ますか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "任せられた。｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》……空間魔術……｜接続《コネクション》!" },
  { chara: [
    { slot: "left", id: "crocell", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "前から思ってたが……ティアやアカツキが略式詠唱を使わないのは何でなんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "略式詠唱の難易度が高すぎるんですよ……並大抵の才能の持ち主じゃ出来ません、それに魔力消費も増えるので……人間が使う物じゃないですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なるほどな……クロセルは魔力が無尽蔵だからあれだけぽんぽんと略式詠唱を使う訳だ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "と言っても、別に略式詠唱が悪いという訳ではないのだぞ。戦場では数秒の差が生死を分ける事になるからな。まぁ……確かに常に略式詠唱をする必要は無いと思っているのだが、こればっかりは癖なのだからどうしようもない" },
  { text: "城壁とその外部を繋げた空間の穴を通り、俺達は森の中へと姿を消す。その後は、アカツキの言葉を頼りに、ロイトンを目指して森を進む。数時間は歩いただろうか。森を抜け、俺達は広い草原を進む。" },
  { text: "障害物が無い為に、遥か先まで見通せるが、まだ街らしき物は見えてこない。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "やはり徒歩だと遠いな、ロイトン" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "馬車でも一晩は掛かる距離ですからね、そう直ぐには辿り着けませんよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "追手も流石に此処までは追いかけてこないだろうし、今夜はこの辺で野宿したらどうだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね、少々目立ちますが、魔物のことを考えれば此処の方が森の中より安全かもしれません" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうと決まればテントを建てようか、荷物は持ってきてるか" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我とアカツキが半分ずつ持ってるぞ、今広げるから待っておれ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、助かる" },
  { text: "背負っていたエルを地面に降ろし、横たわらせる。そして俺はテントの設営を手伝った。前世でも野宿する機会は多かった為、この手の作業には慣れている。物の数分で見事にテントが建った。これは俺だけの力ではない、クロセルも中々手際が良かった。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "流石に全員は入れなそうだな" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね……エルさんとティア様は確定として、二人は入れそうです。私とクロセルさん、ヤマトさんと勇者さんのペアで眠って、頃合いを見計らって見張りを交代しましょうか" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうだな、そうと決まれば時間が惜しい、俺はさっさと寝させて貰おう" },
  { chara: [
    { slot: "left", id: "nicholas", expr: "depressed" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "僕も今日は中々に働いたよ……お疲れ様、ヤマト君" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "おう、お疲れ様だ、勇者" },
  { text: "勇者ニコラス。馬鹿でどうしようもない奴ではあるが、決して悪い奴では無い。今日も彼が居なければ大変な事になっていただろう。だから俺は、勇者にささやかな感謝を抱きつつ、そのまま静かに眠りに落ちた。" },

  // ===== シーン11: 野宿の夜の抱擁 (EP43) =====
  { label: "starlit_vow" },
  { fade: "out" },
  { hide: "all" },
  { bg: "country_road_night" },
  { fade: "in" },
  { bgm: "romance" },
  { text: "それから数時間が経ったのだろう。俺はクロセルの声で目を覚ました。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "normal" },
    { slot: "right", id: "yamato", expr: "sad" },
  ] },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人、ご主人、アカツキと交代してやってくれ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ん……あぁ、そうだったな、悪い" },
  { text: "数回の呼び掛けで意識はゆっくりと覚醒する。俺は僅かに残る眠気を振り払って起き上がり、テントを出る。" },
  { hide: "all" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ヤマトさん、すいません、感謝します" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "気にするな、見張りご苦労だったな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "いえいえ、では失礼します、おやすみなさい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、おやすみ" },
  { hide: "left" },
  { text: "夜。テントの外、見張りでクロセルと二人きりになる。" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "……久々にご主人と二人きりだな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう久しい訳でも無いだろ、それとお前は勇者と交代しなくて良いのか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我は眠る必要が無いのでな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "完全に忘れてた、そう言えばそうだったな" },
  { text: "クロセルにとって眠りは休息。必須ではないのだ。と言っても、今夜はクロセルも中々に無理をしている筈なのだが、休息は必要ないのだろうか。まぁ、本人が大丈夫と言うのなら信じよう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "夜が明けたら出発、ロイトンに着いたら｜魔窟《まくつ》を踏破して最深部まで行けるようにしないといけないんだよな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "そうだな。｜猶予《ゆうよ》は残り5日、かなりのハードスケジュールになる" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "クロセルは大丈夫、俺や勇者も丈夫だから大丈夫だと言え、怪我人のエルと幼いティアには無理をさせる事になるな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人が選び、連れてきたのだ、覚悟は決めているのだろう?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、勿論だ。俺の見立てで今回の任務に彼女達の力が必要なのは事実、多少無理をさせてでも俺達は任務を遂行せねばならない" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "相当に無茶な任務だがな、我も正直成功するとは思っていない" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "クロセル奪還の時も似たような空気だったが、何とかなっただろ、人間の底力ってのは案外侮れないんだぞ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "そうだな、特にご主人に至っては……持ち得ない才能を呼び覚まし使うような芸当までこなしてみせた。全く人間には驚かされてばかりだ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あの時は無我夢中だったからな、お前を取り戻せて本当に良かったと思っている" },
  { text: "そんな話をしていると、無性に人肌が恋しくなってきた。俺は、すぐ横に座るクロセルの腕を引いて、そのまま抱き寄せる。突然の抱擁に驚いたように目を丸くするが、直ぐにその真意を察したのか、俺の胸の中で大人しくなる。" },
  { chara: { slot: "left", id: "crocell", expr: "blush" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……約束は｜違《たが》えるなよ" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "勿論だ……我は完璧なのでな" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あと、勘違いするなよ、今の俺にとって一番は……お前だ、クロセル" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "そうか……っそれは……っ少し……っ予想外かもしれんな" },
  { text: "ゆっくりと紡がれる言葉に、｜嗚咽《おえつ》が交じる。クロセルは、笑いながら涙を流していた。それがどういう意味か、俺には理解できなかったが。" },
  { text: "七百年。こいつが一人で抱えてきた孤独の重さを、俺は本当の意味では分かってやれない。それでも――この涙だけは、二度と流させたくないと思った。" },
  { cg: "cg_starlit_vow" },
  { wait: 600 },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "必ず生きて二人で帰るぞ、大事なことだから何度でも言う。――絶対に、二度と、俺の側から離れるな" },
  { text: "俺は確かに腕の中にある温もりを、ただ強く強く抱き締めた。" },
  { cg: null },

  // ===== シーン12: ロイトン (EP44) =====
  { label: "loiton_ruins" },
  { fade: "out" },
  { hide: "all" },
  { bg: "loiton_makutsu" },
  { bgm: "sad2" },
  { fade: "in" },
  { text: "夜が明けると共に、俺達は再出発した。エルが目覚めなかった為、俺は再びエルを背負って歩くことになった。ティアの方は、明け方に目を覚ました。道すがら話を聞き出せないかと試みたが、襲撃から直ぐに眠らされた為、何も覚えていないという。" },
  { text: "ただ、襲撃があったという確固たる事実はこれで否応無しに浮かび上がる。次に考えるべくは、昨日覚えた違和感の正体だが……残念ながら俺にはまだ何も分からない。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "surprised" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あれが……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "えぇ、あれがロイトンです" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "帝都ばりに大きな防壁があるんだな" },
  { text: "半日近くの行程の果て、遥か遠くに都市の存在が見えてくる。帝都と同じように厚い防壁に囲まれた都市。……これだけならば別にありきたりな都市なのかもしれない。だが、俺は直ぐにその都市の抱えた\"異常\"に気が付いた。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "防壁に入口が無いぞ……?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "それは……直に分かると思います" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いつもの方法で入るんだな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "はい、そうなります" },
  { text: "クロセルが詠唱し、防壁の内部と外部を繋げ、空間の穴を生み出す。それを潜ると、たちまち身を包む、酷い匂いに悪寒を覚えた。この匂いには覚えがある、腐敗した死体の匂いだ。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "これはまた……酷いな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "これが……迷宮都市の末路です" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "迷宮から無限に湧き続ける魔物の流出に耐えきれなくなり、都市は崩壊。被害拡大を防ぐ為に、防壁で外部から隔離、そんな所か" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ご明察です、クロセルさん" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "こりゃまるで……牢獄だな" },
  { text: "此処も、過去にはそこそこに発展した都市だったのだろう。損壊した建物跡や、舗装された道路から、そう察せられる。しかし、今のこの街は、｜廃都市《はいとし》と形容するに相応しい惨状と化している。" },
  { text: "道を進めば、何度だろうと嫌でも人の死体が視界に入る。息をすれば、腐敗物の臭気と血の匂いが胸の中を｜蝕《むしば》む。今のこの都市で心を落ち着かせられる場所は、何処にも無かった。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "迷宮ってのは、どうすれば消えるんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "最深部に封印されている物を解放すれば、時間と共に自然に消失します" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なるほど、ロイトンの迷宮は最深部に魔王が封印されている。仮に最深部まで辿り着いた者が居たとしても、その封印を解けなかったからこの街は此処まで酷い事になってるんだな" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "はい、帝国からも死んだ土地として放棄されているのが現状です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "住人は居るのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "｜魔窟《まくつ》に挑もうとする勇敢な冒険者が居るので、機能している宿が幾つかある筈です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "この都市は外部から入れないんじゃ……" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "正確に言えば\"一度入ったら出られない\"が正解です、傍目には分かりませんが、入口自体は存在します" },
  { text: "そのまま都市を進み、大きな通りに出る。アカツキが宿を探し辺りを歩き回る、俺達はそれに付き従うようにして進んだ。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "sad" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "ダメですね……この通りは全滅です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "適当な｜廃墟《はいきょ》を見繕って泊まるか" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "そうですね……そうしましょう" },
  { text: "残念ながら、機能している宿は見付からなかった。" },
  { text: "俺達は損壊の小さな家屋を見繕い、そこを拠点とすることになった。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ふぅ……良く歩いた、疲れたな" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "今日の所はこれ以上行動は起こしません、明日からは｜魔窟《まくつ》探索に明け暮れる事になりますからね、ゆっくり休んで下さい" },
  { hide: "all" },
  { text: "その夜、拠点の廃屋。背中で眠っていたエルの目が覚めた。" },
  { chara: [
    { slot: "left", id: "el", expr: "sad" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "エル", who: "el", expr: "sad", text: "……っ、此処……は……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "エル?目が覚めたか?" },
  { text: "背中から小さな声が聞こえる。どうやらエルの目が覚めたようだ。俺は直ぐに彼女を部屋のベッドに降ろし、座らせた。まだぼんやりとしていて、目の焦点が定まらないが、どうやら何とか会話は出来そうだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "エル、貧血でまだ辛いと思うが、少し話を聞いても良いか?" },
  { name: "エル", who: "el", expr: "troubled", text: "ぁっ……うっ……はい、大丈夫……" },
  { text: "状況の整理が付いてきたのか、片手で頭を抑えながら返答すると、律儀に俺に向き直る。" },
  { name: "エル", who: "el", expr: "troubled", text: "昨夜の襲撃の事……だよね?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだ、覚えてる事があったら聞かせて欲しい" },
  { text: "合点がいったとばかりに一つ頷き、深呼吸すると、エルは口を開き、ゆっくりと語り出した。" },
  { name: "エル", who: "el", expr: "troubled", text: "私はティア様と一緒に、宿の前で荷物を纏めて待っていた" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、こっちもクロセルと勇者、俺とアカツキに分かれて行動していた" },
  { name: "エル", who: "el", expr: "normal", text: "そして、私達は唐突に襲われたんだ。敵は一人、私は敵の気配を感じ取ると、短剣を抜いて応戦した" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "敵は一人か" },
  { name: "エル", who: "el", expr: "normal", text: "うん、確かに一人だった。獲物は無し、相手は素手で立ち向かってきたんだ。あれは……恐らく才能の差だったね、結論から言えば私は敗北した" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセル、素手の戦闘にも才能があるのか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "うむ、徒手格闘の才能が存在する" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "相手は一人で徒手格闘の才能持ち、他に覚えてる事はあるか?" },
  { name: "エル", who: "el", expr: "blank", text: "……終始笑っていた、まるで戦闘を楽しむようにね。声色は男とも女とも断定し辛い、兎に角恐ろしかった……かな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、取り敢えずエルの身に起きた事は分かった、参考になったよ、ありがとう" },
  { name: "エル", who: "el", expr: "smile", text: "いや、ヤマト様の力になれたのなら良かったよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "明日からは忙しくなるからな、ゆっくり休んでくれ" },
  { name: "エル", who: "el", expr: "smile", text: "そうだね、私なんかを気にかけてくれるなんて、嬉しいよ、ありがとう" },
  { text: "エルは俺の顔を見つめると、小さくお辞儀をして、はにかんで笑った。相変わらず笑顔とは眩しい物だ。でも……今日は普段とは少し違う感覚。なんだか笑顔で力を貰えた気がする。まさか、こんな事を思う日が来るとは思わなかった。" },
  { hide: "all" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "じゃあ、俺も休んでいいか、エルを背負って此処まで歩いて来たんだ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね、ヤマトさんはゆっくり休んで下さい" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "ご主人もお疲れ様だな、我が側に居てやるから安心して休むがよい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "助かる……それじゃあ、おやすみ" },
  { hide: "left" },
  { chara: { slot: "left", id: "nicholas", expr: "depressed" } },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "僕も何故かティアを背負って来る事になったし疲れたんだけど!寝ても良いかな?" },
  { hide: "left" },
  { chara: { slot: "left", id: "akatsuki", expr: "smile" } },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "申し訳ありません、ニコラスさん、｜魔窟《まくつ》までの道を確認しておきたいので、用心棒お願い出来ますか?" },
  { hide: "left" },
  { chara: { slot: "left", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "そうだ、働くのだ勇者よ、キリキリとな" },
  { name: "ティア", who: "tia", expr: "angry", text: "そうよ!祝福の勇者なんだからちゃんと働きなさい!" },
  { hide: "left" },
  { chara: { slot: "left", id: "nicholas", expr: "depressed" } },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "うっ、ぐっ、分かったよ……働けば良いんでしょ働けば……" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "文句があるんですか?" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "無いよ!?どうして僕を疑ったりするんだい!?" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "日頃の行い……" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "常日頃からご主人のように真面目に生きてれば良い物を……" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "そんな……僕は真面目に生きているというのに酷い……なんて仕打ちだ……" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "色々と残念なだけであって……悪い人じゃ無いのだと思うんですけどね" },
  { hide: "left" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "それより、アカツキは休まなくて良いのか?この中で一番無理をしているのはお主だろう" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "……そればっかりは確かに否定は出来ませんね、私はこれから｜石版《せきばん》も解読しないといけないので……今夜も眠れなそうです" },
  { chara: { slot: "left", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "くれぐれも無茶をするではないぞ、お主が倒れては我々の道標が無くなってしまう、アカツキの身体はお主一人の物では無いのだからな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうですね、でも私は大丈夫です、信じて下さい" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "うむ、我は信じておる。自愛するようにな" },
  { hide: "left" },
  { chara: { slot: "left", id: "nicholas", expr: "normal" } },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "僕のことは心配してくれないのかい?" },
  { hide: "left" },
  { chara: { slot: "left", id: "crocell", expr: "laugh" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふむ?勇者は祝福があるだろう、存分に無茶するが良いぞ" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "相変わらず扱いが酷いんだけど!?" },
  { text: "今日も賑やかな会話が聞こえる。相変わらず仲良さそうで何よりだ。俺はベッドに横になり、静かに目を閉じる。やがて、俺は眠りに落ちた。" },

  // ===== シーン13: ｜魔窟《まくつ》 (EP45) =====
  { label: "makutsu_descent" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { bgm: "suspense" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "これが……｜魔窟《まくつ》か" },
  { text: "翌日、俺達はアカツキに案内され、｜魔窟《まくつ》に来ていた。此処に来る途中で数度、獣の魔物に遭遇したが、只の魔物など俺達の敵ではなく、クロセルと勇者が即座に処理していた。" },
  { text: "｜魔窟《まくつ》の入口とは、即ち巨大な穴であった。まるで湖を彫り抜いたのでは無いかと思うほどに、巨大な穴が空いている。｜蟻地獄《ありじごく》のような形状のその穴には｜縄梯子《なわばしご》が掛けられており、真っ直ぐ中央へと、地下へと続いている。" },
  { text: "｜縄梯子《なわばしご》は人為的な物だろうが、それ以外は人の手によって整備されている様子も無い。地下であるが故に中は暗いと予想されるが、この様子だと自然の明かりなんて物は無さそうだ。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "まるで｜奈落《ならく》だな……本当にこの先に行くのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "此処まで来てしまった以上、行くしか無いですね" },
  { chara: { slot: "left", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "なんだいヤマト君、怖気付いたのかな?" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あ?なんだと勇者" },
  { chara: { slot: "left", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "全く、ご主人は直ぐに挑発に乗るでない" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "チッ……分かってる、次は無いからな勇者" },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "ほ……ほんの軽口のつもりだったんだけどね……" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "今回の探索では、進める場所まで進んだら座標を記録、魔術で拠点に帰還します。次の探索の際は記録した座標に飛び、同じ場所から探索を続けることになります" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうして最深部を目指すんだな、空間魔法が使えない奴はどうやって探索してたんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "人力でマッピング、迷宮内に籠もる形で探索していたみたいですね" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "よくそんなことをやるな……それほど｜魔窟《まくつ》の最深部に眠ってる物は期待されてた訳だ" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "これでも最大規模の迷宮ですからね、奥にはとんでもない宝が眠っていると噂されていたみたいです" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "その実態は魔王が封印されています、か……そりゃ誰も探索しなくなる訳だ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "地図は冒険者から入手しているので、迷うことは無い筈です、真っ直ぐ最深部に向かいましょう" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "用意がいいな、流石はアカツキだ" },
  { text: "うんうんと頷く。相変わらずアカツキの奴は優秀だ。俺は一度後ろを振り返り、仲間と顔を見合わせる。覚悟を決めた。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、行くか!" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、行きましょう" },
  { fade: "out" },
  { text: "｜縄梯子《なわばしご》を降りて、｜魔窟《まくつ》の中へと進んでいく。明かりがないと本当に何も見えない。暫く闇の中を降りて行くと、やがてストンと足が付く。" },
  { hide: "all" },
  { bg: "makutsu_depths", instant: true },
  { fade: "in" },
  { chara: [
    { slot: "left", id: "crocell", expr: "normal" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "nicholas", expr: "serious" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "クロセル、明かりを" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "｜魔術回路改竄《カスタマイズ》……｜略式詠唱展開《ファストキャスト》。属性魔術……｜光籠手《ライトハンド》" },
  { fx: "flash" },
  { text: "クロセルの手が強く発光し、辺りが照らし出される。｜奈落《ならく》のような穴の底、｜魔窟《まくつ》の入口は、広い回廊になっていた。天井も奥行きもかなり広い。東西南北、どちらに進むことも出来る。" },
  { text: "少しでも動けば、｜縄梯子《なわばしご》の位置を見失ってしまいそうだ。本来ならば、精巧なマッピングが要求されるのだろう。空間魔術が無ければ帰還すら困難そうだ。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "クロセルとアカツキが先導、最後尾は勇者に任せた" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "無難な所だな、はぐれないように付いてくるのだぞ" },
  { text: "俺はティアとエルの手を取り、握り締める。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、こうすれば大丈夫だろう" },
  { text: "拒まれるかもしれないと思ったが、特にそういう反応は無い。最後尾の勇者がはぐれる可能性もあるが、あいつははぐれても大丈夫だろう。死なないし。" },
  { text: "流石にクロセルの光だけでは心許無い為、ティアにも同じ魔法で光を放って貰った。これならそこそこ視野が確保される。" },
  { hide: "all" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "center", id: "crocell", expr: "serious" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、それじゃ進むか" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、私は迷わないように進むのが精一杯なので、戦闘はお任せします" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "任せとけ" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ご主人は戦えないだろう……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……任せた" },
  { text: "言わずもがな、戦えない俺が出張っても｜邪魔《じゃま》になるだけだろう。此処は大人しくしていることにしよう。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "と、早速来やがったか" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "後方だ!勇者!" },
  { chara: { slot: "left", id: "nicholas", expr: "laugh" } },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "これが僕の聖剣だ!フルティィィィン!" },
  { fx: "shake" },
  { se: "slash" },
  { text: "勇者が背後から迫って来ていた人型の魔物を切り裂く。裸で毛むくじゃら、猿と鬼の中間のような魔物だ。それが頭から綺麗に真っ二つにされ、どくどくと血を流している。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "人型を斬るのに抵抗が無いんだな" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "僕は人斬り｜抜刀斎《ばっとうさい》だからね、正義の名の下であれば人だろうと魔物だろうと何でも斬り裂いてみせるさ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "だからお前の剣は刀じゃないだろ……" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "抜剣斎なら文句は無いかい?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "お前剣抜いてないだろ……というかその剣に鞘無いだろ……" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "なら……剣斎?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "まぁ……もう……なんでも良いんじゃないか?" },
  { text: "頭の弱い人間の相手は疲れる。無視しよう。" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "雑談している暇は無い、次が来るぞ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "魔物の｜巣窟《そうくつ》だってのは分かってたが、こうも頻繁に接敵するのか" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "地上に魔物が溢れるぐらいですからね……中はこんな物ですよ" },
  { name: "エル", who: "el", expr: "troubled", text: "左!此処は私が……はっ!" },
  { text: "エルが俺の手を解き、両手で腰から短剣を抜くと、目にも留まらぬ速さで闇の中を切り裂く。俺に敵影は見えないが……ゴトンと何かが落ちる音がした。" },
  { name: "エル", who: "el", expr: "normal", text: "虫の魔物ですね……気持ち悪い……" },
  { text: "エルの足元に視線を移すと、そこには確かに巨大な虫の死骸が転がっていた。形容するならば過剰に羽の生えた大きなトンボ、キィキィと鳴きながら床で蠢いている。確かにこれは気持ち悪い。エルは短剣を腰に仕舞うと、何事も無かったかのように先に進む。" },
  { text: "今度はさり気なく向こうから手を繋いできた。少しドキリと胸が跳ねる。どうやら初心なのは俺の方だったらしい。" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "またこっちに敵だ!｜埒《らち》が明かないぞ!?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "耐えて下さい、体力が限界になるまで進みます" },
  { text: "勇者は後ろから迫る敵を一人で次々と斬り捨てていく。傍から見れば簡単で単調な作業に見えるが、この暗闇の中であれだけの動体視力、反射神経を発揮するのは、並大抵に出来ることではない。" },
  { text: "勇者が確かに勇者なのだと、改めて実感する。彼は間違いなく俺より有能だ。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……どれくらい進んだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "まだ目標の半分も進んでませんよ、頑張って下さい" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "やっぱ暗闇だと気が滅入るな……体感時間が引き伸ばされているように感じる" },
  { chara: { slot: "left", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "ヤマトさん……暗いの苦手なんですか?" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "……うるせぇ" },
  { text: "実のことを言うと、俺は暗所恐怖症の気がある。はぐれないように手を繋いでいるのも、本当は心細さを解消する目的でもあったのだ。最も、バレないように振る舞っていたつもりであったが。" },
  { hide: "el" },
  { name: "ティア", who: "tia", text: "ヤマト、脚が疲れたわ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "仕方ないな……ほら、乗れ" },
  { text: "まだ幼いティアにはこれは重たい仕事だろう。" },
  { text: "俺は屈み、ティアを背負ってやる。どうせ戦えないのだ、こういう仕事は積極的にやらねばならない。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "本当に、なんで俺に人選を任せたんだか……" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "そういう王命でしたので……私も本当は不本意でしたが……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "王命?ってのは王様が直々に……俺が選ぶように仕向けたってことだよな?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……そうか、案外期待されてたのかもな" },
  { text: "国王は俺に対して当たりが強い印象を覚えたが、それは俺の偏見で、実際の所はそうでもなかったのかもしれない。まぁ、だとすれば俺は期待を裏切る事をしているのかもしれないが。" },
  { text: "果ての見えない回廊を、体感ではもう10時間近く歩いた頃。アカツキが立ち止まる。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……っと、どうしたアカツキ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "此処でこの階層は終わりみたいです、階段があるので足元には気を付けて下さい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "どれくらい進んだんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "｜魔窟《まくつ》は5階層構成なので、丁度此処が今日の目的地になります、お疲れ様です" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お、つまり地上に帰れるのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はい、初日ですし勝手が分からなかったのもあります、今日は早めに切り上げましょうか" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "よし、そうと決まればさっさと戻ろう、この暗闇が続くのは精神的にキツい" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "取り敢えず、魔物が来る前に戻ろう、な?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "座標を記録しているので少し待って下さい……はい、出来ました、では戻りましょうか" },
  { text: "アカツキの指示で全員が手を繋ぐ。そしてアカツキが座標を記録し、帰還の魔法を唱えると、瞬く間に俺達は拠点としている｜廃墟《はいきょ》へと転移した。" },
  { fade: "out" },
  { hide: "all" },
  { bg: "loiton_makutsu", instant: true },
  { fade: "in" },
  { chara: [
    { slot: "left", id: "nicholas", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……新鮮な空気だ" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "冗談じゃない、この空気が綺麗だと思うなんてどうかしてるよ" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "それでも、｜魔窟《まくつ》の中よりは息が出来るんだよ" },
  { text: "そう勇者に言い放ちながら、息を大きく吸う。が、鼻腔を刺激する腐敗臭に思わず吐き気を覚える。確かにこれは新鮮とは言い難い。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "もう日が落ちてる……やっぱ結構な時間潜ってたんだな" },
  { name: "アカツキ", who: "akatsuki", text: "そうですね、皆さん明日に備えて早く休むように、お疲れ様です" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、お疲れ様" },
  { text: "今も跳ねる胸を静かに抑えながら、その日は言われた通り早く眠る。この日だけはクロセルの添い寝が有難かった。" },
  { hide: "all" },
  { text: "そして、俺達はそれから毎日、｜魔窟《まくつ》を少しずつ進む日々を続けるのであった。" },

  // ===== シーン14: 再戦 (EP46) =====
  { label: "future_sight_duel" },
  { bg: "makutsu_depths", instant: true },
  { fade: "in" },
  { bgm: "tension2" },
  { text: "期限当日。代わり映えしない景色だが、俺達は確かにこの五日間で｜魔窟《まくつ》を踏破したのだ。戦闘の経験は十分に積んだ。今日まで、地味でも俺達の背中が安全だったのは、勇者の活躍あってこそだ。" },
  { name: "ティア", who: "tia", text: "｜魔術回路構築《クリエイト》……詠唱!リ・スォーム・リクシア・ティル……風魔術……｜鎌鼬《エアスラッシュ》!" },
  { text: "場所は｜魔窟《まくつ》五階層。光景は代わり映え無く、四方に暗闇が広がる迷宮。俺の背でティアが詠唱すると、彼女の伸ばした掌より放たれた風の刃が、進行方向を塞ぐ二頭を持つライオンのような魔物の首を刈り取っていく。" },
  { text: "それが魔物と相対して数秒の出来事。魔物は二つの頭を失い、ぐらりと傾くと、そのまま絶命する。" },
  { name: "ヤマト", who: "yamato", text: "やっぱり魔術の威力は恐ろしいな……" },
  { name: "エル", who: "el", text: "｜魔窟《まくつ》の魔物程度ならクロセルさんとティア様が居れば魔術だけで攻略出来てしまいそうですね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "地味だが俺達の背中が安全だったのは勇者の活躍あってこそだからな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "その通りです、ニコラスさんには感謝しないとですね" },
  { chara: [
    { slot: "left", id: "nicholas", expr: "laugh" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "そうだよ!みんな僕の活躍をやっと認める気になったんだね!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……" },
  { name: "ニコラス", who: "nicholas", expr: "surprised", text: "何故そこで皆黙るんだい?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "一々声がでけぇんだよ、全くうるせぇ……ほら、魔物が寄って来たぞ" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "任せてくれ!フルティィィィン!" },
  { se: "slash" },
  { text: "闇の中から飛び掛かってきた一体の狼の魔物を、勇者が的確に斬り捨てる。確実に彼の働きは優秀ではあるのだが、何とも甲乙付け難い。" },
  { chara: [
    { slot: "left", id: "nicholas", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それより……今日で期限だろ、復活までの時間はどれくらいあるんだ" },
  { chara: { slot: "left", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ふむ、この様子だとあと数時間も無いな" },
  { chara: { slot: "left", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "最深部まであと少しです、皆さん、覚悟は決めましたね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そんなの当の昔に出来てる" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それよりアカツキよ、封印の方法は用意できたのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "｜石版《せきばん》を解読した結果、封印の儀式には長大な詠唱と膨大な魔力、そして封印対象の無力化が必要と記されています。魔王の無力化さえ成功すれば、あとは私とクロセルさんで封印を実行出来る筈です" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "復活直後の魔王は弱ってるんだろ?それなら俺達の敵じゃ無さそうだな" },
  { chara: { slot: "left", id: "el", expr: "troubled" } },
  { name: "エル", who: "el", expr: "troubled", text: "気持ちは分かるけど、決して慢心してはいけないよ、ヤマト様" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、分かってる" },
  { text: "代わり映えしない景色だが、俺達は確かにこの五日間で｜魔窟《まくつ》を踏破したのだ。戦闘の経験は十分に積んだ。魔王がどれほど強大な存在か分からないが、今の俺達であれば魔王の無力化も難しくはない様に思える。寧ろ問題になるのは……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "皇帝、奴は確実に現れるだろうな" },
  { chara: { slot: "left", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "angry", text: "ご主人の推察だと、皇帝の目的は自身の手で魔王を殺害する事だったか" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "あぁ、まずはそれを止めるのが最優先になるだろう" },
  { text: "俺は塔で対峙した皇帝の事を思い出す。奴は少なくとも祝福の勇者より強い。それはあの時の戦いで分かった。しかし今回はクロセルが居る。必ず、俺達にも勝機はあるはずだ。" },
  { chara: { slot: "left", id: "nicholas", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば、勇者。お前なんであの時に皇帝とクロセルの場所が分かったんだ?" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "あの時……ってのは魔王復活の儀式のことだよね?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そうだ、お前は自力であの塔で儀式が行われることを知り、そして俺達よりも早く辿り着いたのか?" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "それなら簡単な話だ。僕は王命で｜魔杖《まじょう》の奪取を命じられた、その際に儀式の場所も知らされたから、急いで向かったら君達とばったり出会した訳だ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "……どういうことだ?" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "そのままの意味だけど……どうかしたのかい?" },
  { text: "理解はしたが、どうも引っ掛かる点がある。俺は歩きながら、ゆっくりと思考を整理していく。もし、俺の仮説が正しければ……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……まさかな" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "どうかしたのか?ご主人" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いや、なんでもない……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "皆さん、間も無く最深部です" },
  { text: "進行方向へと視線を移すと、やがて光が見えてくる。そこに足を踏み入れる。そこは広い広間のような場所だった。随所に青い炎の｜松明《たいまつ》が設置され、雛壇のような形で中央への階段がある。遥か高い天井から一筋の光が差していた。｜贔屓目《ひいきめ》を抜きにしても、幻想的で、綺麗な場所だ。｜魔窟《まくつ》と称される大迷宮の最深部に相応しい様式をしている。" },
  { text: "そして、予想通り。階段に立ち、俺達を見下ろす二人の先客が居た。その内の片方は、俺達を見下ろしたまま、小さく拍手をすると、そのまま声を発する。" },
  { chara: [
    { slot: "left", id: "elk", expr: "normal" },
    { slot: "center", id: "raon_black", expr: "normal" },
    { slot: "right", id: "yamato", expr: "angry" },
  ] },
  { name: "エルク", who: "elk", expr: "laugh", text: "やぁ、良く来たね" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "……具合はどうだ?皇帝" },
  { name: "エルク", who: "elk", expr: "laugh", text: "お陰様で、全快までかなりの時間を要したよ、いやはや、あれは良く効いた" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "仕留め損なったのは残念だ" },
  { name: "エルク", who: "elk", expr: "normal", text: "おっと、それは申し訳ない事をした" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "一応聞くが、お前は誰だ?" },
  { name: "黒ずくめ", who: "raon_black", expr: "serious", text: "……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "まぁ、答えないだろうな" },
  { text: "意味深な笑みを浮かべる皇帝の隣で立ち尽くす、全身を黒い布で覆った人型の何か。あいつが馬車を襲い、エルとティアを襲った\"警告者\"の正体で間違いないだろう。" },
  { name: "エルク", who: "elk", expr: "laugh", text: "さて、役者は揃ったようだ、舞台の幕開けといこうじゃないか" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "クロセル、やるぞ" },
  { hide: "center" },
  { chara: { slot: "center", id: "crocell", expr: "angry" } },
  { name: "クロセル", who: "crocell", expr: "normal", text: "任せておけ、ご主人!" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "援護します!" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "僕は黒い方を担当しよう、エルとティアは僕の援護を頼む!" },
  { name: "ティア", who: "tia", text: "分かったわ!" },
  { name: "エル", who: "el", expr: "normal", text: "了解しました" },
  { text: "戦闘が始まった。" },
  { bgm: "boss" },
  { fx: "shake" },
  { text: "皇帝が剣を抜いたのとほぼ同時に、クロセルの身体が青い光で覆われる。そして更にクロセルが小さく何かを口遊んだかと思えば、彼女の手元から水が溢れ、長剣の形を形作る。それは剣の形状を取ったと同時に、一瞬で凍り付き、透明の氷の剣となった。" },
  { text: "クロセルが踏み込み、皇帝に｜肉薄《にくはく》すると、綺麗な高い音が打ち鳴らされる。俺には目視する事すら困難な速度で、剣と剣の打ち合いが行われる。傍から見れば互角。気を抜いた方が負ける戦いだが、クロセルの剣が不可視であるという事実が、明確な優位を生んでいた。少しずつ、皇帝の身体に傷が生まれていく。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "――｜亜空切断《ディメンションカッター》!" },
  { se: "slash" },
  { text: "そこに、アカツキによる援護射撃が放たれる。皇帝は飛び退くことで躱すが、そこで決定的な隙が生まれた。好機を逃さんとばかりにクロセルが大きく接近し、不可視の刃が皇帝の胸元を大きく抉る。" },
  { text: "周囲には皇帝の血が飛び散り、それがクロセルの剣を濡らす。これでクロセルの剣は不可視のアドバンテージを失った。" },
  { text: "皇帝は傷を負っても怯む事無く、追撃するクロセルの剣を的確に弾いていく。この状況でも互角を維持する皇帝の底力に、俺は思わず身震いを覚えた。" },
  { name: "エルク", who: "elk", expr: "angry", text: "っ……これは少し厳しいな、持っていけ悪魔!" },
  { name: "???", text: "おや、良いんですか?" },
  { name: "エルク", who: "elk", expr: "angry", text: "どうせ捨てる人の身だ!もはや幾らでもくれてやる!" },
  { name: "???", text: "あははははは!それもそうだ!ではでは~契約通りに……" },
  { fx: "flash" },
  { name: "エルク", who: "elk", expr: "laugh", text: "はは……視える……視えるぞ!お前も此処までだ!｜魔杖《まじょう》クロセル!" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "っ、これは……どういうことだ?" },
  { text: "突然、皇帝の動きが変わった。クロセルの攻撃を全て受け流し、読めない筈の彼女の隙を見抜き、的確に突いてダメージを重ねていく。まるで\"未来を視ている\"かのような動きであった。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "っ……｜亜空切断《ディメンションカッター》" },
  { name: "エルク", who: "elk", expr: "laugh", text: "……そんな避けやすい攻撃、幾ら撃っても無駄だよ" },
  { text: "皇帝はアカツキの詠唱が聞こえない距離に居る。それでありながら、まるで予め知っていたかのような動作で、たった半歩動くだけでアカツキの攻撃を躱す。" },
  { text: "一気にクロセルの劣勢となった。皇帝の放つそれは小さい傷の積み重ねであるが、確実に彼女の身体を傷付け、辺りには鮮血が散っていく。" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ご主人……すまない……これは我の力では……" },
  { name: "エルク", who: "elk", expr: "laugh", text: "その通りだ、よく分かってるじゃないか、賢い｜魔杖《まじょう》だ" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "うっ……ぐはっ……" },
  { bgm: null },
  { fx: "red" },
  { fx: "shake" },
  { se: "slash" },
  { text: "そして遂に、皇帝の剣がクロセルの胸を刺し貫く。地面に鮮血の華が咲く。クロセルは、力無く地面に倒れると、徐々にその姿は半透明になり、やがてそのまま光の粒子になって消失した。" },
  { hide: "center" },
  { text: "後に残されたのは、完全に沈黙した一本の杖。クロセルが負けた。その絶望的な事実が、俺の理性を蝕む。" },
  { fx: "clear-red" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そんな……くそっ、よくもクロセルを……" },
  { name: "エルク", who: "elk", expr: "laugh", text: "あはははは……そうそう、その顔が見たかったんだ。ヤマト君、君は絶望して……そしてそのまま死ぬんだ" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "……させるかよ!" },
  { bgm: "boss" },
  { text: "氷の剣はクロセルと同時に消えた。そしてそもそも俺は剣を持てない。皇帝は、大きく口を歪めて笑いながら、俺の元へとゆっくりと近付いてくる。何か……何か方法がある筈だ。" },
  { name: "エルク", who: "elk", expr: "normal", text: "死ね!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "っ……そう簡単に死ぬかよ" },
  { text: "俺は速やかに構えると、次々と襲い来る皇帝の剣を躱していく。クロセルとの訓練の賜物だ。今の皇帝の剣速であれば俺でも見切れる。だが、このまま躱しているだけでは、やがて追い詰められる。" },
  { name: "エルク", who: "elk", expr: "laugh", text: "……避けるのだけは上手いんだね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "本当は殴るのも上手いんだけどな……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "皇帝、お前は未来が見えるのか?" },
  { name: "エルク", who: "elk", expr: "normal", text: "そうだとも!今の僕には未来が見える!君に限界が来た時、僕は君が死ぬ未来を見るのさ!" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "……そうか" },
  { text: "大凡推察通りだ。奴の未来視は不完全だ。数秒先の\"自身の力で達成可能な最も都合の良い未来\"が見えているに過ぎない。不可能や理不尽を押し付けられない限り、皇帝は都合の悪い未来やもしもの世界を見る事は出来ないのだ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "にしても、厄介な力だな" },
  { name: "エルク", who: "elk", expr: "laugh", text: "逃げ回っても無駄だよ、僕はこのまま君が消耗するのを待つだけで良いのだから" },
  { text: "彼の言う通り、攻撃側よりそれを避け続ける俺の方が確実に体力は消耗していく。" },
  { text: "これはクロセルとの特訓でも想定していた\"最悪の状況\"だ。何か……何か無いだろうか。彼の攻撃を止めさせる手段が。……ある。一つだけ可能性がある。どうせこのままじゃジリ貧だ、試してみる価値はあるだろう。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "なら、これでどうだ?" },
  { name: "エルク", who: "elk", expr: "shock", text: "……っ!何故だ?" },
  { text: "突然、皇帝の攻撃が止まる。――予想通りだ。奴には文字通り\"視えた\"のだろう。攻撃を止めた自分の姿が。攻撃を止める未来は見えても、攻撃を続けた場合の\"都合の悪い\"未来は見えないのだ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "どうした?皇帝" },
  { name: "エルク", who: "elk", expr: "shock", text: "くっ……何をするつもりなんだ、君は" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "さぁ?お前が｜現実《いま》じゃなく未来だけを見てる限り、分からないだろうよ" },
  { text: "剣を構えたまま立ち往生する皇帝を一瞥すると、俺は｜魔杖《まじょう》クロセルを拾う。クロセルの反応はない。死んではないのだろうが、完全に機能は停止しているようだ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "来ないのか?" },
  { name: "エルク", who: "elk", expr: "angry", text: "くっ……" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ヤマトさん、一体何をしたんですか?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "んーまぁ……そうだな、秘密だ" },
  { text: "アカツキが俺の元へと歩いて来る。皇帝は動かない。動けないのだろう。俺に敵意を向け続ける限り、彼の見る未来は変わらないのだから。もし標的をアカツキや他の仲間に向けたのならば、また違った未来が見えるだろうに。馬鹿な男だ。" },
  { name: "エルク", who: "elk", expr: "angry", text: "あぁ、くそっ……やってやる!" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ほう、来るか" },
  { text: "覚悟を決めたのだろう。皇帝は俺に斬り掛かる。素直な剣筋だ。が、俺は剣を躱すこと無く。両手で剣を受け止め、掴んだ。そして、俺の腕が斬り裂かれる……事はなく。" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "――皇帝の剣は\"謎の力\"によって俺の手から弾け飛んだ。そのまま剣は遥か遠くへと飛んでいき、やがて地面に落ちる。" },
  { cg: "cg_sword_break" },
  { name: "エルク", who: "elk", expr: "shock", text: "っ……これはどういうことだ!?" },
  { wait: 500 },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "残念だったな、俺の\"剣術\"はディザビリティだ" },
  { name: "エルク", who: "elk", expr: "normal", text: "どういう……ことだ" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "要するに、俺相手に剣は通用しないってことだ" },
  { cg: null },
  { text: "そう。剣術のディザビリティは\"剣に触れる\"ことすらも許さない。俺が皇帝の剣を受け止め、掴もうとした時点で、\"見えざる神の力\"によって俺の手から剣は弾け飛ぶのだ。" },
  { text: "故に、俺に剣による攻撃は通用しない。――これが皇帝の見ることの出来なかった\"都合の悪い未来\"だ。" },
  { name: "エルク", who: "elk", expr: "shock", text: "くそっ……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "行かせるかよ、剣術しか脳のない奴め" },
  { text: "慌てて剣の方向へと走り出す皇帝の｜襟首《えりくび》を引っ掴むと、そのまま引き寄せて拘束する。筋力なら俺の方が上だ。これで皇帝は身動きが取れなくなった。" },
  { name: "エルク", who: "elk", expr: "shock", text: "くそっお前は無才の癖に何故!僕が負けるんだ!?こんな事有り得ない!" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "うるせぇなぁ……" },
  { text: "俺はクロセルに頼んで作って貰った、金属製の手錠を取り出すと、それで皇帝を拘束する。本当は魔王に使う予定だったのだが、こうなってしまった以上は仕方ない。そのまま皇帝を押し倒して床に転がす。これで一丁上がりだ。" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "驚きました……本当に皇帝に勝ってしまうなんて" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺も此処まで上手くいくとは思わなかった。クロセルとの特訓の賜物だな" },
  { fx: "shake" },
  { se: "rumble" },
  { text: "アカツキとそんな会話をした｜刹那《せつな》のこと。迷宮の内部で、大きな揺れが起こる。かなり大きな地震だ、立っていられない。これは……間違いないだろう。遂に……この時が来てしまったのだ。" },
  { text: "――魔王の復活が、始まった。" },

  // ===== シーン15: 魔王復活 (EP47・エル視点) =====
  { label: "gremory_revival" },
  { fade: "out" },
  { hide: "all" },
  { pov: "el" },
  { fade: "in" },
  { text: "私は腰から短剣を抜き、一度敗北した黒ずくめの人型へ立ち向かう。右には血のように真っ赤に染まった聖剣を持った勇者。一人では勝てなかった相手でも、二人なら勝てる可能性がある。" },
  { text: "遠くでは｜魔杖《まじょう》とヤマト様。そしてアカツキさんが戦っている。私の背後にはティアお嬢様。そして正面に黒ずくめの人型。これで位置関係は把握した、今は目の前の事に集中しよう。" },
  { chara: [
    { slot: "left", id: "el", expr: "normal" },
    { slot: "center", id: "raon_black", expr: "normal" },
    { slot: "right", id: "nicholas", expr: "serious" },
  ] },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "貫き穿て聖剣!フルティィィィン!" },
  { name: "ティア", who: "tia", text: "｜魔術回路構築《クリエイト》……詠唱……リ・スォーム・リクシア・ティル……風魔術……｜鎌鼬《エアスラッシュ》!" },
  { fx: "shake" },
  { text: "私と勇者の間を縫って、風の刃が飛んでいく。それに合わせて勇者と私が僅かな時間差を置いて斬り掛かっていく。黒ずくめは、風の刃を横に避けながら、勇者の聖剣を片手で掴んだ。なんという荒業なのだろう。黒ずくめの手から｜血飛沫《ちしぶき》が上がる。" },
  { name: "エル", who: "el", expr: "normal", text: "はっ……!" },
  { text: "今なら片手が塞がっている、これは好機だ。私は姿勢を低くし、その脚を斬り裂かんと迫る。しかし、それは叶わなかった。全く予備動作の無い突発的な攻撃。黒ずくめの蹴りが私を襲い、私は後方へと蹴り飛ばされる。" },
  { name: "エル", who: "el", expr: "surprised", text: "っ……" },
  { text: "片脚だけで地に根を張りながら勇者の剣を握り続け、予備動作無しで重たい蹴りを放つ。言語化すると痛感する。あれはまさに人間離れした怪力だ。" },
  { fx: "shake" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "くっ……なんて力だ" },
  { text: "勇者は大きく後退して強引に剣を黒ずくめの手から抜き取る。その瞬間。黒ずくめが攻勢に出る。一瞬にして勇者の前へと間合いを詰め、左手の掌で勇者の腹部へと突きを放つ。途端。勇者の身体が不自然に丸くなり、そのままの姿勢で一瞬静止したかと思えば、勇者は口から血の塊を吐き出して、ふらふらと後退する。" },
  { text: "まずい。このままでは一方的に攻撃を受けて勇者が負けてしまう。" },
  { name: "エル", who: "el", expr: "normal", text: "させません!" },
  { text: "追撃の姿勢に入っていた黒ずくめは、直ぐには行動を変えられない。" },
  { text: "私は鈍い痛みを振り払い、黒ずくめの背に回り込み、短剣の刃を宙に走らせた。確かに手応え。黒ずくめの背から鮮血が散る。が、黒ずくめは反撃とばかりにくるりと振り向きながら回し蹴りを放つ。ダメだ……早い。避けられない。" },
  { name: "エル", who: "el", expr: "sad", text: "っあっ……あぁぁぁ……" },
  { fx: "shake" },
  { text: "胸元に激痛が走り。私の身体は再び宙を舞う。ダメだ……実力差がありすぎる。私ではあの黒ずくめを止められない。それは残念ながら勇者も同じらしい。" },
  { text: "黒ずくめは私を無視して勇者に向き直ると、拳を叩き込んでいく。" },
  { name: "ティア", who: "tia", text: "｜魔術回路構築《クリエイト》……詠唱……風魔術……｜吸空竜巻《サックトルネード》!" },
  { text: "黒ずくめの後方に空気の渦が生まれ、黒ずくめはそちらへと吸い寄せられる。ティアお嬢様の援護が功を奏した。その隙に勇者が姿勢を立て直し、剣を構える。" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "一体何者なのか知らないけど……僕を此処まで追い詰めた事を褒めてやろう" },
  { name: "エル", who: "el", expr: "sad", text: "勇者様、これでは……" },
  { name: "ニコラス", who: "nicholas", expr: "normal", text: "……分かってる、僕達じゃこいつには勝てない、だから……君は下がって僕に任せてくれ" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "さぁ掛かってこい、勝負はこれからだ!" },
  { text: "勇者は口元の血を拭うと、黒ずくめへと斬り掛かっていく。彼は一人で……時間を稼ぐつもりだ。複数対一のアドバンテージが事実上消えた今。勇者の｜剣戟《けんげき》はただ躱され続け、宙を切っていく。黒ずくめは余裕綽々とした様子で、時折勇者へとカウンターの拳を叩き込んでいく。" },
  { text: "その度に勇者は血を吐きながら、ぐらりとよろめく。それでも決して隙は見せない。その身体は痣だらけだろうに、痛みに耐え、立ち続けていた。" },
  { text: "祝福の勇者を仕留めることは出来ないと判断したのか。黒ずくめは勇者の脇をすり抜け、走り出す。その狙いは……ティアお嬢様では無く。――私だった。" },
  { text: "黒ずくめの蹴りが響いていて、全身が痺れ立ち上がれない。｜絶体絶命《ぜったいぜつめい》。私は死を覚悟した。ヤマト様、ごめんなさい。私が仕える彼の事を想い、僅かな無念を抱きながら。私は目を閉じた。" },
  { fx: "red" },
  { fx: "shake" },
  { text: "肉が潰れ、弾ける嫌な音が響く。が、痛みは無かった。私は閉じた瞳を再び開ける。そこに広がっていた光景は……" },
  { bgm: "sad" },
  { chara: { slot: "right", id: "nicholas", expr: "depressed" } },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "僕は……祝福の勇者……だからね……僕が……僕こそが……正義の味方……だ" },
  { cg: "cg_hero_shield" },
  { text: "私の前には勇者の背があった。そして、彼の身体の中央を、一つの拳が貫いていた。あれは……黒ずくめの男の手だ。――勇者は私を庇ったのだ。" },
  { text: "祝福を受けた勇者が死ぬことは無いと聞いたが、それでも痛みが消える訳じゃない。他人の為に己の身を犠牲に出来る勇敢な精神。それは並大抵に出来る事ではない。私には、勇者ニコラスが、今この瞬間だけ、救世の英雄に映って見えた。" },
  { text: "動けなかった。神に作られ、人の情など知らぬ筈の私が――この時ばかりは、何も出来なかった自分の無力を、心の底から呪った。" },
  { wait: 700 },
  { name: "ニコラス", who: "nicholas", expr: "depressed", text: "正義は……不滅……だ……" },
  { cg: null },
  { text: "それが勇者の｜断末魔《だんまつま》となった。黒ずくめは勇者の腹から拳を引き抜き、｜血飛沫《ちしぶき》が辺りに撒き散らされたかと思うと、勇者の身体はガクンと力無く地に倒れ伏す。" },
  { text: "辺りにはどくどくと血溜まりが生まれていった。私達は、敗北した。もはや勝ち目はない。ぐらぐらと視界が揺れる。これは私の動揺だろうか。" },
  { hide: "right" },
  { fx: "clear-red" },
  { fx: "shake" },
  { se: "rumble" },
  { text: "――違う。確かに世界が、この地面が揺れている。" },
  { fx: "flash" },
  { text: "大きな揺れで黒ずくめは姿勢を崩し、一時撤退とばかりに後ろへと飛び退く。私も……この揺れの中で立ち上がるのは難しそうだ。一体何が起きているのだと言うのだろう。" },
  { name: "エル", who: "el", expr: "surprised", text: "っ……眩しい!" },
  { text: "突如、辺りが真っ白な閃光に包まれる。揺れが止まり、静寂が訪れる。余りの光量に、目を開けていられない。それはこの場に居る者、全員が該当するらしい。暫く明滅を繰り返していたかと思えば……やっと光が収まる。そして私は、部屋の中央に視界を移す。" },
  { hide: "center" },
  { chara: { slot: "center", id: "gremory", expr: "normal" } },
  { bgm: "dark" },
  { text: "――そこには、魔王が立っていた。" },
  { name: "魔王", who: "gremory", expr: "serious", text: "……｜徒《いたずら》に我を目覚めさせた者は誰だ?" },
  { text: "魔王は、私の想像していた魔王像とはかけ離れていた。あれは……美しい女性と形容するのが相応しい。生気を失った白い肌に、燃えるように赤い髪。黒いドレスを纏っている。だが、その身体から放たれる殺気は、彼女が魔王であることを堂々と主張している。" },
  { name: "グレモリー", who: "gremory", expr: "angry", text: "我は56代魔王グレモリー。甘美な悠久の眠りを妨げた罪、その生命で償って貰おう" },
  { hide: "left" },
  { chara: { slot: "left", id: "yamato", expr: "smirk" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "魔王と聞いてどんな怪物が出てくるかと思えば、只の美人じゃないか" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ヤマトさん!?何をこんな状況で言い出してるんですか" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "待てよアカツキ、取り敢えず落ち着け。会話の余地があるんだから此処は出来る限り穏便に済ませるべきだろ" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "ヤマトと言ったな?お前が我を眠りから目覚めさせたのか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "いや、お前を起こしたのはそこで転がってる皇帝だ、俺達はお前にもう一度眠って貰う為に来た" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "ふむ……なるほど、その言葉に偽りは無いな?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "嘘をつく必要が無いだろ" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "まぁよい、我にはそれを判断する術が無いからな" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "んで、どうする?大人しく封印されて貰えるか?" },
  { name: "グレモリー", who: "gremory", expr: "sad", text: "構わん、我は平穏を望む、好きに封印すると良い" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "話が分かるようで助かった……っ!魔王!危ない!" },
  { name: "グレモリー", who: "gremory", expr: "serious", text: "っ、なんのつもりだ?" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "そいつはお前を殺すつもりだ!" },
  { fx: "shake" },
  { text: "魔王の背後から黒ずくめの男が現れる。だが、ヤマト様のお陰で魔王はそれに気付き、｜既《すんで》の所で奇襲をひらりと躱す。危ない所だった。" },
  { name: "グレモリー", who: "gremory", expr: "serious", text: "こいつはお前らの敵ということで良いのだな?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "その通り、そいつは俺達の敵だ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "皇帝、起きてるか?" },
  { name: "エルク", who: "elk", text: "……なんだい?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "こいつはお前の味方じゃないんだろ?" },
  { name: "エルク", who: "elk", text: "……そうだね、そいつは僕の味方ではない" },
  { text: "ヤマトと皇帝の会話が聞こえる。皇帝の言うことが確かならば、この場には三つの陣営の人間が集まっていたということになる。目的はそれぞれ、魔王の殺害、同じく魔王の殺害。そして私達、魔王の封印。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "まぁ、という訳だから、魔王は少し力を貸してくれ、そいつを仕留める" },
  { name: "グレモリー", who: "gremory", expr: "angry", text: "……我は復活直後故……戦えぬぞ?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "マジ?そこまで弱体化してるのか?" },
  { name: "グレモリー", who: "gremory", expr: "normal", text: "本当だ、だから早く我を助けろ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "まさか魔王に助けを請われる日が来るとは思いませんでした" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "勇者!は死んでるか……くそっ、戦える奴がもう居ない……こうなったら、エル!獲物を貸せ!" },
  { text: "黒ずくめが皇帝の手の者では無いと分かったが、状況に変わりはない。黒ずくめが私達の敵であることに違いはないのだ。私は力を振り絞り立ち上がると、ヤマト様の足元に向かって短剣を投げ付ける。" },
  { text: "ヤマト様はそれを握り締め、安堵したとばかりに溜息を吐くと、一つ頷く。賢い彼の事だ、何か策があるのだろう。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "剣と短剣は別カテゴリみたいだな、どう考えても屁理屈なシステムだが、助かった" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ヤマトさん……一体何を……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺があいつの相手をする、無力化は任せた" },
  { text: "二本の短剣を構えると、ヤマト様はそのまま黒ずくめへと立ち向かっていく。一方、魔王は黒ずくめから逃げるようにしてアカツキさんの方へと走って行く。なんとも拍子抜けする光景だ。私はそれを、力無く地に座り込みながら、ただ見ているのであった。" },

  // ===== シーン16: 黒ずくめとラプラスの裏切り (EP48〜49) =====
  { label: "laplace_betrayal" },
  { fade: "out" },
  { hide: "all" },
  { pov: null },
  { fade: "in" },
  { bgm: "boss" },
  { chara: [
    { slot: "left", id: "yamato", expr: "angry" },
    { slot: "right", id: "raon_black", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "さて……やるか" },
  { text: "俺は二本の短剣を構え、黒ずくめの前に立つ。意識を集中させ、俺の中にあるスイッチを入れる。大丈夫、感覚は覚えている。必ず出来るはずだ。" },
  { fx: "flash" },
  { se: "chime" },
  { text: "\"才能『短剣術10』を強制解放しました エラー……才能データが破損しました\"" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "よし……これでいい" },
  { text: "脳内に、俺の知らない動きがインストールされる。相手は俺の得意とする格闘の才能持ちだ。だが才能の無い俺が同じ土俵で勝つことは出来ない。故に、敢えて使えない獲物を握って才能を引き出した。" },
  { text: "格闘の才能を引き出しても良かったが、それは奥の手だ。相手の才能指数が不明な以上、同じ才能で立ち向かうのは最善手ではない。ただ……流石に相手の格闘の才能指数が10以上だとは思えないが。" },
  { text: "これは短剣術の才能に攻撃も含まれている為だ、俺は頭に浮かんだ動きをなぞるだけ。そこに自分の意志は介入できない。それほどまでに才能の強制力は強い物だった。" },
  { fx: "shake" },
  { name: "黒ずくめ", who: "raon_black", expr: "serious", text: "……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "もはや、お前に勝ち目はない" },
  { text: "前に立ち塞がったまま行動を制限し、相手の攻撃を避け、的確に攻撃を当てていく。傷害のディザビリティが発動している為、有効打は無いが、怯ませるだけの効果はある。相手の行動は制限され、やがて徐々に守りの姿勢に追い込まれていく。才能の強制力がある故に、相手は俺に攻撃を当てることは出来ない。絶対に勝てないのだ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "俺は体力が尽きるまで続けても良いが?" },
  { name: "黒ずくめ", who: "raon_black", expr: "serious", text: "……" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "アカツキ、ティア!こいつの動きは俺が止める!何でも良いから魔法を撃て!" },
  { text: "遂に、黒ずくめを広間の隅まで追い詰める。黒ずくめは逃れようと動くが、俺は直ぐにその前へと立ち塞がる。今がチャンスだ。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "――｜亜空切断《ディメンションカッター》!" },
  { name: "ティア", who: "tia", expr: "surprised", text: "――｜鎌鼬《エアスラッシュ》!" },
  { se: "magic" },
  { text: "馴染みのある二種類の魔法が、黒ずくめを襲う。が……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "どういうことだ……?何故効いていない!" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "これは……ヤマトさん!黒ずくめの纏ってる布は恐らく勇者の鎧と同じ……強力な対魔力を持った布です!" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "つまり身包み剥がないと魔法は効かねぇって訳か…" },
  { text: "想定はしていたが、厄介な相手だ。だが今の俺なら……黒ずくめにダメージを与えず\"布だけを斬り裂く\"芸当が可能だ。そうと決まれば、早速黒ずくめへと踏み込み、破こうと迫る……が。" },
  { fx: "shake" },
  { name: "???", text: "くっ、何者だ!お前は!?うぐっ……ぐああああああああ" },
  { name: "???", text: "全く魔王様とあろうものが、もっと堂々と構えて下さいよ、ついでにそのまま……大人しく死んで下さい" },
  { text: "この声は……誰だ?聞き覚えは……ある、確か皇帝とクロセルが戦っている時……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "チッ……皇帝の魔剣か!?" },
  { hide: "right" },
  { chara: { slot: "right", id: "laplace", expr: "laugh" } },
  { name: "？？？", who: "laplace", expr: "laugh", text: "流石はヤマトさん、ご明察……皇帝の寿命を美味しく頂いたので、ボクも実体化出来るだけの力を得た訳です、でもすこーし……気付くのが遅かったかな?あははははは!" },
  { bgm: null },
  { fx: "red" },
  { fx: "shake" },
  { text: "俺は黒ずくめから距離を取り、何事かと振り返る。――魔王の腹から勇者の聖剣が突き出ていた。" },
  { text: "魔王の背後には、勇者の聖剣を握り締めた黒髪の少女。その顔は見えないが、声色は酷く高く、耳障りに歪んでいた。" },
  { text: "ティアとアカツキは完全に俺の方へと注目していた。その一瞬の不意を突かれたのだろう。" },
  { bgm: "dark" },
  { name: "黒髪の少女", who: "laplace", expr: "normal", text: "でもでも?ボクは魔王の力には興味無いというか、どちらかと言えば仕える事が本分ですので……" },
  { text: "黒髪の少女は、魔王の胸から剣を引き抜くと、それを近くに転がっている皇帝の胸へと、躊躇無く突き刺した。" },
  { name: "エルク", who: "elk", expr: "normal", text: "っああああああああっ!?" },
  { name: "黒髪の少女", who: "laplace", expr: "laugh", text: "こうします~あはは、ボクってなんて優秀なんでしょうね" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "悪魔ですか……" },
  { name: "黒髪の少女", who: "laplace", expr: "normal", text: "その通り!ボクは悪魔です!あは?ボクは元魔王のクロセル様様なんかよりずーっと格下の存在。不意討ちでもしないと~魔王を殺せないような?か弱~い悪魔なんです" },
  { text: "魔剣の少女はニヤニヤと口元を歪めながら、ぶすぶすと皇帝の身体を突き刺して回る。そんなことより……魔王の容態だ、回復魔術を使えるティアが居る、まだ間に合うかもしれない。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ティア!魔王に回復魔術を!" },
  { name: "黒髪の少女", who: "laplace", expr: "laugh", text: "手遅れですよ?だってこれ\"聖剣\"ですもん?魔王には効果は抜群だ!ってね?あははははは!" },
  { fx: "clear-red" },
  { name: "黒髪の少女", who: "laplace", expr: "normal", text: "あーそんなことより?そこの黒い人逃げるみたいですけど良いんですか?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なっ……くそっ、いつの間に!?" },
  { text: "黒ずくめはいつの間にか俺の包囲を潜り抜け、迷宮の方角へと走って行く。奴の目的は自身が魔王になること。それが失敗した為に、この場から逃げようとしている。短剣術の技量は高められているが、脚が早くなった訳ではない。今から追っても追い付けないだろう。" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "逃したか……まぁいい、それよりアカツキ!ティア!魔王はどうだ!?" },
  { name: "ティア", who: "tia", expr: "surprised", text: "どうして!?ヤマト!この人の傷が……塞がらない……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "魔剣の悪魔の言う通り……この傷は魔術じゃ塞がらない物みたいです…" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そんな……ってことは" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい……このままでは……魔王は死亡します" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "くそっ……此処まで来たってのに……" },
  { text: "既に意識は無く、魔王の身体からは血の気が失せていく。魔王の最期が、これほど呆気ない物だとは。魔王も人と殆ど変わりはない。絶大な力を持っていても、不老不死の力は無い。脆く儚い生き物なのだろう。" },
  { name: "黒髪の少女", who: "laplace", expr: "normal", text: "むーむー皆様揃ってボクを放置ですか……折角ボクが狂言回しをして、絶望の舞台を演出したのに、つれないなぁ…" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "お前は何がしたいんだ……" },
  { name: "黒髪の少女", who: "laplace", expr: "normal", text: "ボクですか?ボクはご主人の目的を叶えてあげただけですよ?と言っても……別に命令された訳ではなく、独断と偏見で面白そうだからやってみただけなんですが" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "面白そうだからって……てめぇ……" },
  { name: "黒髪の少女", who: "laplace", expr: "normal", text: "あ?怒ります?怒っちゃいます?いやー困るなぁ……ボクこう見えてもか弱い悪魔なので、ぶっちゃけ戦ったら普通に負けちゃうんですよね~……見逃してくれません?" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ふざけるな!てめぇのような悪魔を逃がす訳ねぇだろ!" },
  { text: "怒りで全身がドクドクと煮え｜滾《たぎ》る。憤りで思考を支配される。気が付けば、俺は魔剣の悪魔へと駆け出していた。あいつだけは、必ず殺す。" },
  { name: "黒髪の少女", who: "laplace", expr: "laugh", text: "でもでも?ボクが思うに……そろそろ貴方、時間切れなんじゃないですか?" },
  { fx: "red" },
  { fx: "shake" },
  { text: "魔剣の悪魔が俺を目の前にして、悪戯っぽくニヤリと笑う。悪魔の言葉、それはまさしく予知であった。魔剣の悪魔を目の前にして……俺は胸と頭蓋を駆け抜ける激痛に思わず足を止める。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あ?っぐあああああああああ!?" },
  { se: "chime" },
  { text: "\"致命的なエラーが発生した為……破損箇所のある才能を破壊します『短剣術0』\"" },
  { text: "何か聞こえるが、俺の脳には届かない。雷に打たれたかのような衝撃。視界が明滅し、意識が遠のく。" },
  { name: "黒髪の少女", who: "laplace", expr: "laugh", text: "あははははは!無様ですねぇ!?あと少しでボクを殺せたのに、残念" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "くそっ……お前……だけは" },
  { name: "黒髪の少女", who: "laplace", expr: "normal", text: "許さなくて結構、人に恨まれるのは慣れっこなので、貴方の罵倒もボクにとっては褒め言葉、いやー実に気持ちが良いですね!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "悪魔……が……" },
  { text: "こいつの言う通り、俺の身体は限界らしい。言うことを聞かない身体が、地面にキスをする。俺はこのまま死ぬのだろうか。そんな事を考えながら……俺は意識を手放した。" },
  { fade: "out" },
  { hide: "all" },
  { fx: "clear-red" },
  { pov: "akatsuki" },
  { fade: "in" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "serious" },
    { slot: "right", id: "laplace", expr: "normal" },
  ] },
  { text: "魔王、クロセル、ニコラス、ヤマト、エル……主戦力の大半を喪失。私も帰還分の魔力を考えれば戦闘不能、ティア様はそもそも殺し合いに場馴れしていない。これは……万事休すか。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "お、始まりますね" },
  { text: "黒髪の悪魔は笑みを浮かべる。全てを見通すかのようにキラキラと光る青い瞳。間違い無い、奴は何かを見ている。そして、それは直に分かる事だろう。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "魔剣、道化師、悪魔……貴方は……" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "道化師とは素晴らしい賛辞!ボクは感激だなぁ……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "道化が賛辞?それはどうしてです?" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "え?そんなの決まってるじゃないですか、道化師はトランプでは切り札ですよ!切り札!どんな逆境もひっくり返すイレギュラー!いやーそんな素晴らしい物と同一視して頂けるなんて、なんとも光栄ですなぁ!" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "なるほど……貴方にはどんな言葉も褒め言葉になるんですね" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "えぇ、ですから貴方は言葉でボクを傷付ける事は出来ない、言葉なんて薄っぺらい物で揺らぐ心など持ち合わせていない" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "なら対話は無意味、そういうことですね" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "そういうことになります、さて……そろそろ始まりますよ、良く見ていると良い、絶望の舞台の幕開けだ!" },
  { fx: "shake" },
  { text: "悪魔が剣で皇帝の身体を指し示す。｜刹那《せつな》。皇帝の身体が膨れ上がる。胸部が大きく膨張し、もはや不要だとばかりに臓物が飛び出る。" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "魔王の血……まさか……" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あははははは!もしかして今更気付いたのですか?馬鹿ですねぇ……もう少し早く気付いていれば良かった物を" },
  { text: "悪魔の少女が高笑いを浮かべる。おかしい。最初に魔王の血を浴びたのは悪魔の少女の筈だ。しかし……今異変が起きているのは皇帝の身体。どういうことだ?これが意味する所は……" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "本当の継承の条件は……死んだ魔王の血を取り込むこと?" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "そうですよ?あれあれ?知らなかったんですか?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "寧ろ貴方が何故そこまで詳しいのか聞きたい所ですが……" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "あぁ、それはボクが魔王に仕えていた存在だからですよ。魔王オロバスの持つ魔剣。その名を\"ラプラス\"。それがボクだ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "ラプラス……" },
  { text: "なるほど。55代魔王オロバスの最期を見届け、今の世まで存在し続けたと言うのならば、魔王の継承にも詳しい訳だ。魔王が死んだ今、その継承は成立する。私達には……もはや止める術は無いのだろうか。" },
  { text: "皇帝の身体は更に膨張し、やがて巨大な肉魂と化す。ピンク色の肉に覆われ、心臓のように脈動する。どうやら今すぐ魔王が生まれる訳では無いらしい。戦闘不能者を含め、今なら転移魔法で逃げることは出来る。だが……それだと魔王の誕生を放置して逃げることになる。" },
  { text: "封印の儀式はティア様の魔力があれば成立する。しかしその場合、あの悪魔が｜邪魔《じゃま》をしてくるだろう。それさえどうにかなれば……封印も可能だ。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "何か考えてるみたいですけど……こうなったらどうしようもないですよ、さっさと逃げることを勧めます" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "私達を逃がすのですか?" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "はい、逃しますよ?別にボクは貴方達に恨みがある訳でもない、寧ろボクの愉快な余興として、もう少し｜足掻く《あがく》様子を見ていたい物です" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "良いこと教えてあげましょうか?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "なんです?" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "……貴方の持っている｜石版《せきばん》、確かにそれは魔王の封印とその解除の儀式について記されている物だ" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それがどうしたと言うのですか?" },
  { name: "ラプラス", who: "laplace", expr: "blank", text: "それ……偽物ですよ?だって本物は……" },
  { text: "悪魔はニヤリと笑うと、肉魂の中に手を突っ込み……一枚の｜石版《せきばん》を取り出す。まずい。そう思った時には遅かった。悪魔は｜石版《せきばん》を床に置くと……" },
  { fx: "flash" },
  { fx: "shake" },
  { text: "――それを剣で叩き割った。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "此処にあるのだから!あははははは!" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "そんな……でも、言われてみれば確かに……" },
  { text: "皇帝の部屋の金庫に鍵が掛かっていなかったのは偶然ではない。あれは罠だったのだ。私は見覚えがあるという理由であれを本物だと断定した。それが間違いだったのだ。それもそうだろう、私は一度も\"本物を見ていない\"のだから。" },
  { text: "五芒星で見たあの｜石版《せきばん》は偽物だったのだ。私はあれと同じだという理由、直感を信じて、あれを本物だと断定した。これは私のミスだ……それも致命的な。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "くっ……悔しいです……" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "はい、これで、もはや貴方達に出来る事は無くなりました、さっさと逃げて下さい、ね?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "……そうさせて頂きます、ティア様はヤマトさんをお願いします" },
  { text: "悪魔の言葉に偽りはない。｜邪魔《じゃま》をする事は無いようだ。私は倒れた勇者を引き摺り、エルの元へと連れて行く。ティアもヤマトを引き摺って同じ場所へ。最後に｜魔杖《まじょう》クロセルを拾い、全員が揃う。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "あーそれと……それ、持って行くと良いですよ" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "魔王の死体……ですか?" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "はい、立場があるのでボクの口からは詳しく言えませんが……面白い事に使える筈なので" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "……何故でしょう、私の直感が貴方は信用出来ると告げています" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "悪魔なんかを信じると痛い目をみますよ?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうかもしれませんね" },
  { text: "私は少女の悪魔が言う通りに、腹部に大穴を空けて絶命している魔王の死体を引き摺っていく。転移魔法の消費魔力は、転移する質量に依存する。転移に成功したと同時に、私も倒れることになりそうだ。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "新たな魔王の誕生まで……どれくらい｜猶予《ゆうよ》がありますか?" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "うーん言って良いのかなぁ……ま、死んでもらっちゃ困りますし教えましょう、3日ぐらいです" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "結構あるんですね……因みにそれまでの間に、その肉魂を壊したらどうなるんですか?" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "無駄ですよ、\"卵\"は神の強制力によって保護されている、才能を持つ生物がこれを傷付ける事は出来ない" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "それは……つまり……魔王の仕組みは神が作った物……そういうことですか?" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "無知だなぁ……ま、そう思うならそうなんじゃないですか?ボク真面目な話苦手と言うか、つまらないんですよね……さっさと失せてくれます?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうします、色々とありがとうございました" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あははははは!ボクに感謝の言葉?あははははは!なんて人間は馬鹿なんだろう!悪魔に感謝をするなんて!流石に冗談が過ぎますよ!?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "神が善行だけをするとは限らないし、悪魔が悪行だけをするとは限らない、大切なのは\"それが誰であるか\"じゃないんですよ" },
  { name: "ラプラス", who: "laplace", expr: "sulk", text: "は?脳みそ腐ってるんじゃないですか?悪魔は悪行しかしーまーせーん!間違えないで下さい、全く" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "まぁ……そういうことにしておきましょう、そうです、私達人間は愚かで馬鹿なんです" },
  { text: "何故か私は悪魔に笑顔を向けた。魔王を殺し、封印する手段を破壊し、新たな魔王を生み出した恨むべき存在であるはずなのに。何故か。それは私には分からない。" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "｜魔術回路構築《クリエイト》……詠唱……ル・トゥーム・アウナデム・ティロワール……空間魔術……｜空間接続《ゲート》!" },
  { se: "magic" },
  { fx: "flash" },
  { text: "全身から一気に魔力が引き抜かれ、辺りは閃光に包まれる。目的地はロイトンの我々の拠点。それ以上遠くに飛ばなかった理由は、今の魔力残量では転移が厳しそうであったからだ。" },
  { text: "実際……ぽっかりと胸に穴が空いたような感覚と同時に、意識が遠のく。転移した先での事は、エルとティアに任せよう。私も……少し疲れた。" },
  { hide: "all" },
  { chara: { slot: "center", id: "laplace", expr: "normal" } },
  { text: "――誰も居なくなった広間。残されたのは、二本の剣と、物言わぬ肉魂。そして、聖剣を｜弄《もてあそ》ぶ黒髪の少女だけ。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "あ、それとこれ返さないと……って行っちゃった……" },
  { text: "悪魔の少女は、思い出したかのように聖剣を振る。しかし、そこにはもう誰も居ない。誰か残っている人間は居ないだろうか……と辺りを見渡すが、残された人間は居なかった。" },
  { name: "ラプラス", who: "laplace", expr: "laugh", text: "まぁ良いか、貰っちゃお" },
  { text: "少女は聖剣を軽く振ると、小さく笑みを浮かべ、その場に座り込んだ。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "それより……ボクも現界し過ぎたな……折角喰らった最後のリソースだってのに" },
  { text: "座り込んだ少女の身体。ゆっくりとその姿が透明化していく。" },
  { name: "ラプラス", who: "laplace", expr: "normal", text: "まぁ、魔王様が目覚めれば幾らでも魔力が供給されるだろ……えーっと……次の魔王は" },
  { fx: "flash" },
  { text: "少女の青い瞳が一瞬、一際強く輝く。そして、小さく頷くと、少女は消え行く身体で肉魂へと背を預けた。" },
  { name: "ラプラス", who: "laplace", expr: "blank", text: "新たな魔王オセ様……貴方が目覚める時を……ボクは……楽しみに待っています" },
  { text: "やがて、少女の身体は光の粒子になって消え失せる。そして、そこには、ただ二本の剣と、物言わぬ肉魂が残された。" },

  // ===== シーン17: 敗走 (EP50〜51) =====
  { label: "retreat_choice" },
  { pov: null },
  { fade: "out" },
  { hide: "all" },
  { bg: "tarf_inn", instant: true },
  { fade: "in" },
  { bgm: "sad2" },
  { text: "俺は、ベッドの上で目を覚ます。生きている。その事実に安堵する。続いて、鼻腔を刺激する死臭で場所を予感する。皆は……皇帝は……魔王は……どうなったのだろう。" },
  { chara: [
    { slot: "left", id: "el", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "エル", who: "el", expr: "smile", text: "目が覚めた?ヤマト様" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "エルか……皆は……無事か?" },
  { name: "エル", who: "el", expr: "surprised", text: "驚くことに……全員無事だよ……アカツキ様が言うに……あの悪魔が逃してくれたとか" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "嘘だろ?あの悪魔が?" },
  { text: "才能の解放は心身共に大きく消耗する。まだ全身の節々が痛むが、無理を効かせて俺は起き上がる。此処は拠点だ。アカツキかティアの転移魔法で戻って来たのだろう。エルは俺の事を介抱してくれていたらしい。感謝しなければ。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "迷惑掛けたな、助かった" },
  { name: "エル", who: "el", expr: "smile", text: "いえいえ……私はヤマト様の世話係だからね" },
  { text: "王城を離れた今、エルが俺に仕える理由は無いというのに、律儀な子だ。俺はベッドから立ち上がり、辺りを見渡す。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "アカツキは……寝てるのか" },
  { name: "エル", who: "el", expr: "normal", text: "魔力欠乏で、此方に転移した直後に意識を失ってしまったみたい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "魔力が枯れると意識を失うのか……俺には分からない感覚だな" },
  { name: "エル", who: "el", expr: "normal", text: "魔力と言っても体力と似たような物だからね、短時間の内に継続的に使用しなければ負担はない" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "体力と違ってリミッターが無いから意識を失うまで使える訳か……簡単に無茶出来るのは便利そうだが……少し恐ろしいな" },
  { name: "エル", who: "el", expr: "sad", text: "そうだね……私も気を失うまで魔術を使った事は無いから……少し怖い" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "それより、エルは大丈夫なのか?" },
  { name: "エル", who: "el", expr: "normal", text: "うん、直ぐに立てなかっただけで……傷自体はどれも浅い、勇者様のお陰だよ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あいつのお陰?" },
  { name: "エル", who: "el", expr: "smile", text: "彼は私を庇ってくれたから……感謝してる" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あいつが身を挺して人を庇うとか……想像出来ないな" },
  { name: "エル", who: "el", expr: "smile", text: "格好良かったよ、勇者様" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "よくやるよな……祝福があるからと言って無茶しやがって……" },
  { text: "勇者は祝福によって高い自己修復能力がある。数日もすればいつもの調子に戻るだろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それより……クロセルは何処だ?まさか置いてきては無いよな?" },
  { name: "エル", who: "el", expr: "smile", text: "大丈夫、ちゃんと連れてきてるよ" },
  { text: "そう言うと、エルは俺に杖を差し出す。それを手の中で転がしながら、俺は大きく頷く。間違い無い、クロセルだ。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "良かった……これで俺も一安心だ" },
  { name: "エル", who: "el", expr: "smile", text: "ヤマト様はクロセルさんが大切なんだね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "当たり前だろ、こいつは俺の物だ、誰にもやらん" },
  { name: "エル", who: "el", expr: "smile", text: "あはは……私は取ったりしないから安心して" },
  { text: "エルが困ったように笑う。気が付けば、俺は｜魔杖《まじょう》クロセルを胸にしっかりと抱き抱えていた。クロセルの仮初の身体は皇帝によって破壊された。あれが死を意味するとしたら……ふと、このまま目覚めないのでは無いかと、不安になる。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "らしくないな……考えるのはやめよう" },
  { name: "エル", who: "el", expr: "sad", text: "どうかした?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "大したことじゃない、気にするな" },
  { text: "エルが心配そうに俺の顔を覗き込んでくる。俺は小さく首を振ると、心に掛かった暗雲を晴らすように軽く手をパンと叩く。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ところで、皇帝と魔王はどうなった?" },
  { name: "エル", who: "el", expr: "sad", text: "魔王は死んで、皇帝が魔王の力を継承した" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "やっぱりそうなったか……｜猶予《ゆうよ》は?" },
  { name: "エル", who: "el", expr: "sad", text: "悪魔の言葉が確かなら……3日" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、それだけあれば逃げれるな" },
  { name: "エル", who: "el", expr: "sad", text: "何処に逃げるの?" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "俺とクロセルは王国には戻らない。行くなら……そうだな、教国とやらを目指すか" },
  { name: "エル", who: "el", expr: "sad", text: "王国に戻らないの……?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あ?別に着いて来る必要はないぞ、お前が王国に戻りたいなら俺は止めない" },
  { name: "エル", who: "el", expr: "sad", text: "いや、それなら私も着いて行く" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "良いのか?" },
  { name: "エル", who: "el", expr: "smile", text: "うん、私はヤマト様に着いて行くって決めたから" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうか" },
  { text: "俺達は任務に失敗した。魔王の復活を許し、新たな魔王を生み出してしまった。俺達は罪人だ。このまま涼しい顔で王国に戻る事は出来ない。帝国は間も無く魔王の手に落ちるだろう。そうなると、安全な教国に逃げるのが得策に思える。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "俺は身勝手だからな、魔王を倒すだとか世界を救うとかいう面倒な事に手を出すつもりはない。そんなのは俺の仕事じゃない、勇者の仕事だ" },
  { name: "エル", who: "el", expr: "smile", text: "そうだね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "今回の任務も皇帝に対する私怨を晴らす為に同行したに過ぎない" },
  { name: "エル", who: "el", expr: "smile", text: "私もヤマト様の世話をしたかったから着いて来た、世界がどうなるかなんて、興味ない" },
  { bgm: "heartwarm" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "そうか……ならまぁ、良いだろう、これからも俺に着いて来い" },
  { name: "エル", who: "el", expr: "smile", text: "うん" },
  { chara: { slot: "center", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "そうですか、ヤマトさんは逃げるんですね" },
  { text: "そんな会話をしていると、アカツキが部屋に入ってくる。いつの間に目が覚めたのだろう。盗み聞きとは趣味が悪い。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そうだ、何か文句があるか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "いいえ?ありませんよ、ただ……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ただ、なんだ?" },
  { text: "アカツキは俺の元に歩み寄ると、少し考えるように目を瞑る。そして、溜息を一つ吐くと、目を開いて言葉を続けた。" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私もヤマトさんに着いて行きます" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……マジで?お前の本来の仕事って国王秘書だろ?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "確かにそうです、国王には恩があります、それを仇で返すような真似になってしまうのは不本意です……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ならどうして……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私の独断です、私がそうしたいからそうするのです。私だってヤマトさんに負けず劣らず、我が儘なんですよ?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "着いて来いと言う訳じゃないんだぞ?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "はい、私が勝手に着いて行きます" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "揃いも揃ってどうして俺なんかに着いて来るんだか……俺には理解できん" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そんなことより……問題はティア様と勇者ですね……勇者は放っておいても良いとして" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ティアを放置する訳にはいかないな、王国に連れ帰るのも出来ない、となると……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "彼女の意思に関わらず、連れて行くことになりますね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "アカツキだけでも帰ってくれれば解決するんだが……" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "酷いですね、そんなに私が嫌いですか?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "馬鹿か、嫌いなら連れて行くことなんか了承しねぇよ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "それは良かった" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ったく……これじゃ殆ど全員着いて来る事になるじゃねぇか" },
  { name: "エル", who: "el", expr: "smile", text: "これは……予想通りだね" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "同意します、エルさん" },
  { text: "小さく笑いながら顔を見合わせるアカツキとエルを見て、俺は溜息を吐く。これからは魔王と帝国と王国、これからはそれら全てと敵対した状態になる。俺達は無事に生きていけるのだろうか。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうそう、それと、ヤマトさんに見て貰いたい物が" },
  { text: "アカツキが取り出したのは、拳サイズの水晶球。だが、それが只の水晶球では無い事は一目瞭然であった。仄かに紅い光を放ち、球体に映り込む世界は真っ赤に染まっている。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "これは……なんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "魔王です" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "魔王?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "正確に言えば……魔王の遺体です" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "この水晶球が?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうです" },
  { text: "アカツキが言うに、この水晶球は魔王の遺体が変化した物だと言う。にわかには信じられないが、アカツキが嘘を言う理由は無い。これは間違いなく魔王の遺体なのだろう。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "けど……どうしてこんな姿になったんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "分かりませんが……ヤマトさんに持っていて欲しくて" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "なんで俺なんだ?こんな怪しい物受け取れと言われても困るんだが……" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "なんでと言われても……その方が良い気がするだけなので、何も言い返せませんが……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あ、いや、お前の\"気がする\"は信用出来る、言う通りに、俺が預かっとこう" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうですか、それではどうぞ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……驚くほど軽いな" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "私も思いました、まるで空気を持っているかのような軽さです" },
  { text: "俺は水晶球を掌で転がす。確かに空気より重く、故に掌に乗っているというのに、全く重さを感じない。不思議な球だ。俺はそれを一枚の布で包むと、懐に仕舞う。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それじゃあさっさとロイトンから離れるか、俺待ちだったんだろ?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "いえ、私もさっき目が覚めたので" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか、ティアは起きてるか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "部屋に居る筈です" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "よし、それじゃあ行くか" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ニコラスさんは良いんですか?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あいつは置いていく、俺の旅には｜邪魔《じゃま》だ" },
  { name: "エル", who: "el", expr: "smile", text: "かわいそうな勇者様……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "文句があるのか?" },
  { name: "エル", who: "el", expr: "smile", text: "無いですよ、可哀想だなと思っただけで" },
  { text: "エルが少しだけ勇者を気遣う素振りを見せる。なんか腹が立つ。勇者の奴、一発殴ってから行くべきだろうか。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "まぁ良い……起きる前にさっさと行くぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "全く、ヤマトさんは気が早いですね、荷物を纏めるので少し待ってて下さい" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "俺はティアを呼んでくる、表で集合な" },
  { text: "ティアの部屋に行くと、奴は俺の元に嬉しそうに飛び付いてきた。俺が王国に戻ることを説明するが、話を最後まで聞くこと無く着いて来るの一点張り。この様子なら案じる必要も無かったか、なんて思いつつ。俺は拠点を出て、アカツキを待った。" },
  { text: "そして、その日の内に。俺達はロイトンを発つのであった。" },

  // ===== シーン17b: 旅路・魔族の理 (EP51) =====
  { label: "ep51_journey" },
  { fade: "out" },
  { hide: "all" },
  { bg: "country_road", instant: true },
  { bgm: "daily2" },
  { fade: "in" },
  { text: "馬車という足を失った俺達は、辺り一面を森に覆われた道を、ティアを背負って歩いていた。重くはないが軽くもない。地味に体力が失われていく。" },
  { text: "アカツキが言うには、ただひたすら道なりに進めば街に着くと聞いたが、かれこれ半日近く歩いても、その街とやらは見えてこない。馬車という足を壊されたのは、やはりそこそこの痛手だ。あれは一朝一夕に用意出来る物ではない。" },
  { chara: [
    { slot: "left", id: "el", expr: "normal" },
    { slot: "right", id: "yamato", expr: "sad" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "はぁ……次の街まで……後どれくらいだ……" },
  { name: "エル", who: "el", expr: "normal", text: "あと少しですよ" },
  { name: "ティア", who: "tia", text: "もう……ヤマトはだらしないのね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "馬鹿、お前を背負って無ければこれぐらい余裕だ" },
  { name: "エル", who: "el", expr: "smile", text: "荷物持ちに勇者を連れてきても良かった気がするね……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "その扱いは流石の勇者でも可哀想だな……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば、魔王ってのは魔王領を統べるのが普通なのか?" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうでもありません、古い文献によると、魔王領を放置して人間の国を統べていた事もあるそうです" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "魔王領なんにも無いからな……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、魔王領と言えば、魔の塔と無数の迷宮、あと魔王城があるぐらいですね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "魔王城……ってのは魔王の根城か?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "そうなります、魔王が魔王の権能を振るえるのは魔王城でのみ、魔王城の外では所詮とてつもなく強い魔物のような物です" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "魔王の権能ってのは?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "魔物、魔族への絶対命令権、それと魔王固有の何らかの\"才能\"です" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "自分の城でしか才能を発揮できないとか可哀想だな……んで魔族ってのは?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "神が人に祝福を与えるのと同じように、魔王は人に｜穢れ《けがれ》を与える事が出来ます、魔王から｜穢れ《けがれ》と力を与えられた種族、それが魔族です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "｜穢れ《けがれ》ってのは才能なのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "いいえ、より深い、魂に刻まれる呪いのような物です。一度でも｜穢れ《けがれ》を受けた種族は、その｜穢れ《けがれ》が必ず子に継承される為、永遠に魔王の支配から逃れることは出来ません" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "そりゃ恐ろしいな……" },
  { text: "俺はクロセルを手の中で転がす。こいつもかつては魔王だったのだと思うと、魔王という存在がとても小さな存在に感じられる。実際はそんな事無いのだろうが、元魔王と当然のように暮らしてきた俺からすれば、魔王なんて物は身近でありふれた存在なのだ。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "魔王になると人格が変わったりするのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "angry", text: "そうですね、元の人格は破壊され、殺人、略奪、破壊の衝動に支配されると聞きます" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それを抑え込んだ魔王の前例とか無いのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "私が知る限りでは……居ませんね。唯一、先代の魔王グレモリーが衝動を抑えられず自身を封印した例があるぐらいです" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "やっぱり抑えようとした奴は居るんだな……今まで多くの魔王が居て、中には衝動を抑えようとした奴も居た筈だ、それが一度も成功してないとなると……望みは薄いか……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "皇帝が衝動を抑えるかもしれない、と思ったんですか?" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "あ?それは無い、あいつが衝動を抑えるとかありえない、衝動に任せて｜暴虐《ぼうぎゃく》の化身となるのが関の山だろうよ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "そうですか……" },
  { text: "そんな風に歓談しながら歩いていると、遥か遠くに街が見えてくる。当然だが、アカツキの言葉に間違いは無かった。このまま転々と街を渡り歩き、目指すは教国とやらだ。神の加護があり、魔王の侵略とは最も縁のない土地。王国や帝国なんかよりは、きっと安全だろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば、転移と馬車による移動ばっかりで全く掴めてないんだが、国同士の位置関係ってどうなってるんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "一つの大きな円を思い浮かべてください。それをざっくり五等分。最北に位置する王国から時計回りに帝国、教国、公国、魔王領となります。大きさは魔王領が一番大きく、続いて王国、帝国、公国。そして教国が一番小さい国となります" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "なるほどな……なんとなくだが理解した" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ヤマトさん……地理は苦手そうですね……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "義務教育すらまともに修了してないからな、俺の知能に期待するなよ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "そうなんですか……それにしては頭が回る気もしますが" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "場数と経験だけは踏んできてる。大体は経験則と勘だ、俺に知識なんて皆無だぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "それでも勇者のように只の馬鹿に見えないのは……やはり天性のカリスマですかね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "まぁ、前世も支配階級だったからな、俺の偉力に人が集まってくるってのはあるだろう" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "それを自分で言いますか……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "事実だから仕方ない" },
  { name: "ティア", who: "tia", text: "ヤマトは昔偉い人だったの?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、そうだ、俺は昔暴君だった" },
  { hide: "all" },
  { chara: [
    { slot: "left", id: "el", expr: "smile" },
    { slot: "center", id: "yamato", expr: "normal" },
    { slot: "right", id: "akatsuki", expr: "normal" },
  ] },
  { name: "ティア", who: "tia", text: "暴君?ヤマトは悪い人じゃないわ!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "んな事言われてもなぁ……" },
  { text: "前から思うが、周りからの俺の評価が些か高すぎる気がする。根はこんなにもクズで悪い人間だと言うのに。" },
  { name: "エル", who: "el", expr: "smile", text: "私も、ヤマトは良い人だと思う" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私もそう思いますよ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "おい……やめてくれ……褒められるのは性に合わない、というか気分が悪くなる……勘弁してくれよ" },
  { text: "周りから絶賛を受け、俺は頭を抱える。穴があったら入りたい。もう少し悪い子アピールをした方が良いのだろうか。でもどうやって?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ふむ、そうだな……ならこうしてやろう!" },
  { text: "色々と考えた末に一つの答えが思い付いた。それは何かって?まず暴力はいけない、つーか出来ない。なら言葉で脅す?それもダメだ、こいつらには効かない。それなら……セクハラするしか無いだろ!" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ちょっと……ヤマトさん!?" },
  { name: "エル", who: "el", expr: "smile", text: "おっと……今日は珍しくヤマト様が積極的だね" },
  { text: "歩調を緩め、横を歩く二人と一歩分の距離を取る。そして、クロセルを脚で挟むと、素早く両手を伸ばし、二人の尻を揉む。全ては俺が思い描いた通り。我ながら完璧な動きだ。" },
  { text: "両手に柔らかい感触を感じると同時に、俺は反撃を覚悟して目を閉じる。が……反撃は飛んでこなかった。というか俺の手から逃れる素振りすらない。何故だ。" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……逃げろよ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "何を言ってるんですか!自分で離して下さい……全く……" },
  { name: "エル", who: "el", expr: "blush", text: "んっ……ヤマト様が望むなら……私はこのままでも良いけど……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ったく、これで分かっただろ、俺は変態な悪い子だ" },
  { name: "ティア", who: "tia", text: "ヤマトは変態なのね!" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうだ!わかったな!" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "色々と方向性が間違ってる気がしますが……はぁ……まぁ良いでしょう" },
  { name: "エル", who: "el", expr: "blush", text: "終わりか、残念" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "何を名残惜しそうに俯いてるんだ……嫌な癖に……" },
  { name: "エル", who: "el", expr: "blush", text: "え?私は嫌なんて一言も言ってない" },
  { text: "取り敢えず手を離す。確かに良く考えなくとも馬鹿な事をした。こんな事で悪い人間だとアピール出来る筈が無い。これじゃあ勇者と同レベルだ。自己嫌悪で足取りが重くなる。" },
  { text: "そんな俺の気持ちなどいざ知らず、エルは｜傍若無人《ぼうじゃくぶじん》と振る舞う。アカツキも先程の声色こそ怒気が含まれつつも、今はもう気にした様子はない。全く……俺の周りは精神面が屈強な女ばかりだ。もう少し嫌がってくれないと俺が困る。" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "何か失礼な事考えてません?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "気の所為だ、勝手に落ち込んでるだけだから気にするな……" },
  { name: "エル", who: "el", expr: "smile", text: "なんというか……相手が悪かったね……今ヤマト様がやったことは此処じゃ逆効果だよ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "逆効果って何だよ……セクハラで好感度が上がるってか?" },
  { name: "エル", who: "el", expr: "smile", text: "あれ……よく分かってるじゃないか" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "嘘だろ……何だこの世界、どうなってるんだよ……" },
  { text: "俺は頭を抱える。どうやら異世界である此処じゃ俺の知っている常識は通用しないようだ。俺はただ悪い人間を装いたかっただけだと言うのに、なんとも難しい。" },
  { fade: "out" },
  { hide: "all" },
  { bg: "tarf_town", instant: true },
  { bgm: "town" },
  { fade: "in" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ほら、そんな事言ってる間に街に着きますよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ……此処で馬車を手に入れて教国まで逃げるんだな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "はい、魔王の誕生が発覚したら需要が急激に増えて馬車なんか二度と手に入らないでしょう、なので今の内に時間を使ってでも手に入れます" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "懸命な判断だ、それじゃあ此処に少し滞在する事になるのか" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "任せて下さい、一日あれば用意出来ます" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "嘘だろ……マジで?" },
  { name: "アカツキ", who: "akatsuki", expr: "laugh", text: "ふふふ……私の事を舐めないで下さい、これでも王国一の敏腕秘書ですから" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "直感と分析の才能しかない癖によくやるよな……" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "その台詞、ヤマトさんにだけは言われたくないですね……" },
  { text: "そんな会話をしながら、俺達四人は街に入る。ロイトンのような死んだ街で過ごしたせいか、人の活気が新鮮だ。此処も明日か明後日には離れる事になる。余り思い入れないようにしておこう。" },
  { fade: "out" },
  { hide: "all" },
  { bg: "tarf_inn_night", instant: true },
  { fade: "in" },
  { chara: [
    { slot: "left", id: "el", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "今夜は久々にまともなベッドで眠れそうだな" },
  { name: "エル", who: "el", expr: "sad", text: "ロイトンの廃屋は酷かったからね……" },
  { text: "手頃な宿を見付け、俺はアカツキと別れると、割り当てられた部屋に向かう。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "四人部屋か……アカツキの奴……金はある癖にケチだな" },
  { name: "エル", who: "el", expr: "normal", text: "クロセルさんが起きたら一人溢れてしまうね……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、それなら心配要らない、クロセルは俺と同じ所で寝るだろうからな" },
  { name: "エル", who: "el", expr: "blush", text: "そ……そうだったね……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "……言ってから気付いたがこれだと色々と誤解されかねんな" },
  { name: "エル", who: "el", expr: "smile", text: "確かにそうだ……でも私は分かってるから、大丈夫だよ" },
  { text: "俺は柔らかいベッドに腰を下ろす。ティアを背負いっぱなしで中々疲れた。肩も若干凝っている気がする。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "エル、肩を揉んでくれ" },
  { name: "エル", who: "el", expr: "blush", text: "……良いの?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "何がだよ" },
  { name: "エル", who: "el", expr: "surprised", text: "そういうのはクロセルさんの特権かなって……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "お前も俺の世話係だろ、これもお前の仕事の一部だ、気にするな" },
  { name: "エル", who: "el", expr: "smile", text: "言われてみればそうだね、じゃあ失礼して" },
  { text: "エルが俺の後ろに回り、肩に手を触れる。心做しかエルの手は冷たい。こうやって触れ合っていると、帝都に向かう馬車の中で熱を出した時の事を思い出す。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば改めて礼を言ってなかった、あの時はありがとな" },
  { name: "エル", who: "el", expr: "surprised", text: "あの時……とは?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "帝都に向かう馬車の中だよ、俺が熱を出した時、ずっと手を当ててくれてただろ" },
  { name: "エル", who: "el", expr: "smile", text: "あぁ……そのことなら気にしないでよ、私はヤマト様の世話係なんだから" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "王国を離れた時点でその役割からも離れてるだろ、もうお前が俺に尽くす義理はないんだぞ" },
  { name: "エル", who: "el", expr: "smile", text: "分かってる、これは私がやりたくてやってるだけだから……" },
  { text: "前から思っていたが、こいつが俺に尽くす理由は今でも不透明だ。単に世話好きなのか、或いは何か思惑があってのことなのか。どちらにせよ、俺に害が無いならばそれで良い。" },
  { text: "有用なら使い潰すまでだ。そんな事を考えている内に、エルが俺の肩を揉みほぐしていく。中々の｜お手前《おてまえ》だ。だいぶ肩が軽くなった。" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "よし……そろそろ良いぞ、ありがとな" },
  { name: "エル", who: "el", expr: "smile", text: "こちらこそありがとう" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "なんでお前が感謝するんだよ……" },
  { name: "エル", who: "el", expr: "smile", text: "あはは……なんでだろうね" },
  { text: "他愛も無い会話をしながら、俺達は笑い合う。こんな平穏無事な日常を過ごしながら旅が出来れば、俺は満足だ。クロセルとの二人旅も魅力的だが、エルやアカツキが居る旅も悪くない。" },
  { text: "何より｜邪魔《じゃま》な勇者が居ないだけでこれほど快適な空間になるとは思わなかった。良くも悪くも、勇者には感謝せねばなるまい。" },
  { text: "そしてその日の夜。俺は未だ目覚めることの無いクロセルを抱えて、深く気持ちの良い眠りにつくのであった。" },

  // ===== シーン18: 教国へ・魔王オセ誕生 (EP52〜53) =====
  { label: "ose_broadcast" },
  { fade: "out" },
  { hide: "all" },
  { bg: "country_road", instant: true },
  { bgm: "daily2" },
  { fade: "in" },
  { text: "逃避行の道中、ある街の宿。端的に言えば、その日、クロセルが目を覚ました。と言っても……いつかのように半透明だ。なんでも魔力が枯渇し実体化出来なかっただけで意識はあったらしい。少しは反応してくれても良かった気がするが。" },
  { text: "姿こそは弱々しくも、その口調は元気そのものだ。元気な姿を見れて嬉しくもあるが、少し腹が立つ。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "laugh", ghost: true },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふはははは!我!完全復活!" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あーうるせぇうるせぇ……ったく……心配して損した" },
  { name: "クロセル", who: "crocell", expr: "blush", text: "何!?ご主人は我を心配してくれてたのか!?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "馬鹿、嘘に決まってるだろ" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "なんだ……そうか……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "再三言うがお前は馬鹿か……嘘なのは損したって方の事だ、決まってんだろ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "それはつまり……やはり心配してくれてたのだな!ご主人!我は一生ご主人に着いて行くぞ!" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "んな事は元から分かってる、まぁ……無事目を覚ましたようで良かった" },
  { chara: { slot: "center", id: "el", expr: "smile" } },
  { name: "エル", who: "el", expr: "smile", text: "ヤマト様も素直になってきたね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あ?何か文句があるか?" },
  { name: "エル", who: "el", expr: "smile", text: "そんな事無い、素直なのは良い事だと思う" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そうか……まぁ俺は嘘が苦手だからな" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "クロセルさんに嘘をついた直後に堂々とそれを言いますか……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "細かいなぁ……嘘が苦手なのは本当だ、だが嘘を言わないとは一言も言っていない" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そうですか……まぁ良いでしょう、取り敢えずさっさと乗って下さい、明日までに国境を越えられないと色々と面倒なので" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "確かに魔王の誕生が知れ渡ったら安全である教国の国境には規制が入りそうだよな……" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "そういう事です、ですので早く" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "分かった分かった、ほらクロセル、行くぞ" },
  { text: "俺はクロセルの手を引いて、馬車に乗り込む。そこにエルとティアが続き、アカツキが俺達全員が乗り込んだのを確認すると、一つ頷く。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "余り大きな馬車では無いので、この人数だと狭いと思いますが我慢して下さい" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "｜御者《ぎょしゃ》が居ないが……アカツキが動かすのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうです、経験は無いですが……まぁ勘でなんとかなるでしょう" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "｜些《いささ》か心配だが他に出来そうな奴も居ないしな……" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "うむ、残念だが我も馬を走らせた経験は無い" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "それにしても本当に一日で用意したんだな……流石としか言いようがない" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "こう見えて本当は結構危ない橋を渡ったんですが……結果オーライですよね" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "それは良くないな……次から危ない事に手を出すなら俺を連れてけよ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ヤマトさんが居ると事態が悪化しかねないので……遠慮しておきます……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "なんだと?俺が面倒事を起こすとでも?" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "我もアカツキに同意だぞ、ご主人に穏便な交渉事は向いてない" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "まぁ……そうか……否定はしない" },
  { text: "クロセルに｜窘《たしな》められる。これに関しては、俺の経験からしても事実だから何とも言えない。喧嘩っ早い俺の性格は、確かに交渉事には向いて無さそうだ。だが待って欲しい。" },
  { text: "間違い無くクロセルの交渉は俺より過激だ。こいつ、人の事は言えないのではないだろうか。まぁ、実際それで事が上手く運び、助かっている以上、文句は言えない。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "では出発しますよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おう" },
  { text: "そんな短いやり取りの後に、ややぎこちなくも、馬車は走り出す。" },
  { fade: "out" },
  { hide: "all" },
  { bg: "desert_border" },
  { bgm: "mystery2" },
  { fade: "in" },
  { text: "馬車は砂漠の国・教国を目指して走り続ける。｜御者《ぎょしゃ》の経験は無いが、直感の才能で勘に従えば何でも上手くいくと、アカツキが手綱を握る。前から思っていたが、直感の才能は勘に従って事を運べば何でも上手くいく才能だ。正直、あれはチートスキルだ。万能すぎる。" },
  { text: "率直に言って羨ましい。才能指数の格差は今まで何度も感じてきたが、才能の種類でもかなり格差があると実感した。同じ魔術でも『魔術』と『空間魔術』では出来る事の幅が全く違う。" },
  { text: "才能指数だけでは測れない、才能の種類で決まる価値も存在するのだ。そう考えると、相変わらず神とやらは不公平な奴だと思う。" },
  { text: "まぁ……仮に公平だった場合、それはそれで大変な世界になるのだろうし、不満を唱えられる立場では無いのだが。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "この調子なら明日には国境まで行けそうですね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "最初はぎこちなかったが、馬を走らせるのも慣れたもんだな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "こればっかりは才能の｜賜物《たまもの》ですね、もうコツは掴みました" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "無理はするなよ、夜には一度馬車を止めて休むべきだと思うが" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "いえ、これは時間との戦いですから、今夜は走り続けます" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我もアカツキの意見に賛成だな、此処は踏ん張り所だ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "クロセルやアカツキの転移魔法じゃダメだったのか?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "我は一度も教国に行ったことがない" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "私も同じです" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセルは兎も角、アカツキは外交で訪れる機会もありそうな物だが……そこまで閉鎖的な国なのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "その通り、教国は他国との外交を一切行わない閉鎖的な国です、とある各国の首脳が集う会談の場においても、トップである教皇が出席したのを私は一度も見たことがありません" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そうか……" },
  { text: "外交が無いと言う事は他の国家に頼る事無く国家として完結しているという事でもある。これは、神の力の影響が大きいのかもしれない。魔の者を退けると聞く神の加護。" },
  { text: "それが確かならば、教国では魔物の脅威に怯える必要も無い。魔物の問題が無いとなれば、その分の人手を生産に注力出来る。そう言った理由もあり、小さくも豊かな国なのだろう。……と思ったのも束の間であった。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人、そう言えば勇者は本当に置いてきて良かったのか?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "連れてく理由が無いだろ、あいつ肉壁にしかならんぞ" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人より強いのだぞ……?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "うるせぇ、あいつは皇帝に負けた、俺は皇帝に勝った、だから俺の方が強いんだ" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人、我が負けた後、あの皇帝に勝ったのか?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あぁ、剣術のディザビリティを使ってな" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "ぐぬぬ……我が負けた相手にご主人が勝ったのか……嬉しくもあるが悔しいぞ……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "つまり、俺が最強って事で良いんだよな?" },
  { name: "クロセル", who: "crocell", expr: "normal", text: "揉め手を使ったと言えど、勝ちは勝ちだ、ご主人の強さは認めざるを得ないな……" },
  { name: "エル", who: "el", expr: "smile", text: "実際、ヤマト様は強いからね、黒ずくめと相対した時も、私なんかよりずっとキレのある動きをしていたし" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そうだ、俺は強いんだ" },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人……さては\"あの力\"の事を我以外に言ってないな?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "何のことだ?俺は知らないな" },
  { name: "クロセル", who: "crocell", expr: "sad", text: "全く……これで嘘は苦手とはどの口が言うか……" },
  { text: "クロセルが呆れたように溜息を吐く。彼女の言う通りだ。俺は自分の力の事をクロセル以外に言っていない。だが、それは言う必要が無いから伝えていないだけだ。敵を欺くにはまず味方から。奥の手は隠しておくべきだと思っている。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "……何か事情がありそうですし……深くは聞かないでおきましょう" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "流石はアカツキだ、話が分かる" },
  { text: "話を聞いていたのか、前方からアカツキの声が聞こえてくる。思考せず勘だけで馬を走らせているからか、会話を聞くだけの余裕があるようだ。" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "なんか……暑くないか?" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "もうすぐ砂漠に入りますからね" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "砂漠……ってのはあの砂漠で良いんだよな?これまた突拍子だな……" },
  { chara: { slot: "left", id: "crocell", expr: "normal" } },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ご主人が無知なのが悪い、教国は広大な砂漠地帯にある国だぞ" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "んな事一度も聞いてない……分かる訳無いだろ" },
  { chara: { slot: "left", id: "akatsuki", expr: "normal" } },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "ヤマトさんの知っている砂漠で相違無いと思います、滅多に雨が降らない乾いた土地、一面が砂で覆われた大地です" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そうなのか……なんか色々と意外だな" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ヤマトさん……何も知らずに教国を目指すとか言い出したんですか?" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "魔王から逃げるにはそれ以外に方法が無かったからな、王国でも良かったが……それはそれで面倒だしな" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "計画性がないですね……本当にこんな人に着いて来て大丈夫だったのでしょうか……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "今更後悔しても遅いぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "分かってますよ、覚悟は決めてます" },
  { text: "馬車の外に軽く顔を出すと、確かに辺りの空気が乾いており、空からは熱射が降り注いでいる。砂漠に近付いている証拠だろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ところで……砂漠の悪路を……馬車で走れるのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "教国は舗装された道路が整備されてるんですよ……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "マジで……?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "マジもマジ、大真面目です" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "どういうことだよ……道路舗装技術とかこの世界にあるのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "いえ、道路は神の奇跡による創造物です" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "道路を神が作ったって言うのか?何の為に?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "さぁ……?神が奇跡を起こせるのはご存知ですよね?もしかしたら教国の民の願いを奇跡で叶えたのかもしれません" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "もしかしたら……ねぇ……神の気まぐれの可能性も有り得るって訳か" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "真実はまさに神のみぞ知る……って奴ですね" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "……" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "なんで黙るんですか……" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "得意げに言ってる様子が可愛かったからな" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "なっ……!?" },
  { text: "ニヤニヤと下衆い笑みを浮かべながら、そんな言葉を投げる。此処からでは馬車を走らせているアカツキの顔は伺えない為、声色から察しただけだが。どうやら図星だったらしい。" },
  { text: "とまぁアカツキは放っておいて。俺の中の神のイメージがまた変質した。今までのイメージは、言い例えるなら絶対中立な観測者。自衛に走ることはあれど、直接人の世界に手は出さない。そういう存在だ。" },
  { text: "だがこの話だと、民心に耳を傾けて絶対的な力を行使する。言うなればキリストのような救世主的な存在に近いように思える。しかしまぁ、百聞は一見に如かずだ。実際に神に会ってみない限りには、全ては推測の域を出ない。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ところで……神が国の為に奇跡を行使するなら、神を巡って戦争が起きないか?" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "神が教国に抱えられるのは数百年規模の暗黙の了解になってるみたいですね……神が居る限り、教国を攻め滅ぼすことは出来ないので" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "その言い方だと……前例があったように聞こえるな" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "その通りです、過去に何度か、神を巡って戦争が起きています" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "結果は?聞くまでもないか……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "千年以上前の話ですが、教国に属する勇者の軍勢が神罰を代行し、戦争は終結したとされています" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "勇者の軍勢……?" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "『勇者』の才能の本質は、その才能を持つ者は\"神に属する対価に力を得る\"という所です。勇者は神の下僕であるからこそ、神による祝福を受けられます" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "詰まる所、勇者ってのは生まれてから死ぬまで神の下僕として生きる訳か……なんか嫌だな……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "同感です、ですが私達の持つ\"才能\"は神の生み出したシステム、それに依存して生きる私達は皆、神の下僕のような物とも言えるんですけどね" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "なるほどな……勇者は神に絶対服従なのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "その通りです、ニコラスさんを筆頭として、各地に居る勇者は全員、神によるお告げがあったらそれに従わなくてなりません" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "神に人生を操作されてるのか……なんか可哀想だな……" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "内容は例えば……ティア様もお告げを聞いたことがあるのでは?" },
  { name: "ティア", who: "tia", text: "あるわよ?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "それはどんな?" },
  { name: "ティア", who: "tia", text: "『あそこの悪人をやっつけなさい』とか『ここではこの魔法を撃ちなさい』とか……" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "聞いてるだけだと只の的確な指示だな、勇者の一挙一投足は何でもお見通しって訳か……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "良く言えば、勇者の権能の一部とも言えますね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "だな、状況に応じて最適解を神が指示してくれるんだ、活用すれば只の優秀なナビゲーションに他ならない" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "だいぶ話が逸れましたね……見えてきましたよ、あれが道路です" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ……あれか……" },
  { text: "アカツキの言う通り、視界の先に舗装された道が見えてくる。黒いアスファルトに白線が引かれ、左右どちらも馬車が通れる程度の広さがあり……" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "surprised" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "ってこれ俺の知ってる道路じゃねぇか!?" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "うぅ……ヤマト様、少し声が大きいかな……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "……悪かった、アカツキ……これはどういう……" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "ええっと……車両の通行方向って日本と海外じゃ逆なんですよね……左側と右側どちらを通れば良いんでしょう" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "そうじゃねぇ!?いやそこも気になるけども!" },
  { text: "馬車から身を乗り出し、何度も確認する。間違い無い、これは日本で見た道路だ。どういうことだ?偶然の一致?いや待て、落ち着け。俺をこの世界に転生させたのは恐らく神だ。" },
  { text: "つまり神は少なくとも俺の世界を知っていることになる。それならば神が俺達の世界の道路を知っていてもおかしな事では無い。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "取り敢えず納得した……色々驚いたけど良く考えればおかしな話ではないな……" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "もしかしたら神様は私達の世界の道路を参考にしたのかもしれませんね、光栄じゃないですか" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "あぁ……そうだな……怒鳴り散らしたから暑くなった、疲れた……" },
  { name: "エル", who: "el", expr: "smile", text: "あはは……ヤマト様、冷たい手が御所望かな?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "良い考えだ、少し寝たいしな、前のように目元に頼む" },
  { name: "エル", who: "el", expr: "smile", text: "了解、分かったよ" },
  { text: "今日という日だけで、神という存在について色々と分かり、分からなくなった気がする。そして俺はエルの魔術で冷やされた氷のような手に癒され、馬車は時代錯誤に存在する砂漠の道路を進み続けるのであった。" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { text: "やがて、教国の国境とは砂漠に長々と鎮座する城壁であった。というかこれ……万里の長城その物だ。アカツキが\"熱心な宣教師団\"と偽って交渉し、何の問題も無く入国の許可を得る。クロセルや俺が手を出すと荒事に発展しかねないからだ。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "smile" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "意外と呆気なかったな" },
  { name: "エル", who: "el", text: "同意だよ……流石はアカツキさんだね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "おかえり、ところでどうやって話を付けたんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "戻りました。私達は熱心な宣教師団と言う事にしておきました、国籍は教国という設定なので、何の問題も無く入国できるという訳です" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "良くそんな設定を通したな……" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "こういう言い方は余り良くないですが……やはりまだ国境の警備はザルみたいですね、魔王の誕生が公になる前に来れて良かったです" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "アカツキの言う通りだな、国境が閉鎖されたら嫌でも強引な手段を取らなくてはならなくなる" },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "うむ、それで教国に入ってお尋ね者になったら本末転倒であるからな" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "国境さえ越えればこっちの物だ、アカツキはお疲れ様だな" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "走り続けた甲斐がありましたね、物資も心許無いですし、取り敢えず補給に近くの街に寄りましょうか" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "そう言えば通貨は全国共通なんだな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "そうですね、両替の手間が無いので便利で助かります" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "ところで資金にはどれぐらい余裕があるんだ?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "こちらの物価が不明なので何とも言えませんが……かなり余裕はありますね、まだ何枚か黒金貨もありますし" },
  { text: "アカツキがジャラッと音を立てながら中身の入った袋を取り出して見せる。その中身は伺えないが、アカツキの言葉が確かなら相当の大金が詰まってるんだろう。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "ところで、それは魔王退治の予算なのか……?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "私のポケットマネーですよ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "ったく……そんな事だと思った" },
  { text: "人の良いこいつの事だ。それが自分の金であろうと、俺達の為に躊躇無く使っていくだろう。だが、それに甘える訳にはいかない。アカツキに養って貰うなど論外だ。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "こっちで仕事を見付けないとな" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "ヤマトさんならなんでも出来そうですよね……" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "それは買い被り過ぎだぞ、俺は無才だ。アカツキの方が何でも出来るだろ" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "否定できません……それもそうですね……" },
  { chara: { slot: "left", id: "crocell", expr: "laugh", ghost: false } },
  { name: "クロセル", who: "crocell", expr: "serious", text: "ふっふ~だがしかし!ご主人には我が付いているからな!" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "そう言えばそうだったな、こいつの手柄は俺の物だ、つまり俺は何でも出来る" },
  { name: "エル", who: "el", expr: "smile", text: "あはは……物は言いようだね……" },
  { name: "ティア", who: "tia", text: "わたしだって色々出来るわよ!ヤマトの｜魔杖《まじょう》には負けないんだから!" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ティア、残念だったな、魔術の才能はクロセルの方が上だ" },
  { name: "ティア", who: "tia", expr: "surprised", text: "えぇ!?わたしより魔術の才能があるなんて!?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "そんな驚くような事なのか……?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "クロセルさんが目覚める前はティア様が世界で一番の魔術師でしたからね" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ、なるほどな" },
  { text: "そんな風に歓談している内に、馬車は走り出す。国境の門を潜り、砂漠に敷かれた道路を走っていく。こうして俺達は教国に入った。これで魔王からは一先ず逃れられたと言って良いだろう。" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "問題は……王国だな……" },
  { name: "アカツキ", who: "akatsuki", expr: "sad", text: "これでめでたく私達は任務を放棄して逃げた大罪人ですからね……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "そういう意味でも教国は安全だな、外交を断ってるから例え王国の刺客だろうと堂々と押し入っては来れないだろ" },
  { name: "エル", who: "el", expr: "normal", text: "それに、王国は魔王の対応に追われてそれどころじゃなくなりそうだね……" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あーそれなんだが……クロセル、魔王になった際に過去の人格、記憶は完全に破壊されるんだよな?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "正確に言えば、元の人格は徐々に破壊され、やがて魔王の人格に完全に支配される。記憶に関しては魔王として不必要な部分は時間と共に封印されるが、脳の奥底には残る筈だ、我も人間であった頃の記憶が残っているからな" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "そう言えばその質問、私にもしてましたね……何か思うことがあるんですか?" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "あぁ……少しな、アカツキとクロセルじゃ言ってることが食い違ってるが……クロセルを信じて大丈夫か?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "我は元魔王だぞ?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "愚問だったな……となると……取り敢えず王国は魔王に滅ぼされる心配は無さそうだな" },
  { name: "エル", who: "el", expr: "troubled", text: "それは……どうして?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "秘密だ、というか……直に分かるだろ" },
  { text: "エルが｜訝《いぶか》しげに俺の瞳を覗き込む。なんとなく罪悪感に駆られるが、こればっかりはまだ確証を持てない仮説である故に仕方ない。まだ秘密にしておくべきだ。" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "特にアカツキには知られると面倒だからな……" },
  { name: "アカツキ", who: "akatsuki", expr: "jito", text: "ヤマトさん、何か言いました?" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "何も?" },
  { text: "アカツキは少し不満そうに唸った後に溜息を吐くと、そのまま押し黙った。俺は彼女の細やかな配慮に感謝しつつ、馬車はアスファルト舗装された道路を進んでいく。" },
  { hide: "all" },
  { text: "暫くすると、進行方向に村が見えてくる。そしてそのまま村に入っていくと、馬車は止まった。" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "normal" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "これが教国か……村ってよりはキャンプって感じだな" },
  { text: "俺はそそくさと馬車から降りて、辺りを見渡す。村と言っても、道に沿ってテントのような家屋が点在しているのみだ。王国や帝国の町村に比べると、やや原始的な風景に思える。" },
  { text: "まさしく秘境と言えるアランの村と比べれば訳ではないかもしれないが。" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "向こうにオアシスが見えますね、水には困らなそうです" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "此処に滞在するのか?" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "最低限の物資を補給したらもう少し大きな街に移りますよ、そうですね……上手く事が運べば明日には発てると思います" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "お前ずっと寝てないだろ……無茶はするなよ?" },
  { name: "アカツキ", who: "akatsuki", expr: "laugh", text: "心配して下さるのは嬉しいですが、大丈夫ですよ" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "取り敢えず今日は寝ろよ、働き過ぎて死ぬぞ" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "分かってますよ……今日はちゃんと休みますから" },
  { name: "ヤマト", who: "yamato", expr: "surprised", text: "よし、本当だな?｜言質《げんち》は取ったからな?" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "心配症ですねぇ……取り敢えず私はあの大きなテントの方に泊めて貰えるか交渉してきます、ヤマトさん達は馬車を見てて貰えますか?" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ、了解した" },
  { hide: "all" },
  { text: "アカツキを見送り、馬車の前で深呼吸をしながら天を仰ぐ。俺のような人間でも、新天地というのはワクワクする。前の世界で言う旅行の感覚だ。砂漠の砂一面の風景も、まだ目新しさを感じて見ていて飽きない。これも、過ごしている内に直に慣れてしまうのだろうが。" },
  { name: "ヤマト", who: "yamato", text: "……なんだ?" },
  { text: "暑さからか、視界が歪む。いや、おかしい。心做しか身体まで揺れている気がする。俺はしっかり眠っている筈だ、目眩など起こす理由はない。となると……" },
  { bgm: "tension" },
  { text: "だが、その矢先。鈍い音を立てながら、大地がぐらぐらと揺れた。この感覚には覚えがある、これが三度目だ。" },
  { name: "エル", who: "el", text: "ヤマト様……これは……" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "あぁ……なるほどな……そういうことか……" },
  { se: "rumble" },
  { fx: "shake" },
  { text: "酷く不快な耳鳴りがする。どうやら聞こえているのは俺だけではないらしい。クロセルは平気そうな様子だが、エルとティアは顔を顰めながら耳を抑えている。" },
  { name: "ラプラス", text: "キィィィィィィィン!えーえー、マイクテストーマイクテストー……世界中の皆様、聞こえますかー!?" },
  { chara: [
    { slot: "left", id: "el", expr: "sad" },
    { slot: "right", id: "yamato", expr: "angry" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "なんだよこれは……うるせぇなぁ……" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "この声は……" },
  { name: "エル", who: "el", expr: "troubled", text: "魔剣の悪魔さん……ですね" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "ったく、つくづく不快な奴だな" },
  { text: "これも魔王の力だろうか。全世界の人間に同時に声を送るなど、あの弱小悪魔が出来る様には思えない。どうやら遂に、魔王が目覚めたらしい。" },
  { name: "ラプラス", text: "さぁさぁ、皆様驚いていらっしゃる事でしょう、え?ボクは誰かって?そんな事はどうでも良いのです、そんなことより!全世界の皆様に、重大発表があります!さぁ、主役に登場して貰いましょう!どうぞ!" },
  { bgm: "dark" },
  { fx: "red" },
  { cg: "cg_ose_birth" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "やっぱりか……" },
  { name: "魔王オセ", text: "……やぁ、皆。僕は魔王を冠する者だ、その名も57代魔王オセ、この世界を支配する者の名だ、しかと覚えておくと良い" },
  { text: "その声は、結界も国境も飛び越えて、世界中の人間の脳裏へ直接響いていた。後に知る。この日この時、放送を聞いた全ての者が、等しく同じ怖気に背筋を撫でられたのだと。" },
  { name: "ラプラス", text: "そう!魔王様の誕生で御座います!皆様拍手~!" },
  { name: "魔王オセ", text: "よせ、僕はそういうノリは好きじゃない" },
  { name: "ラプラス", text: "あははーおっと……これは失礼、出過ぎた真似をしました" },
  { name: "魔王オセ", text: "では続きは僕が話すとしよう。これを聞く者の中には、僕を知っている人間も居るかも知れないね。そう、僕はクロム帝国の皇帝、エルク・ファルスであった者だ。聞いての通り、僕は魔王の力を継承し、新たな魔王となった" },
  { text: "聞き覚えのある皇帝の声だ。肉塊と化した所で怪物になって出てくるのかと思えば、そういう訳でもないらしい。" },
  { chara: [
    { slot: "left", id: "crocell", expr: "serious" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "クロセルの言った通りみたいだな、あいつの人格は残ってる" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "だが魔王としての衝動はある筈だぞ……目覚めた直後だから抑えていられるだけで、衝動が抑えられなくなるのも時間の問題だろう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "クロセル、今のあいつの居場所は分かるか?" },
  { name: "クロセル", who: "crocell", expr: "serious", text: "この声が魔王の権能であるとすれば……奴の居場所は魔王城だろう" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "魔王の権能が只の｜念話《ねんわ》だとは思えないな……何らかの才能の極地による物か、或いは魔術か……" },
  { name: "魔王オセ", text: "まずは僕の力をお披露目するとしよう、手始めに……アステカス公国を粛清する。拒否権は無いよ、王国や帝国に遠く及ばない弱小国家に人権は無い" },
  { name: "魔王オセ", text: "粛清が終わるまでが｜猶予《ゆうよ》期間だ、その間に皆は考えてみると良い。｜穢れ《けがれ》を受け入れ、魔王に支配される世界を望むか、魔王に逆らって惨たらしく死を迎えるか、その二択をね" },
  { name: "魔王オセ", text: "では今日の所はこの辺で。魔王に立ち向かう無謀な者は魔王城まで来ると良い、歓迎するよ。以上だ" },
  { name: "ラプラス", text: "ではこれにて閉幕と致しましょう!全世界の皆様!アデュー!" },
  { cg: null },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "やかましいのは終わったか" },
  { name: "エル", who: "el", expr: "normal", text: "……みたいだね" },
  { fx: "clear-red" },
  { chara: { slot: "right", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "最初のターゲットは公国か……まぁ妥当な所だな" },
  { chara: { slot: "left", id: "crocell", expr: "serious" } },
  { name: "クロセル", who: "crocell", expr: "surprised", text: "ご主人……本当に何もしないのか?" },
  { name: "ヤマト", who: "yamato", expr: "sad", text: "当たり前だ、俺だって命は惜しい。最も、魔王の手先になるぐらいなら死んだ方がマシだけどな" },
  { chara: { slot: "left", id: "el", expr: "normal" } },
  { name: "エル", who: "el", expr: "smile", text: "教国に居れば暫くは安全に過ごせそうだね" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "教国は衣食住を自給自足出来てるのか?" },
  { name: "エル", who: "el", expr: "smile", text: "うん、神の加護があるから痩せた土地でも作物は育つし、砂漠と言ってもあのオアシスのような水源は結構な数あるから……飢える事は無い筈だよ" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "万能だな……神の加護とやらは" },
  { name: "エル", who: "el", expr: "smile", text: "そりゃ神様だからね……" },
  { text: "魔王の放送を聞きながら、俺達は呑気にそんな会話を交わす。エルの言う通り、教国に居る限り魔王は俺達に手を出せない筈だ。俺達が無事に暮らせるならそれで良い、魔王が何をしてようと知ったことではない。" },
  { name: "ヤマト", who: "yamato", expr: "serious", text: "魔王が誕生したってのに、この村は落ち着いてるな" },
  { name: "エル", who: "el", expr: "surprised", text: "教国に居る限り安全だって分かってるからじゃないかな。神を信じていれば必ず救われる、そういう国だからね、此処は" },
  { name: "ヤマト", who: "yamato", expr: "smile", text: "なるほどな……" },
  { text: "暫く待っていると、アカツキが戻ってくる。どうやら交渉が成立したらしい。大きなテントの一つに泊めて貰えるそうだ。その日の内に何人かの村の人間と顔を合わせたが、皆揃って落ち着いていた。" },
  { text: "人の事は言えないと言え、肝の太い者ばかりだと感心しつつ、俺達はその村に滞在するのであった。" },

  // ===== シーン19: Side Story アステカス公国 (EP54) =====
  { label: "astekas_fall" },
  { fade: "out" },
  { hide: "all" },
  { bg: "burning_duchy" },
  { pov: { name: "アステカス公国", color: "#c9a45c" } },
  { fade: "in" },
  { fx: "red" },
  { text: "アステカス公国領、ある一つの街。逃げ惑う人々。｜魑魅魍魎《ちみもうりょう》の魔物の群れ。｜百鬼夜行《ひゃっきやこう》の大｜殺戮《さつりく》。魔王領から進軍してきたその軍勢は、いとも容易く一つの街を轢き滅ぼしていく。" },
  { name: "民衆", text: "うわああああああ!嫌だ!こっちに来るな!" },
  { name: "民衆", text: "誰か!戦える冒険者は居ないのか!?" },
  { name: "民衆", text: "うっ……ぐっ……どうか……貴方だけでも逃げ延びて……" },
  { name: "民衆", text: "嗚呼……神よ……どうか我らをお救い下さい……" },
  { name: "民衆", text: "こんなの……どうしようもないだろ……" },
  { fx: "shake" },
  { text: "悲鳴と｜嗚咽《おえつ》、血が飛び交う。冒険者が武器を取り、果敢に立ち向かうが、圧倒的数の差に為す術はなかった。やがて、絶望が街を支配する。逃げ惑う人々、祈る神父。" },
  { text: "そんな希望も虚しく、魔物は人を一人残さず破壊し、その身を喰らっていく。家屋は崩壊し、火の手が上がる。街は炎に包まれる。" },
  { text: "あれからどれほど経っただろうか。やがて、魔物の行進が終わる。先程まで街だった場所。そこには、何もが残らなかった。" },
  { fx: "clear-red" },
  { fade: "out" },
  { bg: "ariel_town", instant: true },
  { fade: "in" },
  { bgm: "tension" },
  { text: "時は進み、場所は公都。各地の惨状と、絶望的な現状の報告が上がってきていた。" },
  { chara: [
    { slot: "left", id: "bolt", expr: "sad" },
    { slot: "center", id: "aishi", expr: "serious" },
  ] },
  { name: "兵士", text: "魔物の軍勢は三方向より進軍。道中の街は一つ残らず……全て滅ぼされたとのこと" },
  { name: "兵士", text: "｜公主《こうしゅ》様!王国と帝国に向けた援軍要請の返答が来ました!どちらも……援護は出来ない、とのことです……" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "まぁ、そうだろうな……此処でツケが回ってきたか" },
  { name: "ボルト", who: "bolt", expr: "surprised", text: "数時間後には軍勢は公都に到達する、どうするんだ……兄さん" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "逃げる選択肢は無い、ドラゴファースト家の名に掛けて、俺は公国と運命を共にする" },
  { text: "そう高らかに言い放つ金髪の青年は。ドラゴファースト家の当主、アイシィ・ドラゴファースト。事実上、現在の公国を統べる代表者である。" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "指揮は俺が取る、公国軍の配置を見せろ" },
  { name: "兵士", text: "此方になります" },
  { name: "アイシィ", who: "aishi", expr: "sad", text: "万が一公都が落ちたら、ボルト、お前はファイを連れて教国に逃げろ" },
  { name: "ボルト", who: "bolt", expr: "surprised", text: "そんなこと出来るか!兄さんが残るなら僕も残る!" },
  { name: "アイシィ", who: "aishi", expr: "sad", text: "ダメだ。お前が生き延びればドラゴファースト家が復興するチャンスは残る、此処で俺達の守ってきたこの家を、途絶えさせる訳にはいかない" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "それに、まだ終わった訳じゃない。公都は総力を以て魔王軍を迎え撃つ。そして勝てば良いだけの話だ" },
  { name: "ボルト", who: "bolt", expr: "sad", text: "でも……" },
  { name: "ボルト", who: "bolt", expr: "sad", text: "兄さん……" },
  { name: "アイシィ", who: "aishi", expr: "surprised", text: "おかしい……相手は魔物だ、それも種族は無作為。なのに何故統制が取れている?" },
  { name: "兵士", text: "我々もそこが疑問に思っていました、魔王軍は余りにも統制が取れすぎている" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "何処かに魔物を指揮する者が居るのか?だとすれば……チャンスはある" },
  { name: "ボルト", who: "bolt", expr: "surprised", text: "どういうことですか……?" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "相手は魔物だ、指揮系統を破壊できれば、それは軍勢ではなく只の群れになる、そこを叩けば……或いはって所だ" },
  { name: "兵士", text: "なるほど……" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "考えうる限りの精鋭を集めておけ、それが恐らくこの戦いで鍵になる" },
  { name: "兵士", text: "承知しました、｜公主《こうしゅ》様" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "まだ時間はある!ボルト、冒険者を掻き集めろ!総力戦になる、戦力は一人でも多い方が良い" },
  { name: "ボルト", who: "bolt", expr: "normal", text: "分かったよ!行ってくる!" },
  { text: "戦力は圧倒的な差。有利な防衛状況下と言え、公都の死守は絶望的。そんな状況下でも、｜公主《こうしゅ》は諦めていなかった。的確な指示が飛び、一人ずつ決戦に向けて動き出す。" },
  { hide: "all" },
  { text: "一方、屋敷の外はと言えば、魔王の放送で絶望を突き付けられ、民衆は完全にパニックに陥っていた。暴れ出す人、泣き出す人、逃げ出す人、祈りを乞う人、諦めた人。多種多様な人が不安を煽り合い、そのパニックは公都の交通網に支障をきたしてきた。" },
  { text: "来たる防衛戦に向けて作業は急ピッチで進んでいく。国の命運が掛かった戦いだ、気合の入り方は並の物ではない。" },
  { text: "今は一刻も時間が惜しい。戦の準備を円滑に進める為には、まず民衆の不安を解消せねばならない。｜公主《こうしゅ》アイシィは剣を取り、席を立つ。そして向かうは……演説台であった。" },
  { chara: { slot: "center", id: "aishi", expr: "serious" } },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "皆の衆!俺だ!アイシィ・ドラゴファーストだ" },
  { name: "民衆", text: "｜公主《こうしゅ》様!" },
  { name: "民衆", text: "くそっ!何が｜公主《こうしゅ》様だ!国の一つも守れない癖に!" },
  { name: "民衆", text: "そうだ……どうせ……俺達は死ぬんだ……" },
  { text: "恐怖と不安は人を狂わせる。｜公主《こうしゅ》が発した言葉は、民衆の心には届かない。演説台に石が飛んでくる。随所で暴動が起こる。アイシィは、それに動じず言葉を続けた。" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "今!この国は最大の危機に陥っている!だからどうか!俺の言葉にどうか耳を傾けて欲しい" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "告げる!俺はこの国の領主だ!俺は逃げも隠れもしない!建国の日を思い出せ!俺は!命尽きる最後までこの国を守ると誓った!それは今も変わらない!" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "俺はこの国を守る!だからどうか!俺を信じて欲しい!今日のこの日まで!この国を導いた俺を!どうか信じてくれ!" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "公都防衛戦では他でもない俺が指揮を執る!この国に!俺に!どうか着いて来てくれないだろうか!" },
  { text: "嘘偽りない事実。ただ｜戯言《ざれごと》を吐いて民を騙すのではない。目を背けず向き合い、訴えたのだ。民が王を信じる前に、王が民を信じなくてどうするのだろうか。" },
  { text: "俺の声は必ず届く、それはアイシィにとって確信であり、やがてそれは確証へと変わる。辺りは静まり返り、やがて拍手と喝采、歓声が上がる。" },
  { text: "これは｜公主《こうしゅ》アイシィの積み上げてきた全て、人望が為した業だ。アイシィの声は遥か遠くまで届き、兵士達の士気は向上する。" },
  { chara: { slot: "right", id: "nicholas", expr: "serious" } },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "その覚悟!聞き届けた!" },
  { text: "その時、民衆の中から声が上がる。大きな声で叫んだその男は、声と同時にその手に握った刀を突き上げる。" },
  { name: "ニコラス", who: "nicholas", expr: "serious", text: "神の御告げを聞き参上した!世界の危機と聞けば駆け付ける!この僕が力を貸そう!" },
  { name: "アイシィ", who: "aishi", expr: "surprised", text: "お前は……" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "祝福の勇者だ!" },
  { name: "民衆", text: "おお!祝福の勇者ニコラス様だ!" },
  { name: "民衆", text: "神は我らを見捨てていなかった!" },
  { name: "民衆", text: "これで勝てるかもしれないぞ!" },
  { text: "黄金の鎧に身を包んだ剣士。勇者ニコラス。その人格には難ありであるが、実力は確か。間違いなく一騎当千の戦力だ。" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "神も力を貸してくださるんだ!俺が!俺達で!公国を守るぞ!" },
  { name: "民衆", text: "おおー!" },
  { text: "｜公主《こうしゅ》アイシィも勇者に合わせて剣を振り上げる。交通網の麻痺は解消され、士気は大きく向上、更に神の使いである勇者の加勢と、大きな成果を挙げられた。アイシィは満足気に頷くと、演説台を離れる。次に向かうは最前線だ。" },
  { hide: "all" },
  { chara: [
    { slot: "left", id: "bolt", expr: "normal" },
    { slot: "center", id: "aishi", expr: "serious" },
  ] },
  { name: "兵士", text: "公都防衛戦は、三方向による同時戦闘になると想定されます" },
  { name: "ボルト", who: "bolt", expr: "normal", text: "兄さん、冒険者の編入が完了したよ" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "ボルト、ご苦労だったな、魔王軍の到着まではあとどれくらいだ?" },
  { name: "ボルト", who: "bolt", expr: "sad", text: "もう間も無いかと" },
  { name: "兵士", text: "報告です!前線より遥か前方に魔物の軍勢が見えたとのこと!交戦開始は30分後と予想されます" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "やっぱり統制が取れてるだけあって進軍が早いな……戦力の配置は完了してるな?" },
  { name: "兵士", text: "既に完了、いつでもいけます" },
  { name: "アイシィ", who: "aishi", expr: "serious", text: "よし、良いか?これは防衛戦だ、敵の攻勢を凌いで時間を稼ぐ事だけを考えてくれ" },
  { name: "兵士", text: "ですが……それだけだとジリ貧では……" },
  { name: "アイシィ", who: "aishi", expr: "smile", text: "案ずるな、大丈夫だ……" },
  { text: "そう言い残すと、アイシィは前線へと向かった。あっという間に時は過ぎ、交戦が始まる。" },
  { fade: "out" },
  { hide: "all" },
  { bg: "burning_duchy", instant: true },
  { fade: "in" },
  { bgm: "resolve" },
  { fx: "shake" },
  { name: "アイシィ", text: "臆するな!俺達の公国を守るんだ!" },
  { name: "兵士", text: "うおおおおおおお!" },
  { text: "｜怒涛《どとう》の勢いで進軍してくる魔物の軍勢を、その僅か半数以下の軍勢で迎え撃つ。極限まで高まった士気と領主自らによる的確な指揮により、戦況は互角。不可能を可能にしていた。" },
  { name: "ニコラス", who: "nicholas", expr: "laugh", text: "聖剣!｜鎌矛尾羽針《かまぼこおはばり》……抜刀!僕が!僕こそが!｜抜刀斎《ばっとうさい》!だああああ!!!" },
  { text: "勇者の活躍も大きかった。軍から完全に孤立し、たった一人で戦場を駆け回り、片っ端から魔物を斬り伏せていく。その活躍はとても人の物とは思えない、まさしく戦場の鬼であった。" },
  { name: "アイシィ", text: "あれが祝福の勇者の力か……" },
  { name: "兵士", text: "本当に一人でとんでもない戦果を稼いでる……まさかこれほどとは……予想以上です……" },
  { name: "アイシィ", text: "それもただ無作為に戦ってる訳じゃない……彼の担当してる軍勢が最も死傷者が少ない。戦いながらあの大きさの軍勢を庇っている" },
  { name: "兵士", text: "まるで化け物だ……彼が味方で本当に良かった" },
  { name: "兵士", text: "祝福の勇者の加勢により戦力に大幅に余裕が出来ました" },
  { name: "アイシィ", text: "たかが一人だろ?彼一人で兵士千人分の戦力ってのは高く見積もり過ぎじゃないか……?" },
  { name: "兵士", text: "いやいや、千人なんて物じゃない。奴の実力はそれ以上だよ" },
  { text: "そんな会話を交わす前線の司令室に、一人の兵士が駆け込んでくる。" },
  { hide: "right" },
  { name: "兵士", text: "｜公主《こうしゅ》様!判明しました!魔族です!魔族が指揮を執っています" },
  { name: "アイシィ", text: "一人か?" },
  { name: "兵士", text: "はい、各軍に一人!種族は不明です" },
  { name: "アイシィ", text: "よし、用意してた精鋭部隊を送り込め、相手の指揮官を暗殺する、失敗は許されないぞ" },
  { name: "兵士", text: "分かりました" },
  { text: "事は順調に運んでいた。公国軍は見事魔王軍を食い止め、その奥に鎮座する指揮官を発見。後は敵の指揮官を討てれば、形勢は逆転する。アイシィは神妙な面持ちで目を閉じる。もし暗殺に失敗すればチャンスはない。" },
  { text: "それにしても魔族一人か……本当にそれだけであれだけの大きさの軍を統制できるのか?刻一刻と進む戦況の中、アイシィの頭にそんな疑問が浮かぶ。" },
  { se: "explosion" },
  { fx: "flash" },
  { fx: "shake" },
  { name: "兵士", text: "｜公主《こうしゅ》様!報告です!" },
  { name: "アイシィ", text: "なんだ?" },
  { name: "兵士", text: "精鋭部隊……三部隊全て……壊滅しました……" },
  { name: "アイシィ", text: "全てだと!?つまり魔族は討てなかったのか!?" },
  { name: "兵士", text: "いいえ……魔族は囮だったようで、魔族が自爆し、それに巻き込まれる形で部隊は壊滅しました" },
  { name: "アイシィ", text: "どういうことだ!それなら敵の指揮官は何処に居る!?" },
  { name: "兵士", text: "それが……何処をどう見ても、指揮官と思われる存在は見当たりません……" },
  { name: "アイシィ", text: "そんな馬鹿な……あれだけの軍勢だぞ!?指揮を執る者が居ないはずがない!" },
  { name: "兵士", text: "｜公主《こうしゅ》様!" },
  { name: "アイシィ", text: "立て続けになんだ……" },
  { name: "兵士", text: "それが……先刻敵軍の統制が強まりました、魔物達の連携に為す術無く……我が軍は劣勢です" },
  { name: "アイシィ", text: "くそっ……一体どういうことだ……" },
  { text: "アイシィは頭を抱える。あれだけ上手く事が運んでいた筈なのに、それが全て無駄に終わったのだ。見えざる指揮系統に翻弄され、もはや公国軍に逆転の目はない。ただ敗北を待つのみとなった。" },
  { name: "アイシィ", text: "……ボルト、ファイと家を……頼んだぞ" },
  { name: "ボルト", who: "bolt", expr: "sad", text: "分かったよ……兄さん" },
  { name: "アイシィ", text: "公都に避難指示を出せ、公国は……此処までだ" },
  { name: "兵士", text: "｜公主《こうしゅ》様は……" },
  { name: "アイシィ", text: "俺は最後まで戦う、着いて来る奴は着いて来い、地獄の底まで一緒だ" },
  { bgm: "sad" },
  { fx: "red" },
  { text: "公都に避難指示が出され、公国の民は再び絶望を突き付けられる。ボルトはファイを連れて教国へと逃走。アイシィは最前線へと向かった。" },
  { fx: "shake" },
  { se: "rumble" },
  { text: "それから数時間後、勇者は討たれ、最後の一人となるまで戦うも、公国軍は全滅。魔物の軍勢は公都へと｜雪崩《なだれ》込み、｜暴虐《ぼうぎゃく》の限りを尽くした。更に数時間後、公都は完全に陥落。全ては｜瓦礫《がれき》と化した。" },
  { fade: "out" },
  { fx: "clear-red" },
  { text: "――そしてその日、アステカス公国は滅びた。" },
  { pov: null },
  { jump: "ch04:arcadia_arrival" },

  /* =========================================================
     B04 分岐: 開いていた金庫を怪しむ → IF END『本物の｜石版《せきばん》』
     ========================================================= */
  { label: "b04_doubt" },
  { text: "｜石版《せきばん》に伸ばし掛けた手が、止まる。", tid: "ch03__b04_doubt__01" },
  { bgm: "mystery2" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "surprised" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "ヤマト", who: "yamato", text: "鍵を掛け忘れた金庫?……出来すぎだろ", tid: "ch03__b04_doubt__02" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "どういうことですか?", tid: "ch03__b04_doubt__03" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "前世で散々この手の罠を仕掛ける側だった俺の勘だ。あまりに都合の良い獲物には、必ず釣り針が隠れてる", tid: "ch03__b04_doubt__04" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "考えてもみろ。魔術対策までした金属製の金庫に、世界で一枚しかない｜石版《せきばん》を仕舞っておいて、鍵だけ掛け忘れる?あの用意周到な皇帝が?", tid: "ch03__b04_doubt__05" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "それに、だ。馬車の御者は殺されたのに荷物は無事、あれは明らかに\"警告\"だった。俺達が帝都に来ることは読まれていた筈なのに、この部屋まで足止めの一つも無い。……俺達は、\"泳がされてる\"", tid: "ch03__b04_doubt__06" },
  { name: "アカツキ", who: "akatsuki", expr: "serious", text: "……つまり、これは罠。この｜石版《せきばん》を、私達に\"持ち帰らせたい\"誰かが居る、と", tid: "ch03__b04_doubt__07" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "あぁ。アカツキ、その分析の才能で確かめられるか?それが本物かどうか", tid: "ch03__b04_doubt__08" },
  { text: "アカツキは｜石版《せきばん》を手に取ると、目を閉じ、深く集中する。一秒、二秒……やがて、その目が見開かれた。", tid: "ch03__b04_doubt__09" },
  { name: "アカツキ", who: "akatsuki", expr: "surprised", text: "……石材の風化具合と彫りの摩耗が一致しません。文字列は完璧ですが、これは……精巧な複製です。私が五芒星で見た物と\"同じ\"に見えたのは、当然です。あれも複製だったんですから", tid: "ch03__b04_doubt__10" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "ビンゴだ。なら本物は何処にある?お前なら分かるだろ、敏腕秘書", tid: "ch03__b04_doubt__11" },
  { name: "アカツキ", who: "akatsuki", expr: "normal", text: "要塞の構造は半日掛けて分析済みです。執務の動線から外れた不自然な空隙が一つ……皇帝の私室の、寝台の裏です", tid: "ch03__b04_doubt__12" },
  { fade: "out" },
  { hide: "all" },
  { fade: "in" },
  { label: "b04_true_tablet" },
  { text: "皇帝の私室。アカツキの空間魔術で壁を抜けると、寝台の裏の壁面に、石壁と完全に同化した隠し金庫があった。こちらは、固く施錠されている。", tid: "ch03__b04_true_tablet__01" },
  { chara: [
    { slot: "left", id: "akatsuki", expr: "serious" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "アカツキ", who: "akatsuki", text: "魔術対策は外装だけです。内部の｜蝶番《ちょうつがい》と空間を直接\"接続\"します……空間魔術……｜接続《コネクション》!", tid: "ch03__b04_true_tablet__02" },
  { se: "magic" },
  { fx: "flash" },
  { text: "空間の穴の向こうから取り出された｜石版《せきばん》は、先程の物と｜瓜二つ《うりふたつ》――だが、手にした瞬間に分かった。ずしりと重く、刻まれた魔術言語が微かに熱を持っている。", tid: "ch03__b04_true_tablet__03" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "こいつが本物か。……悪いな皇帝、絶望の舞台ってのは、脚本通りに進むから絶望なんだ", tid: "ch03__b04_true_tablet__04" },
  { name: "アカツキ", who: "akatsuki", expr: "smile", text: "複製は元の金庫に戻しておきました。私達が本物を持ち出したことには、当分気付かれません", tid: "ch03__b04_true_tablet__05" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "よし、撤収だ。これで魔王封印の儀式とやらの、本当の手順が手に入った", tid: "ch03__b04_true_tablet__06" },
  { fade: "out" },
  { hide: "all" },
  { bg: "loiton_makutsu" },
  { fade: "in" },
  { label: "b04_sealing" },
  { bgm: "tension" },
  { text: "――だが、要塞からの帰還を待っていたのは、宿の前の血溜まりだった。待機していたエルが何者かに襲われ、ティアは眠らされたまま捨て置かれていたのだ。どちらも止めは刺されていない。これも\"二度目の警告\"、奴等の脚本の一幕なのだろう。", tid: "ch03__b04_sealing__01" },
  { text: "クロセルの回復魔術でエルは一命を取り留めた。敵の思惑通りに怯えてやる義理はない。俺達は予定通り帝都を発ち、迷宮都市ロイトンへと向かった。", tid: "ch03__b04_sealing__02" },
  { text: "それから五日間、俺達は｜魔窟《まくつ》を駆け抜けた。アカツキは本物の｜石版《せきばん》を解読し、封印の儀式の全手順を頭に叩き込んだ。偽物を回収していたなら、儀式は途中で｜破綻《はたん》していただろう。あの開いた金庫は、間違いなく俺達を破滅させる為の罠だったのだ。", tid: "ch03__b04_sealing__03" },
  { text: "そして期限当日、｜魔窟《まくつ》最深部。青い炎の｜松明《たいまつ》に照らされた広間で、皇帝と黒ずくめが俺達を待ち構えていた。――だが今回は、こちらが脚本を知っている側だ。", tid: "ch03__b04_sealing__04" },
  { chara: [
    { slot: "left", id: "elk", expr: "normal" },
    { slot: "right", id: "yamato", expr: "smirk" },
  ] },
  { name: "エルク", who: "elk", text: "やぁ、良く来たね。｜石版《せきばん》は大事に持って来てくれたかな?", tid: "ch03__b04_sealing__05" },
  { name: "ヤマト", who: "yamato", text: "あぁ、勿論だ。――本物をな", tid: "ch03__b04_sealing__06" },
  { name: "エルク", who: "elk", expr: "shock", text: "……何だって?", tid: "ch03__b04_sealing__07" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "気付いてないとでも思ったか?鍵の開いた金庫、丁寧すぎる\"警告\"。お膳立てが過ぎるんだよ、お前の舞台は", tid: "ch03__b04_sealing__08" },
  { name: "エルク", who: "elk", expr: "angry", text: "馬鹿な……あの金庫の細工に気付いていたというのか……!?", tid: "ch03__b04_sealing__09" },
  { name: "ヤマト", who: "yamato", text: "前世で散々罠を仕掛けてきた俺を相手に、お粗末すぎたな。お前の未来視は、自分の知らない過去までは映してくれないんだろ?", tid: "ch03__b04_sealing__10" },
  { text: "皇帝の表情から余裕が消える。図星だったのだろう。", tid: "ch03__b04_sealing__11" },
  { bgm: "boss" },
  { fx: "shake" },
  { text: "戦闘が始まった。クロセルの氷の剣が皇帝を、勇者とエルが黒ずくめを抑え込む。そして地響きと共に、閃光が広間を白く染め上げた。魔王の復活だ。", tid: "ch03__b04_sealing__12" },
  { fx: "flash" },
  { hide: "all" },
  { chara: { slot: "center", id: "gremory", expr: "normal" } },
  { name: "グレモリー", who: "gremory", text: "……｜徒《いたずら》に我を目覚めさせた者は誰だ?", tid: "ch03__b04_sealing__13" },
  { chara: { slot: "left", id: "yamato", expr: "normal" } },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "話は後だ、魔王。お前にもう一度眠って貰う為に来た。お前を殺して成り代わろうって連中も居るが――封印なら、文句は無いな?", tid: "ch03__b04_sealing__14" },
  { name: "グレモリー", who: "gremory", expr: "sad", text: "構わん、我は平穏を望む、好きに封印すると良い", tid: "ch03__b04_sealing__15" },
  { chara: { slot: "right", id: "akatsuki", expr: "serious" } },
  { name: "アカツキ", who: "akatsuki", text: "ティア様!魔力をお借りします!儀式を始めますよ!", tid: "ch03__b04_sealing__16" },
  { bgm: "holy" },
  { text: "本物の｜石版《せきばん》に記された長大な詠唱が、アカツキとティアの声で紡がれていく。床一面に魔法陣が広がり、青い光が魔王の身体を包み込む。", tid: "ch03__b04_sealing__17" },
  { se: "magic" },
  { fx: "flash" },
  { text: "その時、闇の中から黒髪の少女が滲み出るように現れた。聖剣を携え、青い瞳をキラキラと光らせて。", tid: "ch03__b04_sealing__18" },
  { chara: { slot: "right", id: "laplace", expr: "surprised" } },
  { name: "黒髪の少女", who: "laplace", text: "あれあれ?おっかしいなぁ……｜石版《せきばん》は偽物の筈なんですけど。儀式が、成立しちゃってる?", tid: "ch03__b04_sealing__19" },
  { name: "ヤマト", who: "yamato", expr: "angry", text: "お前の仕込みなら悪いな、最初から全部疑わせて貰った", tid: "ch03__b04_sealing__20" },
  { name: "黒髪の少女", who: "laplace", expr: "sulk", text: "うわ、性格悪……ボクの完璧な脚本が台無しじゃないですか。皇帝の寿命、先払いで貰っちゃったのになぁ", tid: "ch03__b04_sealing__21" },
  { text: "悪魔は聖剣を一度だけ握り直し――やがて、興味を失ったように肩を竦めた。", tid: "ch03__b04_sealing__22" },
  { name: "黒髪の少女", who: "laplace", expr: "normal", text: "予定と違うなぁ。ま、良いです。眠る魔王を刺しても継承は起きませんし、ボクは撤収。……ヤマトさん、貴方、面白い人ですね。次の舞台では主役にしてあげます", tid: "ch03__b04_sealing__23" },
  { text: "黒髪の少女は光の粒子になって闇に溶け、黒ずくめもまた、目的を失って迷宮の奥へと姿を消した。", tid: "ch03__b04_sealing__24" },
  { fx: "flash" },
  { hide: "all" },
  { text: "封印の儀式が、完成する。魔王グレモリーの身体は静かに目を閉じ、巨大な水晶の｜柩《ひつぎ》に包まれて、広間の中央へと沈んでいった。", tid: "ch03__b04_sealing__25" },
  { text: "――魔王の再封印、成功。誰一人欠けることなく。", tid: "ch03__b04_sealing__26" },
  { fade: "out" },
  { bg: "royal_castle" },
  { fade: "in" },
  { label: "b04_hero_return" },
  { bgm: "ending" },
  { text: "王都への帰還は、英雄の｜凱旋《がいせん》となった。拘束された皇帝エルク・ファルスは王国に引き渡され、帝国は新たな執政の下で頭を垂れた。", tid: "ch03__b04_hero_return__01" },
  { chara: [
    { slot: "left", id: "raon", expr: "smile" },
    { slot: "right", id: "yamato", expr: "normal" },
  ] },
  { name: "国王", who: "raon", text: "……見事であった。｜魔杖《まじょう》にではない、ヤマト、貴殿にだ。余の目が曇っていたことを認めよう", tid: "ch03__b04_hero_return__02" },
  { name: "ヤマト", who: "yamato", expr: "smirk", text: "あんたの挑発のお陰で意地になれた、って事にしておくよ", tid: "ch03__b04_hero_return__03" },
  { name: "国王", who: "raon", expr: "smile", text: "ははは!言うようになったな。魔王の脅威は遠のき、帝国の野心も砕けた。これも全て、無才と侮られた一人の男の働きだ。誇るがいい", tid: "ch03__b04_hero_return__04" },
  { name: "ヤマト", who: "yamato", expr: "normal", text: "誇るのは性に合わないんでな。俺はただ、自分の平穏な日常を守りたかっただけだ。それがおまけで世界を救ったってだけのことさ", tid: "ch03__b04_hero_return__05" },
  { hide: "all" },
  { chara: [
    { slot: "left", id: "crocell", expr: "laugh" },
    { slot: "center", id: "yamato", expr: "smile" },
    { slot: "right", id: "el", expr: "smile" },
  ] },
  { name: "クロセル", who: "crocell", expr: "laugh", text: "ふはははは!我のご主人は英雄だぞ!もっと讃えるが良い!", tid: "ch03__b04_hero_return__06" },
  { name: "エル", who: "el", expr: "smile", text: "ふふ……良かったね、ヤマト様", tid: "ch03__b04_hero_return__07" },
  { name: "ヤマト", who: "yamato", text: "あぁ。……これで世界は救われた、めでたしめでたし、だ", tid: "ch03__b04_hero_return__08" },
  { text: "魔王は眠り、皇帝は裁かれ、悪魔は消えた。俺達は王城の一室で、騒がしくも平和な日常を取り戻した。", tid: "ch03__b04_hero_return__09" },
  { text: "教国に居るという神の正体も。青い髪の少女が俺に尽くす本当の理由も。馬車の中で見た、どうしても思い出せないあの夢の中身も。――俺は何一つ知らないまま、それでも確かに幸福な日々を、これからも生きていく。", tid: "ch03__b04_hero_return__10" },
  { text: "それはきっと、誰もが望んだ結末で。ほんの少しだけ、何かが欠けたままの世界だった。", tid: "ch03__b04_hero_return__11" },
  { fade: "out" },
  { hide: "all" },
  { jump: "ending:if_tablet" },
]);
